    #[test]
    fn root_fence_proc_fallback_refuses_and_completed_token_retains_owner() {
        let domain = crate::events::EventsDomain::test_standin(91);
        let mut child = Some(spawn("/bin/true", &[]));
        child.as_mut().unwrap().terminate_and_reap().unwrap();
        let original = child.as_ref().unwrap().pin.clone();
        child.as_mut().unwrap().pin =
            std::sync::Arc::new(PidPin::test_proc_only(child.as_ref().unwrap().pid()));
        let mut seed = Some(crate::attach::RootSeed::test_acknowledgement(
            child.as_ref().unwrap(),
            domain.clone(),
        ));
        assert!(OriginalRootExit::take(&mut child, &mut seed).is_err());
        child.as_mut().unwrap().pin = original;
        let weak = std::sync::Arc::downgrade(&child.as_ref().unwrap().pin);
        let mut seed = Some(crate::attach::RootSeed::test_acknowledgement(
            child.as_ref().unwrap(),
            domain.clone(),
        ));
        let exit = OriginalRootExit::take(&mut child, &mut seed)
            .unwrap()
            .unwrap();
        let mut tail =
            crate::events::OwnedRootTail::new(exit, Instant::now() + Duration::from_secs(1));
        let mut drain = crate::events::EventDrain::over_domain(
            crate::events::root_fence_tests::source([]),
            domain,
        );
        drain.begin_root_tail(&mut tail).unwrap();
        drain.poll_root_tail(&mut tail, 1, |_| Ok(())).unwrap();
        let completed = tail.complete().unwrap();
        drop(drain);
        assert!(weak.upgrade().is_some());
        drop(completed);
        assert!(weak.upgrade().is_none());
    }

    #[test]
    fn root_fence_settlement_retains_original_owner_after_exact_reap() {
        let mut child = spawn("/bin/true", &[]);
        child.release().unwrap();
        let fd = child.pin().pidfd().unwrap().as_raw_fd();
        let mut pending = None;
        let mut exit_code = None;
        let mut requested_kill = false;
        let mut running = false;
        let mut retained = Some(child);
        settle_owned_child(
            &mut retained,
            CaptureEnd::TargetExit,
            true,
            true,
            &SignalState::new(),
            &mut pending,
            &mut exit_code,
            &mut requested_kill,
            &mut running,
        )
        .unwrap();
        assert!(exit_code.is_some());
        // Only lifetime observation of this test's own original descriptor.
        assert_ne!(
            unsafe { libc::fcntl(fd, libc::F_GETFD) },
            -1,
            "settlement dropped the original owner before its EVENTS fence"
        );
    }

    /// An unreadable exit observation at finish invalidates the selection
    /// coverage instead of failing the run: only a proven exit after a
    /// target end closes coverage naturally, and an `Interrupted` poll
    /// from a second signal must not veto the report teardown owes.
    #[test]
    fn finish_observation_failure_invalidates_coverage_without_vetoing_finish() {
        assert!(finish_observation_natural_exit(
            CaptureEnd::TargetExit,
            Ok(true)
        ));
        for end in [
            CaptureEnd::Signal,
            CaptureEnd::DurationExpired,
            CaptureEnd::LimitReached,
            CaptureEnd::Error,
        ] {
            assert!(
                !finish_observation_natural_exit(end, Ok(true)),
                "only a target end closes coverage naturally: {end:?}"
            );
        }
        assert!(!finish_observation_natural_exit(
            CaptureEnd::TargetExit,
            Ok(false)
        ));
        for observation in [
            "cannot check whether original pid 7 exited: Interrupted system call (os error 4)",
            "original pidfd poll failed: revents=0x18",
        ] {
            assert!(
                !finish_observation_natural_exit(
                    CaptureEnd::TargetExit,
                    Err(observation.to_string())
                ),
                "an unreadable pin proves no exit: {observation}"
            );
        }
    }

    #[test]
    fn owned_disposition_records_every_capture_end_state() {
        let cases = [
            (
                "/bin/true",
                CaptureEnd::TargetExit,
                true,
                false,
                None,
                Some(0),
            ),
            (
                "/bin/sleep",
                CaptureEnd::Signal,
                true,
                false,
                Some(libc::SIGTERM),
                Some(128 + libc::SIGTERM),
            ),
            (
                "/bin/sleep",
                CaptureEnd::LimitReached,
                true,
                false,
                None,
                None,
            ),
            ("/bin/sleep", CaptureEnd::Error, true, false, None, None),
            (
                "/bin/sleep",
                CaptureEnd::DurationExpired,
                true,
                false,
                None,
                None,
            ),
            // A failed pause cleanup is an observer failure: without
            // --kill-on-timeout an expired duration hands the live child
            // back like any observer-side end, never kills it.
            (
                "/bin/sleep",
                CaptureEnd::DurationExpired,
                false,
                false,
                None,
                None,
            ),
            // With --kill-on-timeout the requested kill still lands,
            // whether or not the pause cleanup succeeded.
            (
                "/bin/sleep",
                CaptureEnd::DurationExpired,
                false,
                true,
                None,
                Some(128 + libc::SIGTERM),
            ),
            (
                "/bin/sleep",
                CaptureEnd::DurationExpired,
                true,
                true,
                None,
                Some(128 + libc::SIGTERM),
            ),
        ];

        for (program, end, cleanup_ok, kill_on_timeout, signal, expected_exit) in cases {
            let mut args = Vec::new();
            if program == "/bin/sleep" {
                args.push("10".to_string());
            }
            let mut child = spawn(
                program,
                &args.iter().map(String::as_str).collect::<Vec<_>>(),
            );
            let pid = child.pid();
            child.release().unwrap();
            if end == CaptureEnd::TargetExit {
                wait_until(
                    || !child.still_running(),
                    "target fixture never reached its exit state",
                );
            }
            let signals = SignalState::new();
            if let Some(signal) = signal {
                signals.observe(signal);
            }
            let mut pending = None;
            let mut exit_code = None;
            let mut requested_kill = false;
            let mut still_running = false;
            let mut retained = Some(child);
            settle_owned_child(
                &mut retained,
                end,
                cleanup_ok,
                kill_on_timeout,
                &signals,
                &mut pending,
                &mut exit_code,
                &mut requested_kill,
                &mut still_running,
            )
            .unwrap();
            assert_eq!(exit_code, expected_exit, "{program} {end:?}");
            assert_eq!(still_running, expected_exit.is_none(), "{program} {end:?}");
            assert_eq!(
                pending.is_some(),
                end == CaptureEnd::DurationExpired && cleanup_ok && !kill_on_timeout
            );
            if let Some(mut pending) = pending {
                assert!(pending.still_running());
                assert_eq!(pending.pid(), pid);
                pending.terminate_and_reap().unwrap();
            } else if still_running {
                // A committed handoff is no longer owned: settle the
                // survivor by PID so no case leaks a live sleeper.
                assert_eq!(
                    unsafe { libc::kill(pid as libc::pid_t, libc::SIGKILL) },
                    0,
                    "{program} {end:?}"
                );
                let mut status = 0;
                assert_eq!(
                    unsafe { libc::waitpid(pid as libc::pid_t, &mut status, 0) },
                    pid as libc::pid_t,
                    "{program} {end:?}"
                );
            }
        }
    }

    /// A requested timeout kill of a live child is a normal end: the
    /// settlement marks it so the run exits 0, while the child's own
    /// signal status stays exact for the death note. A child that
    /// already exited keeps its own status unmarked.
    #[test]
    fn requested_timeout_kill_marks_a_live_child_reaped_by_signal() {
        let signals = SignalState::new();
        // Live sleeper, timeout expiry with the kill requested: marked.
        let mut child = spawn("/bin/sleep", &["10"]);
        child.release().unwrap();
        assert!(child.still_running());
        let mut retained = Some(child);
        let mut pending = None;
        let mut exit_code = None;
        let mut requested_kill = false;
        let mut still_running = false;
        settle_owned_child(
            &mut retained,
            CaptureEnd::DurationExpired,
            true,
            true,
            &signals,
            &mut pending,
            &mut exit_code,
            &mut requested_kill,
            &mut still_running,
        )
        .unwrap();
        assert_eq!(exit_code, Some(128 + libc::SIGTERM));
        assert!(!still_running);
        assert!(
            requested_kill,
            "a requested kill of a live child must be marked"
        );
        // Exited child, same end: its own status, unmarked.
        let mut child = spawn("/bin/true", &[]);
        child.release().unwrap();
        wait_until(
            || !child.still_running(),
            "target fixture never reached its exit state",
        );
        let mut retained = Some(child);
        let mut pending = None;
        let mut exit_code = None;
        let mut requested_kill = false;
        let mut still_running = false;
        settle_owned_child(
            &mut retained,
            CaptureEnd::DurationExpired,
            true,
            true,
            &signals,
            &mut pending,
            &mut exit_code,
            &mut requested_kill,
            &mut still_running,
        )
        .unwrap();
        assert_eq!(exit_code, Some(0));
        assert!(!still_running);
        assert!(
            !requested_kill,
            "a child that exited on its own keeps its status unmarked"
        );
    }

    /// A child that answers the timeout SIGTERM by voluntarily exiting
    /// with a high status keeps its own status unmarked: only a death
    /// by the observer's signal is a requested kill, never a voluntary
    /// exit, however high its code.
    #[test]
    fn requested_timeout_kill_must_not_claim_a_voluntary_high_exit() {
        let signals = SignalState::new();
        let mut child = spawn("/bin/sh", &["-c", "trap 'exit 200' TERM; sleep 10"]);
        child.release().unwrap();
        // Let the shell install its TERM trap and start sleeping, so the
        // timeout SIGTERM below answers with a voluntary exit, not a race
        // against startup.
        std::thread::sleep(Duration::from_millis(500));
        assert!(child.still_running());
        let mut retained = Some(child);
        let mut pending = None;
        let mut exit_code = None;
        let mut requested_kill = false;
        let mut still_running = false;
        settle_owned_child(
            &mut retained,
            CaptureEnd::DurationExpired,
            true,
            true,
            &signals,
            &mut pending,
            &mut exit_code,
            &mut requested_kill,
            &mut still_running,
        )
        .unwrap();
        assert_eq!(exit_code, Some(200));
        assert!(!still_running);
        assert!(
            !requested_kill,
            "a voluntary exit keeps its status unmarked even above 128"
        );
    }

    /// A child killed from outside the observer keeps its real signal
    /// status unmarked: an external SIGKILL stays exit 137 and an
    /// external SIGTERM stays exit 143, neither claimed as a requested
    /// timeout kill. The initial probe reaps both before the observer
    /// sends any signal of its own.
    #[test]
    fn requested_timeout_kill_must_not_claim_an_externally_killed_child() {
        for (signal, want) in [
            (libc::SIGKILL, 128 + libc::SIGKILL),
            (libc::SIGTERM, 128 + libc::SIGTERM),
        ] {
            let signals = SignalState::new();
            let mut child = spawn("/bin/sleep", &["10"]);
            let pid = child.pid();
            child.release().unwrap();
            assert!(child.still_running());
            // SAFETY: signals the exact owned child only, from outside
            // the observer's own settlement path; the pid cannot be
            // reused while the child is unreaped.
            assert_eq!(unsafe { libc::kill(pid as libc::pid_t, signal) }, 0);
            wait_until(
                || !child.still_running(),
                "externally killed fixture never reported dead",
            );
            let mut retained = Some(child);
            let mut pending = None;
            let mut exit_code = None;
            let mut requested_kill = false;
            let mut still_running = false;
            settle_owned_child(
                &mut retained,
                CaptureEnd::DurationExpired,
                true,
                true,
                &signals,
                &mut pending,
                &mut exit_code,
                &mut requested_kill,
                &mut still_running,
            )
            .unwrap();
            assert_eq!(exit_code, Some(want));
            assert!(!still_running);
            assert!(
                !requested_kill,
                "an external signal death keeps its status unmarked"
            );
        }
    }

    /// The run's process exit code: a requested timeout kill and a
    /// handed-back child are observer success; otherwise the child's
    /// own status, as a shell would report it.
    #[test]
    fn run_exit_code_maps_requested_kills_and_handoffs_to_success() {
        let outcome =
            |child_exit_code: Option<i32>, requested_timeout_kill: bool| OwnedRunOutcome {
                child_exit_code,
                requested_timeout_kill,
                child_still_running: child_exit_code.is_none(),
                child_pid: 4242,
                error_handoff: false,
                evidence: render::tests::evidence(),
            };
        assert_eq!(
            outcome(Some(128 + libc::SIGTERM), true).exit_code(),
            0,
            "a requested timeout kill is a normal end"
        );
        assert_eq!(
            outcome(None, false).exit_code(),
            0,
            "a handed-back child stays success"
        );
        assert_eq!(outcome(Some(0), false).exit_code(), 0);
        assert_eq!(outcome(Some(1), false).exit_code(), 1);
        assert_eq!(
            outcome(Some(128 + libc::SIGTERM), false).exit_code(),
            128 + libc::SIGTERM,
            "an unrequested signal death keeps the child's status"
        );
    }

