    #[test]
    fn run_tree_unretained_child_degrades_only_cgroup_scope() {
        let cgroup = crate::attach::Scope::Cgroup {
            id: 1,
            path: "/".into(),
            dir: std::sync::Arc::new(std::fs::File::open("/").unwrap()),
        };
        assert_eq!(
            super::run_tree_unretained_gap(&cgroup, false),
            Some(crate::render::RUN_TREE_DEGRADED)
        );
        assert_eq!(super::run_tree_unretained_gap(&cgroup, true), None);
        assert_eq!(
            super::run_tree_unretained_gap(&crate::attach::Scope::Pid(4242), false),
            None
        );
        assert_eq!(
            super::run_tree_unretained_gap(&crate::attach::Scope::System, true),
            None
        );
    }

    #[test]
    fn run_tree_scope_or_exact_degrades_off_a_non_cgroup_dir() {
        // A placed group that is not a cgroup v2 scope (here tmpfs)
        // falls back to the exact child PID with the scope-build gap;
        // the group is retired for cleanup-only (it may still hold the
        // placed child) and its dir goes once the holder drops.
        let base = tempfile::tempdir().unwrap();
        let group = crate::scope::RunCgroup::create(base.path()).unwrap();
        let path = group.path().to_path_buf();
        let (scope, active, retired, gap) = super::run_tree_scope_or_exact(4242, group);
        assert!(
            matches!(scope, crate::attach::Scope::Pid(pid) if pid == 4242),
            "degraded scope names the child exactly"
        );
        assert!(active.is_none(), "no active group on the exact path");
        let retired = retired.expect("the placed group is retired for cleanup");
        assert_eq!(retired.path(), path, "the retired group is the placed one");
        let reason = gap.expect("the scope-build gap is named");
        assert_eq!(
            reason,
            crate::render::RUN_TREE_DEGRADED,
            "the scope-build gap is finite vocabulary; the step prints on stderr"
        );
        assert!(
            path.exists(),
            "the retired dir survives until its holder drops"
        );
        drop(retired);
        assert!(!path.exists(), "dropping the retired group removes the dir");
    }

    #[test]
    fn run_tree_survivors_gap_names_handed_back_members() {
        assert_eq!(
            super::run_tree_survivors_gap(Ok(0)),
            (Some(0), None),
            "an empty tree at run end is a measured zero, not a gap"
        );
        // The gap reasons are finite vocabulary (schema v3): the count
        // rides beside the reason in `run_tree_handed_back`, never in it.
        for survivors in [1, 3] {
            assert_eq!(
                super::run_tree_survivors_gap(Ok(survivors)),
                (
                    Some(survivors),
                    Some(crate::render::RUN_TREE_SURVIVORS.to_string())
                )
            );
        }
        let (count, gap) = super::run_tree_survivors_gap(Err(std::io::Error::new(
            std::io::ErrorKind::NotFound,
            "cgroup.procs",
        )));
        assert_eq!(count, None, "an unread membership is unknown, never zero");
        assert_eq!(
            gap.as_deref(),
            Some(crate::render::RUN_TREE_MEMBERSHIP_UNKNOWN)
        );
    }

    /// I1: a quiesce failure after `--duration` without
    /// `--kill-on-timeout` settles with the loop's real end, so the live
    /// child is handed back (never reaped, and never SIGKILLed by a skipped
    /// settlement's `Drop`). A failed loop settles through the same
    /// observer-side handoff. The real `settle_owned_child` runs behind the
    /// combiner with a real sleeper child.
    #[test]
    fn quiesce_error_after_duration_expiry_hands_back_the_living_child() {
        for loop_failed in [false, true] {
            let mut child = spawn("/bin/sleep", &["10"]);
            let pid = child.pid();
            child.release().unwrap();
            let signals = SignalState::new();
            let mut retained = Some(child);
            let mut pending = None;
            let mut exit_code = None;
            let mut requested_kill = false;
            let mut still_running = false;
            let mut detached = false;
            let published = std::cell::Cell::new(false);
            let loop_result: Result<CaptureEnd> = if loop_failed {
                Err(anyhow::anyhow!("loop failure"))
            } else {
                Ok(CaptureEnd::DurationExpired)
            };
            let error = finish_quiesce_error(
                anyhow::anyhow!("quiesce failure"),
                loop_result,
                &mut (),
                |_| {},
                |_, end| {
                    settle_owned_child(
                        &mut retained,
                        end,
                        true,
                        false,
                        &signals,
                        &mut pending,
                        &mut exit_code,
                        &mut requested_kill,
                        &mut still_running,
                    )
                    .map(|_| ())
                },
                |_| {
                    published.set(true);
                    Ok(())
                },
                |_| {
                    detached = true;
                    Ok(())
                },
            );
            assert!(detached, "loop_failed={loop_failed}");
            // Every settled end publishes from partial state, a failed
            // loop included: the report names what is unknown.
            assert!(published.get(), "loop_failed={loop_failed}");
            let message = format!("{error:#}");
            if loop_failed {
                assert!(
                    message.contains("loop failure") && message.contains("quiesce failure"),
                    "either error dropped: {message}"
                );
                // An Error settlement hands the live child back, never
                // kills it; the handoff commits, so nothing stays pending.
                assert_eq!(exit_code, None);
                assert!(still_running);
                assert!(pending.is_none());
                assert!(retained.is_none());
                assert_eq!(
                    unsafe { libc::kill(pid as libc::pid_t, libc::SIGKILL) },
                    0,
                    "the failed loop killed the observed program"
                );
                let mut status = 0;
                assert_eq!(
                    unsafe { libc::waitpid(pid as libc::pid_t, &mut status, 0) },
                    pid as libc::pid_t
                );
            } else {
                assert_eq!(message, "quiesce failure");
                assert_eq!(exit_code, None);
                assert!(still_running);
                let mut pending = pending.expect("the live child must be handed back");
                assert_eq!(pending.pid(), pid);
                assert!(pending.still_running());
                pending.terminate_and_reap().unwrap();
            }
        }
    }

    /// A quiesce failure behind a failed loop still seals what was
    /// captured, whatever ended the capture (a signal, the child's own
    /// exit, a failed live tick): calls happened, so the view shows
    /// them and names the failed loop as a gap filed before the seal.
    /// Both errors stay in the chain.
    #[test]
    fn quiesce_error_behind_a_failed_loop_still_publishes() {
        let gap = std::cell::Cell::new(false);
        let published = std::cell::Cell::new(false);
        let error = finish_quiesce_error(
            anyhow::anyhow!("terminal quiescence failed"),
            Err(anyhow::anyhow!("loop failure")),
            &mut (),
            |_| gap.set(true),
            |_, _| Ok(()),
            |_| {
                assert!(gap.get(), "the loop gap must be filed before the seal");
                published.set(true);
                Ok(())
            },
            |_| Ok(()),
        );
        assert!(
            published.get(),
            "a failed loop must still publish: {error:#}"
        );
        let message = format!("{error:#}");
        assert!(
            message.contains("loop failure") && message.contains("terminal quiescence"),
            "either error dropped: {message}"
        );
    }

    /// Healthy handoff twin: the step succeeds, so its full report
    /// publishes and the outcome is success. Control for the failure
    /// twin below: the seam publishes on both arms.
    #[test]
    fn owned_handoff_healthy_twin_publishes() {
        let full = std::cell::Cell::new(false);
        let outcome = drive_owned_handoff_with(
            &mut (),
            |_| Ok(()),
            |_| panic!("a healthy handoff files no gap"),
            |_| panic!("a healthy handoff settles in the capture loop, not here"),
            |_| {
                full.set(true);
                Ok(())
            },
            |_| panic!("a healthy handoff never seals a partial report"),
            |_| panic!("a healthy handoff detaches after the loop, not here"),
        );
        outcome.expect("a healthy handoff succeeds");
        assert!(full.get(), "the healthy twin must publish its report");
    }

    /// Failure handoff twin: the step fails after probes attached, so a
    /// partial report naming the failed step still seals from whatever
    /// was captured, and the original error returns the run nonzero.
    /// Settlement still runs first and producers still detach.
    #[test]
    fn owned_handoff_failure_twin_publishes_partial_and_returns_err() {
        let gap = std::cell::Cell::new(false);
        let settled = std::cell::Cell::new(false);
        let published = std::cell::Cell::new(false);
        let detached = std::cell::Cell::new(false);
        let outcome = drive_owned_handoff_with(
            &mut (),
            |_| Err(anyhow::anyhow!("run: exec handoff cancelled")),
            |_| gap.set(true),
            |_| {
                assert!(gap.get(), "the handoff gap must be filed before settlement");
                settled.set(true);
                Ok(())
            },
            |_| panic!("a failed handoff never publishes a full report"),
            |_| {
                assert!(settled.get(), "settlement gates the partial seal");
                published.set(true);
                Ok(())
            },
            |_| {
                detached.set(true);
                Ok(())
            },
        );
        let error = outcome.expect_err("a failed handoff must still fail the run");
        assert!(gap.get(), "the failed step must file its named gap");
        assert!(settled.get(), "the child must still settle");
        assert!(
            published.get(),
            "a failed handoff must still publish its partial report: {error:#}"
        );
        assert!(detached.get(), "producers must still detach");
        assert!(
            format!("{error:#}").contains("exec handoff cancelled"),
            "the original error must stay the outer error: {error:#}"
        );
    }

    /// The handoff seals file their gaps straight into
    /// `evidence.skipped[]`, past the discovery sanitizer — so every
    /// handoff reason must be a member of the published schema's closed
    /// reason enum, or every handoff `-o` JSON is schema-invalid output.
    #[test]
    fn owned_handoff_gap_reasons_are_schema_reasons() {
        let path = concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/docs/schema/observed-profile-v3.schema.json"
        );
        let schema: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
        let allowed: Vec<&str> = schema
            .pointer("/properties/evidence/properties/skipped/items/properties/reason/enum")
            .expect("the schema names its skip reasons")
            .as_array()
            .expect("skip reasons are an enum")
            .iter()
            .map(|reason| reason.as_str().expect("a skip reason is a string"))
            .collect();
        for reason in [
            HANDOFF_REASON_STEP_PROFILE,
            HANDOFF_REASON_STEP_TRACE,
            HANDOFF_REASON_IDENTITY,
            HANDOFF_REASON_TAIL_RETIRE,
            HANDOFF_REASON_TAIL_CANCELLED,
            HANDOFF_REASON_TAIL_DEADLINE,
            HANDOFF_REASON_TAIL_DRAIN,
            HANDOFF_REASON_EVENTS_DRAIN,
            HANDOFF_REASON_EVENTS_OPEN,
            HANDOFF_REASON_COUNTER,
            HANDOFF_REASON_RING_LOSS,
            HANDOFF_REASON_KERNEL,
        ] {
            assert!(
                allowed.contains(&reason),
                "{reason:?} is not a schema skip reason"
            );
        }
    }

    /// Each handoff seal files its own step sentence: the profile seal
    /// says the report holds the capture, the trace seal says the trace
    /// holds it. Swapping the two constants between the seals reddens
    /// this test; the schema-membership pin above cannot see that swap.
    #[test]
    fn owned_handoff_step_reason_matches_its_seal() {
        let source = include_str!("run.rs");
        let production = source.split_once("#[cfg(test)]\nmod tests").unwrap().0;
        let profile = production
            .split_once("fn seal_owned_handoff_profile(")
            .expect("profile handoff seal")
            .1
            .split_once("fn seal_owned_handoff_trace(")
            .expect("profile handoff seal end")
            .0;
        let trace = production
            .split_once("fn seal_owned_handoff_trace(")
            .expect("trace handoff seal")
            .1
            .split_once("fn finish_capture_loop(")
            .expect("trace handoff seal end")
            .0;
        assert!(
            profile.contains("HANDOFF_REASON_STEP_PROFILE"),
            "the profile seal must file the report sentence"
        );
        assert!(
            !profile.contains("HANDOFF_REASON_STEP_TRACE"),
            "the profile seal must not file the trace sentence"
        );
        assert!(
            trace.contains("HANDOFF_REASON_STEP_TRACE"),
            "the trace seal must file the trace sentence"
        );
        assert!(
            !trace.contains("HANDOFF_REASON_STEP_PROFILE"),
            "the trace seal must not file the report sentence"
        );
    }

    /// The trace handoff seal drains the reaped child's tail the way the
    /// profile seal does: tail events at handoff stream through the trace
    /// reducer ahead of the EVENTS drain, a completed tail retires, and
    /// every other outcome files its named gap — never silently lost.
    /// Deleting any outcome arm, or draining the tail after EVENTS,
    /// reddens this test.
    #[test]
    fn owned_handoff_trace_seal_drains_the_original_root_tail() {
        let source = include_str!("run.rs");
        let production = source.split_once("#[cfg(test)]\nmod tests").unwrap().0;
        let seal = production
            .split_once("fn seal_owned_handoff_trace(")
            .expect("trace handoff seal")
            .1
            .split_once("fn finish_capture_loop(")
            .expect("trace handoff seal end")
            .0;
        assert!(
            seal.contains("drain_original_root_events("),
            "the trace handoff seal must drain the reaped child's tail"
        );
        assert!(
            seal.contains("apply_original_root_retirement("),
            "a completed tail must retire its processes"
        );
        let tail = seal
            .find("drain_original_root_events(")
            .expect("the tail drain call");
        let events = seal.find("drain_trace_events(").expect("the EVENTS drain");
        assert!(
            tail < events,
            "the tail must drain ahead of the EVENTS ring, as the terminal path does"
        );
        assert!(
            seal.contains("OriginalRootDrain::Cancelled"),
            "the seal must handle a cancelled tail drain"
        );
        assert!(
            seal.contains("HANDOFF_REASON_TAIL_CANCELLED"),
            "a cancelled tail must file its named gap"
        );
        assert!(
            seal.contains("HANDOFF_REASON_TAIL_DRAIN"),
            "a failed tail drain must file its named gap"
        );
        assert!(
            seal.contains("HANDOFF_REASON_TAIL_RETIRE"),
            "a failed tail retirement must file its named gap"
        );
    }

    /// Both handoff seals handle the root-tail deadline abandon in its own
    /// arm: the deadline reason (never relabeled as a cancellation) and the
    /// `deadline` stderr token, while the cancelled arm keeps its own
    /// reason. Deleting either deadline arm, or filing the cancelled
    /// reason in it, fails here.
    #[test]
    fn owned_handoff_seals_file_the_tail_deadline_in_its_own_arm() {
        let source = include_str!("run.rs");
        let production = source.split_once("#[cfg(test)]\nmod tests").unwrap().0;
        let window = |start: &str, end: &str| -> &'static str {
            production
                .split_once(start)
                .unwrap_or_else(|| panic!("missing {start}"))
                .1
                .split_once(end)
                .unwrap_or_else(|| panic!("missing end {end}"))
                .0
        };
        let arm = |seal: &'static str, variant: &str| -> &'static str {
            let head = format!("Ok(OriginalRootDrain::{variant} {{");
            let (_, rest) = seal
                .split_once(head.as_str())
                .unwrap_or_else(|| panic!("the seal lost its {variant} arm"));
            let next = ["Ok(OriginalRootDrain::", "Err("]
                .iter()
                .filter_map(|marker| rest.find(marker))
                .min()
                .expect("a following arm");
            &rest[..next]
        };
        for (mode, seal) in [
            (
                "profile",
                window(
                    "fn seal_owned_handoff_profile(",
                    "\nfn seal_owned_handoff_trace(",
                ),
            ),
            (
                "trace",
                window("fn seal_owned_handoff_trace(", "fn finish_capture_loop("),
            ),
        ] {
            assert_eq!(
                seal.matches("OriginalRootDrain::DeadlineAbandoned").count(),
                1,
                "{mode}: one deadline arm"
            );
            let deadline = arm(seal, "DeadlineAbandoned");
            assert!(
                deadline.contains("reason: HANDOFF_REASON_TAIL_DEADLINE")
                    && !deadline.contains("HANDOFF_REASON_TAIL_CANCELLED"),
                "{mode}: the deadline arm files the deadline reason"
            );
            assert!(
                deadline.contains("root_tail_incomplete: deadline;")
                    && deadline.contains("name: HANDOFF_GAP_ORIGINAL_ROOT_TAIL"),
                "{mode}: the deadline arm names itself under the tail subject"
            );
            let cancelled = arm(seal, "Cancelled");
            assert!(
                cancelled.contains("reason: HANDOFF_REASON_TAIL_CANCELLED")
                    && !cancelled.contains("HANDOFF_REASON_TAIL_DEADLINE"),
                "{mode}: the cancelled arm keeps the cancelled reason"
            );
        }
    }

    /// The handoff failure happens before any loop starts, so its gap
    /// names the failed handoff step — never the capture loop.
    #[test]
    fn owned_handoff_gap_names_the_step_not_the_loop() {
        let source = include_str!("run.rs");
        let production = source.split_once("#[cfg(test)]\nmod tests").unwrap().0;
        let seal = production
            .split_once("fn finish_owned_handoff_error(")
            .expect("handoff error seal")
            .1
            .split_once("fn seal_owned_handoff_partial(")
            .expect("handoff error seal end")
            .0;
        assert!(
            seal.contains("note_handoff_failure("),
            "the handoff gap must name the failed step"
        );
        assert!(
            !seal.contains("note_capture_loop_failure()"),
            "no loop ever ran at handoff"
        );
    }

    /// The engine loss for a handoff failure carries the seal's own
    /// sentence: a profile handoff says the report holds the capture,
    /// a trace handoff says the trace holds it. Swapping the match
    /// arms reddens this test.
    #[test]
    fn owned_handoff_failure_passes_its_kind_sentence() {
        let source = include_str!("run.rs");
        let production = source.split_once("#[cfg(test)]\nmod tests").unwrap().0;
        let seal = production
            .split_once("fn finish_owned_handoff_error(")
            .expect("handoff error seal")
            .1
            .split_once("fn seal_owned_handoff_partial(")
            .expect("handoff error seal end")
            .0;
        assert!(
            seal.contains("Kind::Profile => HANDOFF_REASON_STEP_PROFILE"),
            "a profile handoff must record the report sentence"
        );
        assert!(
            seal.contains("Kind::Trace => HANDOFF_REASON_STEP_TRACE"),
            "a trace handoff must record the trace sentence"
        );
    }

    /// Settlement-failure twin: when settlement itself fails, no partial
    /// report publishes here (the child's disposition is unknown, and the
    /// settlement-gate lane owns that report), producers still detach,
    /// and the original handoff error returns the run nonzero.
    #[test]
    fn owned_handoff_settlement_failure_skips_publication() {
        let gap = std::cell::Cell::new(false);
        let settled = std::cell::Cell::new(false);
        let published = std::cell::Cell::new(false);
        let detached = std::cell::Cell::new(false);
        let outcome = drive_owned_handoff_with(
            &mut (),
            |_| Err(anyhow::anyhow!("run: exec handoff cancelled")),
            |_| gap.set(true),
            |_| {
                settled.set(true);
                Err(anyhow::anyhow!(
                    "run: settling the original child: test-forced"
                ))
            },
            |_| panic!("a failed handoff never publishes a full report"),
            |_| {
                published.set(true);
                Ok(())
            },
            |_| {
                detached.set(true);
                Ok(())
            },
        );
        let error = outcome.expect_err("a failed handoff must still fail the run");
        assert!(gap.get(), "the failed step must file its named gap");
        assert!(settled.get(), "settlement must still run");
        assert!(
            !published.get(),
            "a failed settlement must skip publication here"
        );
        assert!(detached.get(), "producers must still detach");
        let message = format!("{error:#}");
        assert!(
            message.contains("exec handoff cancelled"),
            "the original error must stay the outer error: {message}"
        );
        assert!(
            message.contains("settling the original child"),
            "the settlement failure must be retained: {message}"
        );
    }

    /// The four owned-handoff failure sites (pause-arm lifecycle,
    /// pause-arm retire, exec barrier release, post-release
    /// revalidation) seal through the handoff helper, never a bare
    /// settlement without publication. Each arm is pinned individually:
    /// reverting any one arm to the bare settlement reddens this test.
    #[test]
    fn owned_handoff_failures_seal_a_partial_report() {
        let source = include_str!("run.rs");
        let production = source.split_once("#[cfg(test)]\nmod tests").unwrap().0;
        let handoff = production
            .split_once("fn run_owned_inner_with_host(")
            .expect("owned startup")
            .1
            .split_once("fn preflight_uretprobe_hazard(")
            .expect("owned startup end")
            .0;
        assert!(
            handoff.contains("finish_owned_handoff_error("),
            "handoff failures must seal a partial report"
        );
        assert_eq!(
            handoff.matches("finish_owned_handoff_error(").count(),
            4,
            "pause-arm lifecycle, pause-arm retire, release and revalidation sites must all seal"
        );
        assert!(
            !handoff.contains("finish_capture_error("),
            "no handoff arm may settle without sealing its partial report"
        );
        for (step, want) in [
            ("HANDOFF_STEP_PAUSE_ARM", 2),
            ("HANDOFF_STEP_EXEC", 1),
            ("HANDOFF_STEP_POST_RELEASE", 1),
        ] {
            assert_eq!(
                handoff.matches(step).count(),
                want,
                "{step} must name its handoff arm"
            );
        }
    }

    /// A poisoned terminal discovery batch degrades to the recorded gap
    /// with the committed plan at any stop (a signal, the child's own
    /// exit, the duration): calls happened, so the report is sealed
    /// with the named gap instead of ending the view with no document.
    #[test]
    fn terminal_discovery_failure_degrades_to_a_gap() {
        let gap = std::cell::Cell::new(false);
        let changed = seal_terminal_discovery_or_gap(
            || gap.set(true),
            || Err(anyhow::anyhow!("slot 0 refers to unknown candidate module")),
        );
        assert!(gap.get(), "the failure must file its named gap");
        assert!(changed.unwrap(), "the seal syncs to the committed plan");
    }

    /// An exec failure names the errno in words, so a script the
    /// target account cannot reach reads `Permission denied`.
    #[test]
    fn exec_failure_names_the_errno_text() {
        let failure = ExecFailure {
            errno: libc::EACCES,
            exit_code: 127,
        };
        assert_eq!(
            failure.to_string(),
            "exec failed with errno 13 (Permission denied) and exit status 127"
        );
    }

    #[test]
    fn signal_observed_before_handoff_rejects_the_handoff_boundary() {
        let signals = SignalState::new();
        signals.observe(libc::SIGTERM);
        assert!(!signals.claim_handoff());
    }

    #[test]
    fn path_absolute_shebang_retarget_and_exec_chain_prearm_classification_is_conservative() {
        let path = PreparedExecutable::resolve("sh".as_ref()).unwrap().unwrap();
        assert!(path.path().is_absolute());
        let _: &Path = path.interpreter();
        assert!(path.interpreter_file().metadata().is_ok());
        assert!(path.unchanged().unwrap());
        assert!(
            PreparedExecutable::resolve("/bin/sh".as_ref())
                .unwrap()
                .is_some()
        );

        let directory = tempfile::tempdir().unwrap();
        let script = directory.path().join("script");
        std::fs::write(&script, "#!/bin/sh\nexit 0\n").unwrap();
        let mut permissions = std::fs::metadata(&script).unwrap().permissions();
        permissions.set_mode(0o700);
        std::fs::set_permissions(&script, permissions).unwrap();
        assert!(
            PreparedExecutable::resolve(script.as_os_str())
                .unwrap()
                .is_none()
        );

        let target = directory.path().join("target");
        std::fs::copy("/bin/true", &target).unwrap();
        let pinned = PreparedExecutable::resolve(target.as_os_str())
            .unwrap()
            .unwrap();
        let replacement = directory.path().join("replacement");
        std::fs::copy("/bin/false", &replacement).unwrap();
        std::fs::rename(&replacement, &target).unwrap();
        assert!(
            !pinned.unchanged().unwrap(),
            "a retargeted path must not pre-arm"
        );

        let sleeper_dir = tempfile::tempdir().unwrap();
        let sleeper = build_sleeper(sleeper_dir.path());
        let sleeper = sleeper.to_str().unwrap();
        let mut direct = spawn(sleeper, &[]);
        direct.release().unwrap();
        assert!(direct.revalidate_after_exec().unwrap());
        direct.terminate_and_reap().unwrap();

        let mut chain = spawn("/bin/sh", &["-c", "exec /bin/sleep 1"]);
        chain.release().unwrap();
        let sleep_path = std::fs::canonicalize("/bin/sleep").unwrap();
        wait_until(
            || {
                std::fs::read_link(format!("/proc/{}/exe", chain.pid()))
                    .is_ok_and(|path| path == sleep_path)
            },
            "the shell never completed its second exec",
        );
        assert!(!chain.revalidate_after_exec().unwrap());
        chain.terminate_and_reap().unwrap();
    }

    /// Hermetic long-running child: this host's `/bin/sleep` is a uutils
    /// multicall shim that dispatches on AT_EXECFN, which fd-pinned exec
    /// (`execveat` + `AT_EMPTY_PATH`) leaves as an fd-based name — so it
    /// exits 1 with "unknown program" under the harness while GNU sleep
    /// elsewhere survives. Duration/settle tests need a child that simply
    /// lives until signalled, independent of host coreutils.
    fn build_sleeper(dir: &std::path::Path) -> std::path::PathBuf {
        build_sleeper_source(
            dir,
            "#include <unistd.h>\nint main(void) { for (;;) sleep(60); return 0; }\n",
        )
    }

    /// The same sleeper with a self-imposed lifetime: `alarm` ends it
    /// after `seconds` even if every test-side cleanup was skipped (the
    /// test binary itself SIGKILLed), so a probe that deliberately runs
    /// without the test-death backstop leaves minutes, not days, of residue.
    fn build_bounded_sleeper(dir: &std::path::Path, seconds: u32) -> std::path::PathBuf {
        build_sleeper_source(
            dir,
            &format!(
                "#include <unistd.h>\nint main(void) {{ alarm({seconds}); for (;;) sleep(60); return 0; }}\n"
            ),
        )
    }

    fn build_sleeper_source(dir: &std::path::Path, text: &str) -> std::path::PathBuf {
        let source = dir.join("sleeper.c");
        let binary = dir.join("sleeper");
        std::fs::write(&source, text).unwrap();
        assert!(
            std::process::Command::new("gcc")
                .args(["-O0", "-o"])
                .arg(&binary)
                .arg(&source)
                .status()
                .unwrap()
                .success()
        );
        binary
    }

    #[test]
    fn duration_and_forwarded_signals_have_one_owned_cleanup_route() {
        let fixture_dir = tempfile::tempdir().unwrap();
        let sleeper = build_sleeper(fixture_dir.path());
        let sleeper = sleeper.to_str().unwrap();
        let mut running = spawn(sleeper, &[]);
        running.release().unwrap();
        assert_eq!(
            running
                .wait_for(Some(Duration::from_millis(10)), false)
                .unwrap(),
            ChildOutcome::TimedOutRunning
        );
        assert!(running.still_running());
        running
            .terminate_with_grace(Duration::from_millis(10))
            .unwrap();
        assert!(running.is_reaped());

        let directory = tempfile::tempdir().unwrap();
        let ready = directory.path().join("interrupt-ready");
        let mut interrupted = spawn(
            "/bin/sh",
            &[
                "-c",
                &format!(
                    "trap '' INT; : > {}; while :; do sleep 1; done",
                    ready.display()
                ),
            ],
        );
        interrupted.release().unwrap();
        wait_until(
            || ready.exists(),
            "the SIGINT fixture never installed its trap",
        );
        assert_eq!(
            interrupted.forward_signal(libc::SIGINT).unwrap(),
            ForwardAction::Forwarded
        );
        assert_eq!(
            interrupted.forward_signal(libc::SIGINT).unwrap(),
            ForwardAction::Escalated
        );
        assert_eq!(
            interrupted.wait_for(None, false).unwrap(),
            ChildOutcome::Exited(128 + libc::SIGKILL)
        );

        let mut terminated = spawn("/bin/sleep", &["10"]);
        terminated.release().unwrap();
        assert_eq!(
            terminated.forward_signal(libc::SIGTERM).unwrap(),
            ForwardAction::Forwarded
        );
        assert_eq!(
            terminated.wait_for(None, false).unwrap(),
            ChildOutcome::Exited(128 + libc::SIGTERM)
        );

        let term_ready = directory.path().join("term-ready");
        let mut term_ignoring = spawn(
            "/bin/sh",
            &[
                "-c",
                &format!(
                    "trap '' TERM; : > {}; while :; do sleep 1; done",
                    term_ready.display()
                ),
            ],
        );
        term_ignoring.release().unwrap();
        wait_until(
            || term_ready.exists(),
            "the TERM fixture never installed its trap",
        );
        assert_eq!(
            term_ignoring
                .terminate_with_grace(Duration::from_millis(10))
                .unwrap(),
            128 + libc::SIGKILL
        );
    }

    #[test]
    fn reap_only_after_escalated_signal_reaps_pidfd_ready_child() {
        let directory = tempfile::tempdir().unwrap();
        let ready = directory.path().join("ready");
        let mut child = spawn(
            "/bin/sh",
            &[
                "-c",
                &format!("trap '' INT; : > {}; while :; do :; done", ready.display()),
            ],
        );
        child.release().unwrap();
        wait_until(|| ready.exists(), "the SIGINT fixture never became ready");

        assert_eq!(
            child.forward_signal(libc::SIGINT).unwrap(),
            ForwardAction::Forwarded
        );
        assert_eq!(
            child.forward_signal(libc::SIGINT).unwrap(),
            ForwardAction::Escalated
        );
        wait_until(
            || child.pin.wait_ready(Some(Duration::ZERO)).unwrap(),
            "the escalated child pidfd never became ready",
        );

        assert_eq!(child.reap_after_escalation().unwrap(), 128 + libc::SIGKILL);
        assert!(child.is_reaped());
    }

    #[test]
    fn signal_settlement_forwards_the_second_sigint_as_escalation() {
        let directory = tempfile::tempdir().unwrap();
        let ready = directory.path().join("ready");
        let first_signal = directory.path().join("first-signal");
        let mut child = spawn(
            "/bin/sh",
            &[
                "-c",
                &format!(
                    "trap ': > {}' INT; : > {}; while :; do sleep 1; done",
                    first_signal.display(),
                    ready.display(),
                ),
            ],
        );
        child.release().unwrap();
        wait_until(|| ready.exists(), "the SIGINT fixture never became ready");

        let signals = Arc::new(SignalState::new());
        signals.observe(libc::SIGINT);
        let observed = Arc::clone(&signals);
        let sender = std::thread::spawn(move || {
            wait_until(
                || first_signal.exists(),
                "settlement never forwarded the first SIGINT",
            );
            observed.observe(libc::SIGINT);
        });
        assert_eq!(
            settle_after_signal(&mut child, &signals).unwrap(),
            ChildOutcome::Exited(128 + libc::SIGKILL)
        );
        sender.join().unwrap();
        assert_eq!(child.interrupt_count, 2);
    }

    #[test]
    fn signal_settlement_observes_second_sigint_during_fallback_term_grace() {
        let directory = tempfile::tempdir().unwrap();
        let ready = directory.path().join("ready");
        // `sleep` instead of a busy loop: no CPU burn, identical signal
        // behavior for this test (INT/TERM ignored; SIGKILL via group
        // escalation still lands; the group kill covers the extra process).
        let mut child = spawn(
            "/bin/sh",
            &[
                "-c",
                &format!("trap '' INT TERM; : > {}; sleep 300", ready.display(),),
            ],
        );
        // Generous setup-only budgets: handoff and ready-file latency prove
        // nothing about second-SIGINT settlement, so they must not be able
        // to fail the test. The settlement bounds below are untouched.
        child
            .release_until(Instant::now() + Duration::from_secs(60), || None)
            .unwrap();
        wait_until_with_timeout(
            || ready.exists(),
            Duration::from_secs(30),
            "the SIGINT fixture never became ready",
        );

        let signals = Arc::new(SignalState::new());
        signals.observe(libc::SIGINT);
        let observed = Arc::clone(&signals);
        let mut fallback_terms = 0;
        assert_eq!(
            settle_after_signal_with_grace_and(
                &mut child,
                &signals,
                Duration::from_millis(100),
                || {
                    fallback_terms += 1;
                    assert_eq!(
                        observed.sigint_deliveries(),
                        1,
                        "the second SIGINT was recorded before fallback SIGTERM",
                    );
                    observed.observe(libc::SIGINT);
                },
            )
            .unwrap(),
            ChildOutcome::Exited(128 + libc::SIGKILL)
        );
        assert_eq!(
            fallback_terms, 1,
            "settlement did not enter fallback SIGTERM grace"
        );
        assert_eq!(signals.sigint_deliveries(), 2);
        assert_eq!(child.interrupt_count, 2);
        assert!(child.is_reaped());
    }

    #[test]
    fn always_wrap_reports_interruption_not_refusal_when_signalled() {
        let signals = SignalState::new();
        signals.observe(libc::SIGTERM);
        let text = format!(
            "{:#}",
            always_wrap(&signals, anyhow!("pause: pause coordination cancelled"))
        );
        assert!(
            text.contains("interrupted by SIGTERM"),
            "a signalled run must not claim refusal: {text}"
        );
        assert!(
            !text.contains("refused rather than capturing unpaused"),
            "refusal text on a signal exit is false: {text}"
        );
    }

    #[test]
    fn always_wrap_keeps_refusal_text_without_signal() {
        let signals = SignalState::new();
        let text = format!(
            "{:#}",
            always_wrap(&signals, anyhow!("pause: something failed"))
        );
        assert!(
            text.contains("refused rather than capturing unpaused"),
            "genuine refusal text must be unchanged: {text}"
        );
    }

    #[test]
    fn signal_settlement_forwards_the_retained_sigterm_identity() {
        let mut child = spawn("/bin/sleep", &["10"]);
        child.release().unwrap();
        let signals = SignalState::new();
        signals.observe(libc::SIGTERM);
        assert_eq!(
            settle_after_signal(&mut child, &signals).unwrap(),
            ChildOutcome::Exited(128 + libc::SIGTERM)
        );
    }

    #[test]
    fn graceful_termination_resumes_a_stopped_child_before_sigterm() {
        let fixture_dir = tempfile::tempdir().unwrap();
        let sleeper = build_sleeper(fixture_dir.path());
        let sleeper = sleeper.to_str().unwrap();
        let mut child = spawn(sleeper, &[]);
        child.release().unwrap();
        unsafe { libc::kill(child.pid() as libc::pid_t, libc::SIGSTOP) };
        wait_until(
            || child_is_stopped(child.pid()),
            "the fixture child never entered the stopped state",
        );

        // A stopped child cannot observe SIGTERM: without a resume-first
        // it burns the whole grace window and dies by SIGKILL (137).
        assert_eq!(child.terminate_and_reap().unwrap(), 128 + libc::SIGTERM);
    }

    /// DR-LEAKED-STOPPED-HOLD regression: a test binary that dies without
    /// unwinding runs no `Drop`. Model that by forgetting the owned children
    /// of a test thread that then ends: both a stopped released command and
    /// a stopped pre-exec child (whose release pipe stays open, so EOF cannot
    /// end it) must still die by the test-only parent-death SIGKILL.
    #[test]
    fn stopped_children_die_with_the_test_thread_that_forked_them() {
        let fixture_dir = tempfile::tempdir().unwrap();
        let sleeper = build_sleeper(fixture_dir.path());
        let sleeper = sleeper.to_str().unwrap().to_owned();
        let pids = std::thread::spawn(move || {
            let mut released = spawn(&sleeper, &[]);
            released.release().unwrap();
            let unreleased = spawn("/bin/sh", &["-c", "exit 0"]);
            wait_for_session_leader(&unreleased);
            for child in [&released, &unreleased] {
                child.pin().send_signal(libc::SIGSTOP).unwrap();
                wait_until(
                    || child_is_stopped(child.pid()),
                    "the owned child never entered the stopped state",
                );
            }
            let pids = [released.pid(), unreleased.pid()];
            // As if the test binary were killed here: no Drop, no reap, and
            // the pre-exec child's release pipe stays open.
            std::mem::forget(released);
            std::mem::forget(unreleased);
            pids
        })
        .join()
        .unwrap();
        let deadline = Instant::now() + Duration::from_secs(10);
        let mut outcomes = Vec::new();
        for pid in pids {
            let mut status = 0;
            loop {
                // SAFETY: the pid is this process's own unreaped child.
                let waited =
                    unsafe { libc::waitpid(pid as libc::pid_t, &mut status, libc::WNOHANG) };
                if waited == pid as libc::pid_t {
                    outcomes
                        .push(libc::WIFSIGNALED(status) && libc::WTERMSIG(status) == libc::SIGKILL);
                    break;
                }
                if Instant::now() >= deadline {
                    for pid in pids {
                        // SAFETY: SIGKILL to this process's own unreaped child.
                        unsafe { libc::kill(pid as libc::pid_t, libc::SIGKILL) };
                        // SAFETY: as above; reaps the child just killed.
                        unsafe { libc::waitpid(pid as libc::pid_t, &mut status, 0) };
                    }
                    panic!("a stopped child outlived the test thread that forked it: {pids:?}");
                }
                std::thread::sleep(Duration::from_millis(5));
            }
        }
        assert_eq!(outcomes, [true, true], "both children must die by SIGKILL");
    }

    fn child_is_stopped(pid: u32) -> bool {
        let stat = std::fs::read_to_string(format!("/proc/{pid}/stat")).unwrap_or_default();
        stat.split(' ').nth(2).is_some_and(|state| state == "T")
    }

    #[test]
    fn signal_settlement_resumes_a_stopped_child_before_forwarding_sigterm() {
        let fixture_dir = tempfile::tempdir().unwrap();
        let sleeper = build_sleeper(fixture_dir.path());
        let sleeper = sleeper.to_str().unwrap();
        let mut child = spawn(sleeper, &[]);
        child.release().unwrap();
        // The pause path holds the owned child in T (SIGSTOP) while the
        // observer is signalled; settle must resume it first, because a
        // stopped child cannot observe the forwarded SIGTERM and would
        // otherwise burn both grace windows before SIGKILL.
        unsafe { libc::kill(child.pid() as libc::pid_t, libc::SIGSTOP) };
        wait_until(
            || child_is_stopped(child.pid()),
            "the fixture child never entered the stopped state",
        );

        let signals = SignalState::new();
        signals.observe(libc::SIGTERM);
        assert_eq!(
            settle_after_signal_with_grace(&mut child, &signals, Duration::from_millis(300))
                .unwrap(),
            ChildOutcome::Exited(128 + libc::SIGTERM)
        );
    }

    /// F-25's other shape: the child held in T also refuses to exit on
    /// SIGTERM. Settlement must resume it first, so the forwarded SIGTERM is
    /// actually delivered (its handler runs) instead of pending behind the
    /// stop, and then escalate to SIGKILL on its fixed budget: two grace
    /// windows plus the final kill grace, never a wait on the child itself.
    #[test]
    fn operator_stop_delivers_sigterm_to_a_held_child_then_escalates_within_the_bound() {
        let directory = tempfile::tempdir().unwrap();
        let ready = directory.path().join("ready");
        let term_seen = directory.path().join("term-seen");
        // The paths travel as positional parameters, never as script text.
        let mut child = spawn(
            "/bin/sh",
            &[
                "-c",
                "exec 2>/dev/null; trap ': > \"$2\"' TERM; : > \"$1\"; while :; do sleep 1; done",
                "sh",
                ready.to_str().unwrap(),
                term_seen.to_str().unwrap(),
            ],
        );
        child.release().unwrap();
        wait_until(
            || ready.exists(),
            "the TERM fixture never installed its handler",
        );
        let rescue_pidfd = duplicate_fd(child.pin().pidfd().unwrap());
        child.pin().send_signal(libc::SIGSTOP).unwrap();
        wait_until(
            || original_child_is_stopped(rescue_pidfd.as_fd()),
            "the fixture child never entered the stopped state",
        );

        let signals = Arc::new(SignalState::new());
        signals.observe(libc::SIGTERM);
        let grace = Duration::from_secs(1);
        let bound = grace.saturating_mul(2).saturating_add(FINAL_KILL_GRACE);
        let settling = Arc::clone(&signals);
        let (settled_tx, settled_rx) = std::sync::mpsc::channel();
        let started = Instant::now();
        let settle = std::thread::spawn(move || {
            let outcome = settle_after_signal_with_grace(&mut child, &settling, grace)
                .map_err(|error| format!("{error:#}"));
            settled_tx.send((outcome, child.is_reaped())).unwrap();
        });
        let settled = settled_rx.recv_timeout(bound);
        let elapsed = started.elapsed();
        if settled.is_err() {
            // Unwedge the harness before failing: kill the exact child.
            let _ = rescue_original_pidfd(
                rescue_pidfd.as_raw_fd(),
                &std::sync::atomic::AtomicBool::new(false),
            );
        }
        settle.join().unwrap();
        let (outcome, reaped) = settled.unwrap_or_else(|_| {
            panic!("settling a held child that survives SIGTERM overran its {bound:?} budget")
        });

        assert_eq!(outcome, Ok(ChildOutcome::Exited(128 + libc::SIGKILL)));
        assert!(reaped);
        assert!(
            term_seen.exists(),
            "the forwarded SIGTERM never reached the held child: it was not resumed first"
        );
        assert!(elapsed < bound, "settlement took {elapsed:?}");
    }

    /// The scripted half of a pause-held owned child: the authorization map,
    /// the discovery queue, the coordinator's monotonic clock, and a count of
    /// resumes. The clock advances by one tick per read, so no coordinator
    /// deadline (the 500 ms cleanup bound included) depends on scheduling.
    /// Everything else the shutdown test below drives is real — the
    /// coordinator, the owned child, its pidfd SIGCONT, its `/proc` task
    /// states, and the settlement path.
    ///
    /// The F-T4-2 tick tests add several scripted pieces, so they can confirm
    /// a full cycle, observe what a tick hands the capture loop, and price an
    /// idle tick:
    /// - a batch outcome (`required_complete`);
    /// - whether a batch with records changes the attach plan
    ///   (`batch_changes_plan`, reported through `plan_changed` per tick);
    /// - a successor stop on the first resume;
    /// - counts of the scripted I/O.
    ///
    /// All of these default to the shutdown test's behaviour.
    #[derive(Default)]
    struct HeldPause {
        authorization: Option<u64>,
        queue: std::collections::VecDeque<crate::discovery::pause::DiscoveryItem>,
        now_ns: u64,
        resumes: usize,
        required_complete: bool,
        batch_changes_plan: bool,
        plan_changed: bool,
        successor_on_resume: bool,
        hooks: Vec<u64>,
        resumed_at: Vec<u64>,
        authorization_reads: usize,
        dequeues: usize,
        arm_error: Option<String>,
        /// Post-release revalidation hands the queued record back as a
        /// deferred pause-owned item (the first hold right after release).
        deferred_revalidation: bool,
    }

    /// The helper's stop, as the kernel performs it: a loader hook in the
    /// owned child consumes the ARMED authorization (REQUESTED), queues its
    /// record stamped on the coordinator's clock (never older than the arm it
    /// consumed), and its SIGSTOP holds the child. Returns the hook timestamp
    /// that starts the stop's causal deadline.
    fn helper_stop(child: &OwnedChild, held: &mut HeldPause) -> u64 {
        held.authorization = Some(p11scope_ebpf_common::PAUSE_REQUESTED);
        // SAFETY: DiscoveryRecord is plain old data; all-zero is valid.
        let mut record: p11scope_ebpf_common::DiscoveryRecord = unsafe { std::mem::zeroed() };
        record.pid_tgid = u64::from(child.pid()) << 32;
        record.hook_ts_ns = held.now_ns;
        held.queue
            .push_back(crate::discovery::pause::DiscoveryItem::Record(record));
        held.hooks.push(record.hook_ts_ns);
        child.pin().send_signal(libc::SIGSTOP).unwrap();
        wait_until(
            || original_child_is_stopped(child.pin().pidfd().unwrap()),
            "the helper's SIGSTOP never held the child",
        );
        record.hook_ts_ns
    }

    struct HeldPauseIo<'a> {
        child: &'a OwnedChild,
        held: &'a mut HeldPause,
        signals: &'a SignalState,
    }

    impl crate::discovery::pause::PauseIo for HeldPauseIo<'_> {
        fn now_ns(&mut self) -> std::result::Result<u64, String> {
            self.held.now_ns += 1;
            Ok(self.held.now_ns)
        }

        fn wait_one_ms(&mut self) -> std::result::Result<(), String> {
            self.held.now_ns += 1_000_000;
            Ok(())
        }

        fn task_states(
            &mut self,
            pid: u32,
        ) -> std::result::Result<std::collections::BTreeMap<u32, u8>, String> {
            crate::discovery::pause::read_task_states(pid)
        }

        fn task_samples(
            &mut self,
            pid: u32,
        ) -> std::result::Result<
            std::collections::BTreeMap<u32, crate::discovery::pause::TaskSample>,
            String,
        > {
            crate::discovery::pause::read_task_samples(pid)
        }

        fn last_hook_attach_boot_ns(&mut self) -> Option<u64> {
            crate::discovery::pause::last_hook_attach_boot_ns()
        }

        fn boot_now_ns(&mut self) -> Option<u64> {
            crate::discovery::pause::boot_ns()
        }

        fn dequeue(
            &mut self,
        ) -> std::result::Result<Option<crate::discovery::pause::DiscoveryItem>, String> {
            self.held.dequeues += 1;
            Ok(self.held.queue.pop_front())
        }

        fn arm(&mut self) -> std::result::Result<(), String> {
            if let Some(error) = self.held.arm_error.clone() {
                return Err(error);
            }
            self.held.authorization = Some(p11scope_ebpf_common::PAUSE_ARMED);
            Ok(())
        }

        fn authorization(&mut self) -> std::result::Result<Option<u64>, String> {
            self.held.authorization_reads += 1;
            Ok(self.held.authorization)
        }

        fn remove_authorization(&mut self) -> std::result::Result<Option<u64>, String> {
            Ok(self.held.authorization.take())
        }

        fn apply_batch(
            &mut self,
            records: Vec<p11scope_ebpf_common::DiscoveryRecord>,
            _: Option<u64>,
            _: bool,
            _: bool,
            _: &mut Option<crate::discovery::engine::TerminalBatch>,
        ) -> std::result::Result<
            crate::discovery::pause::PauseBatchOutcome,
            crate::discovery::pause::PauseBatchError,
        > {
            self.held.plan_changed |= self.held.batch_changes_plan && !records.is_empty();
            let mut outcome = crate::discovery::pause::PauseBatchOutcome::default();
            outcome.required_complete = self.held.required_complete;
            Ok(outcome)
        }

        fn account_unvalidated_records(&mut self, _: u64) {}

        fn reconcile_terminal_authority(
            &mut self,
            _: &mut Option<crate::discovery::engine::TerminalBatch>,
        ) -> std::result::Result<(), String> {
            Ok(())
        }

        fn cleanup_terminal_batch_without_replay(
            &mut self,
            _: &mut Option<crate::discovery::engine::TerminalBatch>,
        ) -> std::result::Result<(), String> {
            Ok(())
        }

        fn revalidate_after_release(
            &mut self,
            _: bool,
        ) -> std::result::Result<crate::discovery::pause::PauseRevalidationOutcome, String>
        {
            if self.held.deferred_revalidation
                && let Some(crate::discovery::pause::DiscoveryItem::Record(record)) =
                    self.held.queue.pop_front()
            {
                let at = self.held.now_ns;
                return Ok(crate::discovery::pause::PauseRevalidationOutcome::Deferred(
                    crate::discovery::pause::TimedItem::record_for_test(record, at),
                ));
            }
            Err("post-release revalidation is not part of shutdown".into())
        }

        fn marker_seen(&mut self) -> std::result::Result<bool, String> {
            Ok(false)
        }

        fn resume(&mut self) -> std::result::Result<(), String> {
            self.held.resumes += 1;
            self.held.resumed_at.push(self.held.now_ns);
            self.child.pin().send_signal(libc::SIGCONT)?;
            // A cascade: the child's next loader hook consumes the successor
            // the cycle installed before this resume, right after it.
            if std::mem::take(&mut self.held.successor_on_resume)
                && self.held.authorization == Some(p11scope_ebpf_common::PAUSE_ARMED)
            {
                helper_stop(self.child, self.held);
            }
            Ok(())
        }

        fn detach_pause_links(&mut self) -> std::result::Result<(), String> {
            Ok(())
        }

        fn same_generation(
            &mut self,
            pid: u32,
            generation: u64,
        ) -> std::result::Result<bool, String> {
            Ok(pid == self.child.pid()
                && generation == self.child.generation().get()
                && self.child.pin().still_the_same())
        }

        fn original_exited(&mut self) -> std::result::Result<bool, String> {
            self.child.pin().original_exited()
        }

        fn cancelled(&mut self) -> std::result::Result<bool, String> {
            Ok(self.signals.interrupted())
        }
    }

    impl TickPauseIo for HeldPauseIo<'_> {
        fn plan_changed(&self) -> bool {
            self.held.plan_changed
        }
    }

    /// F-25 end to end, without BPF: the kernel consumed the pause arm and the
    /// helper's SIGSTOP holds the owned child when the capture ends — by an
    /// operator SIGTERM, by `--duration`, or by a capture error — before any
    /// capture tick serviced the stop. The two steps `Owned::finish` runs
    /// (coordinator cleanup, then settlement) must resume the held child,
    /// report the stop that never confirmed (`auto`: partial; `always`: a
    /// required refusal), and settle the child well inside one TERM grace
    /// window: terminated, or handed back running — never left in T.
    #[test]
    fn shutdown_resumes_reports_and_settles_a_child_held_by_an_unserviced_pause() {
        let fixture_dir = tempfile::tempdir().unwrap();
        let sleeper = build_sleeper(fixture_dir.path());
        for policy in [cli::PausePolicy::Auto, cli::PausePolicy::Always] {
            for end in [
                CaptureEnd::Signal,
                CaptureEnd::DurationExpired,
                CaptureEnd::Error,
            ] {
                let case = format!("{policy:?}/{end:?}");
                let mut child = spawn(sleeper.to_str().unwrap(), &[]);
                let pid = child.pid();
                let signals = SignalState::new();
                let mut held = HeldPause::default();
                let mut coordinator = {
                    let mut io = HeldPauseIo {
                        child: &child,
                        held: &mut held,
                        signals: &signals,
                    };
                    let mut coordinator =
                        PauseCoordinator::preflight(policy, &child, &mut io).unwrap();
                    assert_eq!(coordinator.arm(&mut io).unwrap(), ArmResult::Armed);
                    coordinator
                };
                child.release().unwrap();

                // The loader hook fires: the kernel's exchange consumes the
                // arm, the helper's record is queued, and its SIGSTOP holds
                // the child.
                held.authorization = Some(p11scope_ebpf_common::PAUSE_REQUESTED);
                // SAFETY: DiscoveryRecord is plain old data; all-zero is valid.
                let mut record: p11scope_ebpf_common::DiscoveryRecord =
                    unsafe { std::mem::zeroed() };
                record.pid_tgid = u64::from(child.pid()) << 32;
                // Stamped on the scripted clock at the arm's tick, as the
                // kernel stamps it after the exchange: never older than the arm.
                record.hook_ts_ns = held.now_ns;
                held.queue
                    .push_back(crate::discovery::pause::DiscoveryItem::Record(record));
                child.pin().send_signal(libc::SIGSTOP).unwrap();
                wait_until(
                    || original_child_is_stopped(child.pin().pidfd().unwrap()),
                    "the helper's SIGSTOP never held the child",
                );

                if end == CaptureEnd::Signal {
                    signals.observe(libc::SIGTERM);
                }
                let started = Instant::now();
                let cleanup = {
                    let mut io = HeldPauseIo {
                        child: &child,
                        held: &mut held,
                        signals: &signals,
                    };
                    coordinator.cleanup(&mut io)
                };
                assert!(
                    !original_child_is_stopped(child.pin().pidfd().unwrap()),
                    "{case}: the child is still held stopped after cleanup"
                );
                assert_eq!(
                    held.resumes, 1,
                    "{case}: cleanup resumes the held child once"
                );
                assert_eq!(held.authorization, None, "{case}");
                if policy == cli::PausePolicy::Auto {
                    assert!(cleanup.is_ok(), "{case}: {cleanup:?}");
                    assert_eq!(
                        coordinator.counters(),
                        crate::discovery::pause::PauseCounters {
                            attempts: 1,
                            confirmed: 0,
                            partial: 1,
                            unavailable: 0,
                        },
                        "{case}: the stop that never confirmed must be reported as partial"
                    );
                    assert_eq!(coordinator.status(), PauseStatus::Partial, "{case}");
                } else {
                    let error = cleanup
                        .as_ref()
                        .expect_err("always refuses a stop that never confirmed");
                    assert!(error.required() && !error.lifecycle(), "{case}: {error}");
                    assert_eq!(coordinator.counters().confirmed, 0, "{case}");
                }

                let mut retained = Some(child);
                let mut pending = None;
                let mut exit_code = None;
                let mut requested_kill = false;
                let mut still_running = false;
                settle_owned_child(
                    &mut retained,
                    end,
                    cleanup.is_ok(),
                    false,
                    &signals,
                    &mut pending,
                    &mut exit_code,
                    &mut requested_kill,
                    &mut still_running,
                )
                .unwrap();
                let elapsed = started.elapsed();

                assert!(
                    elapsed < TERM_GRACE,
                    "{case}: shutdown waited out a TERM grace window ({elapsed:?})"
                );
                if end == CaptureEnd::DurationExpired && cleanup.is_ok() {
                    // `--duration` without `--kill-on-timeout` hands it back.
                    assert_eq!(exit_code, None, "{case}");
                    assert!(still_running, "{case}");
                    let staged = pending.as_mut().expect("a staged running handoff");
                    assert!(
                        !original_child_is_stopped(staged.pin().pidfd().unwrap()),
                        "{case}: a handed-back child is never left stopped"
                    );
                    staged.terminate_and_reap().unwrap();
                } else if end == CaptureEnd::Error || end == CaptureEnd::DurationExpired {
                    // A capture error, or an expired duration whose pause
                    // cleanup failed, hands the live child back running,
                    // never stopped and never killed.
                    assert_eq!(exit_code, None, "{case}");
                    assert!(still_running, "{case}");
                    assert!(pending.is_none(), "{case}: the error handoff commits");
                    assert!(retained.is_none(), "{case}: the error handoff commits");
                    assert_eq!(
                        unsafe { libc::kill(pid as libc::pid_t, 0) },
                        0,
                        "{case}: the error settlement killed the observed program"
                    );
                    assert_eq!(
                        unsafe { libc::kill(pid as libc::pid_t, libc::SIGKILL) },
                        0,
                        "{case}"
                    );
                    let mut status = 0;
                    assert_eq!(
                        unsafe { libc::waitpid(pid as libc::pid_t, &mut status, 0) },
                        pid as libc::pid_t,
                        "{case}"
                    );
                } else {
                    assert_eq!(
                        exit_code,
                        Some(128 + libc::SIGTERM),
                        "{case}: the resumed child must die by the SIGTERM it was sent"
                    );
                    assert!(!still_running, "{case}");
                    assert!(retained.as_ref().unwrap().is_reaped(), "{case}");
                    assert!(pending.is_none(), "{case}");
                }
            }
        }
    }

    /// One capture tick's pause step, composed as both capture loops compose
    /// it for an owned explicit pause. The discovery gate asks `pause_stop_due`
    /// between frames only.
    /// - A pending stop runs the production between-frames step,
    ///   `pending_stop_pass`: all of `service_pending_stop` but its session
    ///   adapter.
    /// - A frame pass services an armed pause through the same `service_pause`
    ///   entry that `drain_discovery_tick` calls. That wrapper, and its ordinary
    ///   fallback for a disabled policy, need BPF and do not arise here.
    ///
    /// Returns the admitted pass and what the loop receives: the tick's
    /// `(plan_changed, paused)`, or `Err` when the capture ends.
    fn held_pause_tick(
        since_frame: Duration,
        drain: Duration,
        coordinator: &mut PauseCoordinator,
        io: &mut HeldPauseIo<'_>,
    ) -> (Option<DiscoveryPass>, Result<(bool, bool)>) {
        let pass = discovery_due(
            since_frame,
            drain,
            || pause_stop_due(coordinator, io),
            || false,
        );
        let handed = match pass {
            None => Ok((false, false)),
            Some(DiscoveryPass::PendingStop) => pending_stop_pass(coordinator, io),
            Some(DiscoveryPass::Frame) => {
                let serviced = service_pause(coordinator, io)
                    .unwrap_or_else(|error| panic!("a frame pass failed: {error}"));
                assert!(serviced, "a frame pass must service an armed pause");
                Ok((io.plan_changed(), true))
            }
            // The held-child harness never stages discovery backlog: the
            // gate above always reports none, so this arm is unreachable.
            Some(DiscoveryPass::Backlog) => {
                unreachable!("held harness admits no backlog pass")
            }
        };
        (pass, handed)
    }

    /// One driven tick: the pass it admitted, then the `(plan_changed, paused)`
    /// it handed the loop (both false when it ended the capture).
    type HeldTick = (Option<DiscoveryPass>, bool, bool);

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    enum HeldStop {
        /// One helper stop, landing just after a frame.
        One,
        /// The same, and the successor its cycle installs is consumed right
        /// after that cycle's resume, so `observe_resumed` only acknowledges it.
        Cascade,
        /// The cascade with the first stop serviced by a frame, so only the
        /// successor waits between frames.
        CascadeAfterFrame,
        /// One stop whose required attachment fails: a genuinely failed cycle.
        Failed,
        /// One stop, with an operator stop already pending on the tick.
        Signalled,
    }

    #[derive(Debug, PartialEq, Eq)]
    struct HeldStopOutcome {
        case: HeldStop,
        policy: cli::PausePolicy,
        /// The first two ticks.
        first_ticks: [HeldTick; 2],
        /// A tick's pause failure ended the capture.
        ended_by_pause_failure: bool,
        /// Whether the child was still stopped after the last tick.
        held_after_ticks: bool,
        counters_after_ticks: crate::discovery::pause::PauseCounters,
        /// After the capture's cleanup: the counters the report renders, and
        /// whether cleanup refused the run.
        counters_after_cleanup: crate::discovery::pause::PauseCounters,
        cleanup_refused: bool,
        resumes: usize,
        /// The scripted I/O of the idle ticks after the first two.
        idle_authorization_reads: usize,
        idle_dequeues: usize,
    }

    /// F-T4-2 end to end, without BPF. A real owned child is held stopped by
    /// the helper's SIGSTOP, with REQUESTED and its record queued. The real
    /// coordinator is driven through one capture tick's pause step at the
    /// profile default drain interval, with `since_frame = 0` (the frame has
    /// just run). The scripted clock advances one idle wait per tick, and the
    /// ticks span the whole 500 ms causal budget.
    ///
    /// The first tick must service the stop: confirmed, and the child resumed
    /// (the kernel's waitid says so) before hook + 500 ms on the coordinator's
    /// clock. In a cascade, the next tick must service the successor as well.
    /// Afterwards an idle tick costs one authorization read while the
    /// successor stays armed, and nothing once the pause is disarmed. The
    /// semantics around it hold. A genuinely failed cycle still resumes the
    /// child and goes partial under `auto`, and collects unpaused with an
    /// unavailable gap under `always`. A pending operator stop wins: the tick
    /// services nothing, and
    /// cleanup resumes the child and reports the stop (`auto` partial, `always`
    /// refused). Under the frame-only gate every stop stayed held through all
    /// the ticks and cleanup reported it unconfirmed.
    ///
    /// Each tick also records the `(plan_changed, paused)` it hands the loop.
    /// A pause batch normally changes the attach plan (a new provider). One
    /// `always` stop's batch attaches nothing new, because `always` stops on
    /// every load, already-attached ones included. That tick pauses without a
    /// plan change, so the pair's two halves can be told apart.
    #[test]
    fn a_pending_pause_stop_is_serviced_between_frames_within_its_causal_deadline() {
        use crate::cli::PausePolicy::{Always, Auto};
        use crate::discovery::pause::PauseCounters;
        let fixture_dir = tempfile::tempdir().unwrap();
        let sleeper = build_sleeper(fixture_dir.path());
        let budget = crate::discovery::pause::CYCLE_NS;
        let idle_wait = u64::try_from(READY_IDLE_POLL.as_nanos()).unwrap();
        let ticks = usize::try_from(budget / idle_wait).unwrap();
        let drain = PROFILE_CADENCE;
        let cases = [
            (HeldStop::One, Auto),
            (HeldStop::Cascade, Auto),
            (HeldStop::CascadeAfterFrame, Auto),
            (HeldStop::Failed, Auto),
            (HeldStop::Signalled, Auto),
            (HeldStop::One, Always),
            (HeldStop::Failed, Always),
            (HeldStop::Signalled, Always),
        ];
        let mut observed = Vec::new();
        let mut deadlines = Vec::new();
        for (case, policy) in cases {
            let mut child = spawn(sleeper.to_str().unwrap(), &[]);
            let signals = SignalState::new();
            let mut held = HeldPause {
                required_complete: case != HeldStop::Failed,
                batch_changes_plan: (case, policy) != (HeldStop::One, Always),
                successor_on_resume: matches!(
                    case,
                    HeldStop::Cascade | HeldStop::CascadeAfterFrame
                ),
                ..HeldPause::default()
            };
            let mut coordinator = {
                let mut io = HeldPauseIo {
                    child: &child,
                    held: &mut held,
                    signals: &signals,
                };
                let mut coordinator = PauseCoordinator::preflight(policy, &child, &mut io).unwrap();
                assert_eq!(coordinator.arm(&mut io).unwrap(), ArmResult::Armed);
                coordinator
            };
            child.release().unwrap();
            helper_stop(&child, &mut held);
            if case == HeldStop::Signalled {
                signals.observe(libc::SIGTERM);
            }

            let idle: HeldTick = (None, false, false);
            let mut first_ticks = [idle; 2];
            let mut idle_from = None;
            let mut ended_by_pause_failure = false;
            for tick in 0..ticks {
                if tick == 2 {
                    idle_from = Some((held.authorization_reads, held.dequeues));
                }
                let since_frame = if tick == 0 && case == HeldStop::CascadeAfterFrame {
                    drain
                } else {
                    Duration::ZERO
                };
                // A fresh adapter per tick, as the loop builds one per pass.
                held.plan_changed = false;
                let mut io = HeldPauseIo {
                    child: &child,
                    held: &mut held,
                    signals: &signals,
                };
                let (pass, handed) = held_pause_tick(since_frame, drain, &mut coordinator, &mut io);
                held.now_ns += idle_wait;
                let (plan_changed, paused) = handed.as_ref().map_or((false, false), |pair| *pair);
                if let Some(record) = first_ticks.get_mut(tick) {
                    *record = (pass, plan_changed, paused);
                }
                if handed.is_err() {
                    ended_by_pause_failure = true;
                    break;
                }
            }
            let held_after_ticks = original_child_is_stopped(child.pin().pidfd().unwrap());
            let counters_after_ticks = coordinator.counters();
            let (idle_authorization_reads, idle_dequeues) = idle_from
                .map_or((0, 0), |(reads, dequeues)| {
                    (held.authorization_reads - reads, held.dequeues - dequeues)
                });

            // The capture ends: `Owned::finish` runs the coordinator's cleanup.
            let cleanup = {
                let mut io = HeldPauseIo {
                    child: &child,
                    held: &mut held,
                    signals: &signals,
                };
                coordinator.cleanup(&mut io)
            };
            if let Err(error) = &cleanup {
                assert!(
                    error.required() && !error.lifecycle(),
                    "{case:?}/{policy:?}: {error}"
                );
            }
            assert!(
                !original_child_is_stopped(child.pin().pidfd().unwrap()),
                "{case:?}/{policy:?}: the child is still held stopped after cleanup"
            );
            observed.push(HeldStopOutcome {
                case,
                policy,
                first_ticks,
                ended_by_pause_failure,
                held_after_ticks,
                counters_after_ticks,
                counters_after_cleanup: coordinator.counters(),
                cleanup_refused: cleanup.is_err(),
                resumes: held.resumes,
                idle_authorization_reads,
                idle_dequeues,
            });
            if matches!(
                case,
                HeldStop::One | HeldStop::Cascade | HeldStop::CascadeAfterFrame
            ) {
                deadlines.push((case, policy, held.hooks.clone(), held.resumed_at.clone()));
            }
            // Dropping the child kills and reaps it.
        }

        let idle: HeldTick = (None, false, false);
        let stop: HeldTick = (Some(DiscoveryPass::PendingStop), true, true);
        let confirmed = |stops| PauseCounters {
            attempts: stops,
            confirmed: stops,
            partial: 0,
            unavailable: 0,
        };
        let unconfirmed = |partial| PauseCounters {
            attempts: 1,
            confirmed: 0,
            partial,
            unavailable: 0,
        };
        let unavailable = || PauseCounters {
            attempts: 1,
            confirmed: 0,
            partial: 0,
            unavailable: 1,
        };
        let serviced =
            |case, policy, first_ticks, stops, idle_authorization_reads| HeldStopOutcome {
                case,
                policy,
                first_ticks,
                ended_by_pause_failure: false,
                held_after_ticks: false,
                counters_after_ticks: confirmed(stops),
                counters_after_cleanup: confirmed(stops),
                cleanup_refused: false,
                resumes: usize::try_from(stops).unwrap(),
                idle_authorization_reads,
                idle_dequeues: 0,
            };
        // Every confirmed stop keeps the owned epoch armed (GT-4), so after a
        // cascade too each idle tick reads the armed authorization once.
        let expected = [
            serviced(HeldStop::One, Auto, [stop, idle], 1, ticks - 2),
            serviced(HeldStop::Cascade, Auto, [stop, stop], 2, ticks - 2),
            serviced(
                HeldStop::CascadeAfterFrame,
                Auto,
                [(Some(DiscoveryPass::Frame), true, true), stop],
                2,
                ticks - 2,
            ),
            // The failed cycle resumes the child, counts one partial attempt
            // and retires re-arming; the capture continues.
            HeldStopOutcome {
                case: HeldStop::Failed,
                policy: Auto,
                first_ticks: [stop, idle],
                ended_by_pause_failure: false,
                held_after_ticks: false,
                counters_after_ticks: unconfirmed(1),
                counters_after_cleanup: unconfirmed(1),
                cleanup_refused: false,
                resumes: 1,
                idle_authorization_reads: 0,
                idle_dequeues: 0,
            },
            HeldStopOutcome {
                case: HeldStop::Signalled,
                policy: Auto,
                first_ticks: [idle, idle],
                ended_by_pause_failure: false,
                held_after_ticks: true,
                counters_after_ticks: PauseCounters::default(),
                counters_after_cleanup: unconfirmed(1),
                cleanup_refused: false,
                resumes: 1,
                idle_authorization_reads: 0,
                idle_dequeues: 0,
            },
            // Its batch attached nothing new: the tick pauses without a plan
            // change.
            serviced(
                HeldStop::One,
                Always,
                [(Some(DiscoveryPass::PendingStop), false, true), idle],
                1,
                ticks - 2,
            ),
            // The failed cycle resumes the child, counts one unavailable
            // attempt and collects unpaused; the capture continues.
            HeldStopOutcome {
                case: HeldStop::Failed,
                policy: Always,
                first_ticks: [(Some(DiscoveryPass::PendingStop), true, false), idle],
                ended_by_pause_failure: false,
                held_after_ticks: false,
                counters_after_ticks: unavailable(),
                counters_after_cleanup: unavailable(),
                cleanup_refused: false,
                resumes: 1,
                idle_authorization_reads: 0,
                idle_dequeues: 0,
            },
            HeldStopOutcome {
                case: HeldStop::Signalled,
                policy: Always,
                first_ticks: [idle, idle],
                ended_by_pause_failure: false,
                held_after_ticks: true,
                counters_after_ticks: PauseCounters::default(),
                counters_after_cleanup: unconfirmed(0),
                cleanup_refused: true,
                resumes: 1,
                idle_authorization_reads: 0,
                idle_dequeues: 0,
            },
        ];
        assert_eq!(observed, expected);

        for (case, policy, hooks, resumed_at) in deadlines {
            assert_eq!(
                hooks.len(),
                resumed_at.len(),
                "{case:?}/{policy:?}: one resume per stop"
            );
            for (hook, resumed) in hooks.iter().zip(&resumed_at) {
                assert!(
                    *resumed <= hook + budget,
                    "{case:?}/{policy:?}: the stop hooked at {hook} ns was resumed at \
                     {resumed} ns, past its {budget} ns causal deadline"
                );
            }
        }
    }

    /// A stop that lands during a held `auto` cycle cancels it; that is a
    /// signal end, not a capture failure. The between-frames step hands the
    /// tick back — the loop then observes the stop and still writes the
    /// report — instead of failing the capture. The cancelled attempt counts
    /// one partial, and the child is resumed, never stranded stopped. (The
    /// gate already idles a stop that lands before the cycle; this covers a
    /// stop that lands during it, which the gate cannot see.)
    #[test]
    fn a_stop_during_a_held_auto_cycle_hands_the_tick_back_for_a_signal_end() {
        use crate::discovery::pause::PauseCounters;
        let fixture_dir = tempfile::tempdir().unwrap();
        let sleeper = build_sleeper(fixture_dir.path());
        let mut child = spawn(sleeper.to_str().unwrap(), &[]);
        let signals = SignalState::new();
        let mut held = HeldPause {
            batch_changes_plan: true,
            ..HeldPause::default()
        };
        let mut coordinator = {
            let mut io = HeldPauseIo {
                child: &child,
                held: &mut held,
                signals: &signals,
            };
            let mut coordinator =
                PauseCoordinator::preflight(crate::cli::PausePolicy::Auto, &child, &mut io)
                    .unwrap();
            assert_eq!(coordinator.arm(&mut io).unwrap(), ArmResult::Armed);
            coordinator
        };
        child.release().unwrap();
        helper_stop(&child, &mut held);
        // The operator stop lands while the child is held stopped.
        assert!(
            original_child_is_stopped(child.pin().pidfd().unwrap()),
            "the helper stop must hold the child before the stop lands"
        );
        signals.observe(libc::SIGTERM);
        let mut io = HeldPauseIo {
            child: &child,
            held: &mut held,
            signals: &signals,
        };
        let handed = pending_stop_pass(&mut coordinator, &mut io);
        let (plan_changed, paused) =
            handed.expect("a stop during the hold ends the tick, not the capture");
        assert!(!paused, "the cancelled cycle serviced nothing");
        assert_eq!(
            (plan_changed, paused),
            (held.plan_changed, false),
            "the tick reports whatever the cancelled cycle applied"
        );
        assert_eq!(
            coordinator.counters(),
            PauseCounters {
                attempts: 1,
                confirmed: 0,
                partial: 1,
                unavailable: 0,
            },
            "the cancelled attempt counts one partial"
        );
        assert_eq!(
            coordinator.refusal(),
            None,
            "a handed-back auto cycle is a signal end, not a refusal"
        );
        assert!(
            !original_child_is_stopped(child.pin().pidfd().unwrap()),
            "the cancelled cycle resumes the held child"
        );
        // Dropping the child kills and reaps it.
    }

    /// Arms a held-pause coordinator under `policy` for a freshly spawned
    /// sleeper, releases the child and holds it stopped through the helper.
    fn armed_and_held(
        policy: cli::PausePolicy,
        child: &mut OwnedChild,
        held: &mut HeldPause,
        signals: &SignalState,
    ) -> PauseCoordinator {
        let coordinator = {
            let mut io = HeldPauseIo {
                child: &*child,
                held: &mut *held,
                signals,
            };
            let mut coordinator = PauseCoordinator::preflight(policy, &*child, &mut io).unwrap();
            assert_eq!(coordinator.arm(&mut io).unwrap(), ArmResult::Armed);
            coordinator
        };
        child.release().unwrap();
        helper_stop(child, held);
        assert!(
            original_child_is_stopped(child.pin().pidfd().unwrap()),
            "the helper stop must hold the child before the stop lands"
        );
        coordinator
    }

    /// The `always` twin of the held-cycle stop: a required pause keeps
    /// refusing. The between-frames step fails the capture with the
    /// cancellation (production still seals the report: data always), the
    /// refused attempt counts one partial, and the child is resumed, never
    /// stranded stopped.
    #[test]
    fn a_stop_during_a_held_always_cycle_still_refuses_with_the_cancellation() {
        use crate::discovery::pause::{PauseCounters, PauseRefusal};
        let fixture_dir = tempfile::tempdir().unwrap();
        let sleeper = build_sleeper(fixture_dir.path());
        let mut child = spawn(sleeper.to_str().unwrap(), &[]);
        let signals = SignalState::new();
        let mut held = HeldPause {
            batch_changes_plan: true,
            ..HeldPause::default()
        };
        let mut coordinator =
            armed_and_held(cli::PausePolicy::Always, &mut child, &mut held, &signals);
        signals.observe(libc::SIGTERM);
        let mut io = HeldPauseIo {
            child: &child,
            held: &mut held,
            signals: &signals,
        };
        let error = pending_stop_pass(&mut coordinator, &mut io)
            .expect_err("a required pause refuses a stop during its hold");
        assert!(
            format!("{error:#}").contains("pause coordination cancelled"),
            "the refusal names the cancellation: {error:#}"
        );
        assert_eq!(
            coordinator.counters(),
            PauseCounters {
                attempts: 1,
                confirmed: 0,
                partial: 1,
                unavailable: 0,
            },
            "the refused attempt counts one partial"
        );
        assert_eq!(
            coordinator.refusal(),
            Some(PauseRefusal::Interrupted),
            "a stop during the hold refuses as interrupted"
        );
        assert!(
            !original_child_is_stopped(child.pin().pidfd().unwrap()),
            "the cancelled cycle resumes the held child"
        );
    }

    /// A stop landing in the first hold right after release (post-release
    /// revalidation services a deferred stop) is the same signal end as a
    /// stop during a tick's hold: under `auto` the step hands back so the
    /// loop observes the stop and writes the report, counting one partial;
    /// under `always` it still refuses with the cancellation. The child is
    /// resumed either way.
    #[test]
    fn a_stop_during_the_post_release_hold_ends_auto_by_signal_and_refuses_always() {
        use crate::discovery::pause::PauseCounters;
        let fixture_dir = tempfile::tempdir().unwrap();
        let sleeper = build_sleeper(fixture_dir.path());
        for policy in [cli::PausePolicy::Auto, cli::PausePolicy::Always] {
            let mut child = spawn(sleeper.to_str().unwrap(), &[]);
            let signals = SignalState::new();
            let mut held = HeldPause {
                deferred_revalidation: true,
                ..HeldPause::default()
            };
            let mut coordinator = armed_and_held(policy, &mut child, &mut held, &signals);
            signals.observe(libc::SIGTERM);
            let mut io = HeldPauseIo {
                child: &child,
                held: &mut held,
                signals: &signals,
            };
            let revalidated = post_release_pass(&mut coordinator, &mut io);
            if policy == cli::PausePolicy::Auto {
                revalidated.expect("auto: a stop during the post-release hold is a signal end");
                assert_eq!(
                    coordinator.counters(),
                    PauseCounters {
                        attempts: 1,
                        confirmed: 0,
                        partial: 1,
                        unavailable: 0,
                    },
                    "auto: the cancelled attempt counts one partial"
                );
            } else {
                let error = revalidated.expect_err("always: a required pause refuses");
                assert!(
                    format!("{error:#}").contains("pause coordination cancelled"),
                    "always: the refusal names the cancellation: {error:#}"
                );
            }
            assert!(
                !original_child_is_stopped(child.pin().pidfd().unwrap()),
                "{policy:?}: the cancelled cycle resumes the held child"
            );
        }
    }

    /// Settling an owned-run pause preflight: success passes the coordinator
    /// through; an `auto` failure degrades to one counted partial attempt
    /// with arming disabled (the child runs free); `always` and `never`
    /// failures propagate to the caller, which fails the run.
    #[test]
    fn auto_preflight_failure_degrades_to_one_partial_attempt() {
        use crate::discovery::pause::PauseCounters;
        let fixture_dir = tempfile::tempdir().unwrap();
        let sleeper = build_sleeper(fixture_dir.path());
        let child = spawn(sleeper.to_str().unwrap(), &[]);
        let mut degraded = settle_pause_preflight(
            crate::cli::PausePolicy::Auto,
            Err(anyhow::anyhow!("probe: no pidfd signal authority")),
            child.pid(),
            child.generation().get(),
        )
        .expect("auto degrades, never fails the child");
        assert_eq!(
            degraded.counters(),
            PauseCounters {
                attempts: 1,
                confirmed: 0,
                partial: 1,
                unavailable: 0,
            },
            "the degrade counts one partial attempt"
        );
        assert_eq!(degraded.status(), PauseStatus::Partial);
        let signals = SignalState::new();
        let mut held = HeldPause::default();
        let mut io = HeldPauseIo {
            child: &child,
            held: &mut held,
            signals: &signals,
        };
        assert_eq!(
            degraded.arm(&mut io).unwrap(),
            ArmResult::Disabled,
            "the degraded coordinator never arms"
        );
        assert_eq!(
            child.pin().original_exited(),
            Ok(false),
            "the child runs free, never killed by the degrade"
        );
        // Dropping the child kills and reaps it.
    }

    #[test]
    fn non_auto_preflight_failures_propagate_to_fail_the_run() {
        for policy in [
            crate::cli::PausePolicy::Always,
            crate::cli::PausePolicy::Never,
        ] {
            match settle_pause_preflight(
                policy,
                Err(anyhow::anyhow!("probe: no pidfd signal authority")),
                7,
                9,
            ) {
                Ok(_) => panic!("{policy:?}: non-auto failures propagate"),
                Err(error) => assert!(
                    format!("{error}").contains("no pidfd signal authority"),
                    "{policy:?}: the cause survives: {error}"
                ),
            }
        }
    }

    #[test]
    fn successful_preflight_passes_the_coordinator_through() {
        use crate::discovery::pause::PauseCounters;
        let through = PauseCoordinator::degraded_auto(7, 9);
        let settled = settle_pause_preflight(crate::cli::PausePolicy::Auto, Ok(through), 7, 9)
            .expect("success passes through");
        assert_eq!(
            settled.counters(),
            PauseCounters {
                attempts: 1,
                confirmed: 0,
                partial: 1,
                unavailable: 0,
            },
            "the coordinator passes through untouched"
        );
    }

    /// U-19: the live discovery-noise summary is flushed on every
    /// `run_loop` exit, including a failed or second-signal-abandoned
    /// capture: no `?` may return between the capture call and the flush.
    /// `run_loop` needs a live session, so the order is pinned statically.
    #[test]
    fn run_loop_reports_discovery_noise_before_returning_a_capture_error() {
        let source = include_str!("run.rs");
        let body = source
            .split_once("\nfn run_loop(")
            .unwrap()
            .1
            .split_once("\n}\n")
            .unwrap()
            .0;
        let flush = body
            .find("engine.report_discovery_noise();")
            .expect("run_loop flushes the discovery noise");
        let captures = &body[body.find("let evidence = match kind {").unwrap()..flush];
        assert!(captures.contains("capture_profile("));
        assert!(captures.contains("capture_trace("));
        assert!(
            !captures.contains(")?"),
            "a capture error must not return before the noise flush"
        );
        assert!(
            body[flush..]
                .trim_start_matches("engine.report_discovery_noise();")
                .contains("evidence"),
            "run_loop returns the capture result after the flush"
        );
    }

    /// SG-I7/M11: a second-SIGINT cleanup abandon reaches `main` through
    /// every stop-path combinator as the typed outcome (exit 130), and the
    /// error line is suppressed only when the abandon is the whole story.
    #[test]
    fn a_second_signal_abandon_survives_every_stop_path_combinator() {
        let interrupted = || anyhow::Error::new(crate::attach::CleanupInterrupted);
        let alone = combine_detach::<()>(Ok(()), Err(interrupted())).unwrap_err();
        assert_eq!(failure_exit_code(&alone), 130, "{alone:#}");
        assert!(failure_already_reported(&alone), "{alone:#}");
        let quiesce = finish_quiesce_error(
            anyhow!("terminal quiescence failed"),
            Ok(CaptureEnd::Signal),
            &mut (),
            |_| {},
            |_, _| Ok(()),
            |_| Ok(()),
            |_| Err(interrupted()),
        );
        let quiesce_publish_failed = finish_quiesce_error(
            anyhow!("terminal quiescence failed"),
            Ok(CaptureEnd::Signal),
            &mut (),
            |_| {},
            |_, _| Ok(()),
            |_| Err(anyhow!("seal failed")),
            |_| Err(interrupted()),
        );
        let preflight = combine_preflight_failure_with(
            anyhow!("pause preflight"),
            || Err(interrupted()),
            || Err(anyhow!("settling the child")),
        );
        for (name, error) in [
            (
                "terminal + detach",
                combine_detach::<()>(Err(anyhow!("publish failed")), Err(interrupted()))
                    .unwrap_err(),
            ),
            (
                "capture failure",
                combine_capture_failure(anyhow!("loop failed"), Ok(()), Err(interrupted())),
            ),
            (
                "capture + settle failure",
                combine_capture_failure(
                    anyhow!("loop failed"),
                    Err(anyhow!("settle failed")),
                    Err(interrupted()),
                ),
            ),
            ("quiesce failure", quiesce),
            ("quiesce + publish failure", quiesce_publish_failed),
            ("preflight failure", preflight),
            (
                "run --pause always",
                always_wrap(
                    &SignalState::new(),
                    combine_capture_failure(anyhow!("loop failed"), Ok(()), Err(interrupted())),
                ),
            ),
        ] {
            assert_eq!(failure_exit_code(&error), 130, "{name}: {error:#}");
            assert!(
                !failure_already_reported(&error),
                "{name}: the primary failure still needs its line: {error:#}"
            );
            // DR-RETRO-C6-2: the abandon is named once, never repeated by
            // the typed outer context that keeps exit 130.
            assert_eq!(
                format!("{error:#}").matches("second SIGINT").count(),
                1,
                "{name}: {error:#}"
            );
        }
        let ordinary = combine_detach::<()>(Ok(()), Err(anyhow!("detach failed"))).unwrap_err();
        assert_eq!(failure_exit_code(&ordinary), 1);
        assert!(!failure_already_reported(&ordinary));
    }

    /// The abandon's own context survives the de-duplication; only its
    /// repeated text is dropped.
    #[test]
    fn also_failed_names_a_second_signal_abandon_once_and_keeps_its_context() {
        let secondary =
            anyhow::Error::new(crate::attach::CleanupInterrupted).context("closing 3 links");
        let combined = also_failed(anyhow!("loop failed"), secondary, "detaching");
        let rendered = format!("{combined:#}");
        assert_eq!(rendered.matches("second SIGINT").count(), 1, "{rendered}");
        assert!(
            rendered.contains("detaching also failed: closing 3 links: loop failed"),
            "{rendered}"
        );
        assert_eq!(failure_exit_code(&combined), 130);
        let bare = also_failed(
            anyhow!("loop failed"),
            anyhow::Error::new(crate::attach::CleanupInterrupted),
            "detaching",
        );
        assert!(
            format!("{bare:#}").ends_with("detaching also failed: loop failed"),
            "{bare:#}"
        );
    }

    #[test]
    fn also_failed_keeps_both_causes_in_order() {
        // WINS: one "also failed" core behind the four combine_* helpers.
        let chained = also_failed(anyhow!("primary"), anyhow!("secondary"), "cleanup");
        let rendered = format!("{chained:#}");
        assert!(
            rendered.contains("cleanup also failed: secondary"),
            "{rendered}"
        );
        assert!(rendered.contains("primary"), "{rendered}");
    }

    #[test]
    fn capture_error_keeps_cleanup_and_settlement_context() {
        let finish = combine_finish_errors(
            Err(anyhow!("cleanup failed")),
            Err(anyhow!("settlement failed")),
        )
        .unwrap_err();
        let finish_rendered = format!("{finish:#}");
        assert!(
            finish_rendered.contains("cleanup failed"),
            "{finish_rendered}"
        );
        assert!(
            finish_rendered.contains("settlement failed"),
            "{finish_rendered}"
        );

        let error = combine_capture_failure(
            anyhow!("capture failed"),
            Err(finish),
            Err(anyhow!("detach failed")),
        );
        let rendered = format!("{error:#}");
        assert!(rendered.contains("capture failed"), "{rendered}");
        assert!(rendered.contains("cleanup failed"), "{rendered}");
        assert!(rendered.contains("settlement failed"), "{rendered}");
        assert!(rendered.contains("detach failed"), "{rendered}");

        let terminal = combine_detach::<()>(
            Err(anyhow!("terminal failed")),
            Err(anyhow!("detach failed")),
        );
        let terminal_rendered = format!("{:#}", terminal.unwrap_err());
        assert!(
            terminal_rendered.contains("terminal failed"),
            "{terminal_rendered}"
        );
        assert!(
            terminal_rendered.contains("detach failed"),
            "{terminal_rendered}"
        );
    }

    #[test]
    fn drop_closes_the_barrier_and_reaps_an_unreleased_child() {
        let unreleased_pid = {
            let child = spawn("/bin/sleep", &["10"]);
            child.pid()
        };
        let invalid_handoff_pid = {
            let mut child = spawn("/bin/sleep", &["10"]);
            let pid = child.pid();
            assert!(child.hand_off_running().is_err());
            pid
        };
        let deadline = Instant::now() + Duration::from_secs(2);
        while [unreleased_pid, invalid_handoff_pid]
            .into_iter()
            .any(|pid| std::path::Path::new(&format!("/proc/{pid}")).exists())
        {
            assert!(
                Instant::now() < deadline,
                "owned child was not reaped by drop"
            );
            std::thread::sleep(Duration::from_millis(1));
        }
    }

    /// MED (forward_signal): a child that exited before the first forwarded
    /// signal settles as Exited, never as a forwarding error — its pin reads
    /// "no longer active", so settle reaps the natural exit instead.
    #[test]
    fn settle_after_signal_reaps_a_child_that_exited_first() {
        let mut child = spawn("/bin/true", &[]);
        child.release().unwrap();
        wait_until(
            || child.pin.wait_ready(Some(Duration::ZERO)).unwrap(),
            "the true fixture never exited",
        );
        let signals = SignalState::new();
        signals.observe(libc::SIGTERM);
        let outcome =
            settle_after_signal_with_grace(&mut child, &signals, Duration::from_millis(50))
                .expect("a pre-exited child settles as Exited, not as an error");
        assert_eq!(outcome, ChildOutcome::Exited(0));
    }

    #[test]
    fn completed_generation_cannot_authorize_a_later_child_action() {
        let mut child = spawn("/bin/true", &[]);
        child.release().unwrap();
        assert_eq!(
            child.wait_for(None, false).unwrap(),
            ChildOutcome::Exited(0)
        );
        assert!(child.forward_signal(libc::SIGTERM).is_err());
        assert!(child.terminate_and_reap().is_err());
    }

    // ---- Slice 1b-2 error taxonomy (design §10.3) -----------------------

    /// Name errors precede hazard errors: the fail-fast target check
    /// refuses what is neither ELF nor script before any kernel
    /// verdict is consulted, exactly as `spawn` would at the fork.
    /// Scripts pass (pinned separately); a runnable ELF passes too.
    #[test]
    fn unrunnable_targets_are_refused_by_name_before_the_preflight() {
        let dir = tempfile::tempdir().unwrap();
        let blob = dir.path().join("blob");
        std::fs::write(&blob, "not an executable\n").unwrap();
        std::fs::set_permissions(&blob, std::fs::Permissions::from_mode(0o755)).unwrap();
        let error = check_owned_target_runnable(blob.as_os_str(), &[], None).unwrap_err();
        let text = format!("{error}");
        assert!(
            text.contains("must be an ELF executable or a #! script"),
            "{text}"
        );
        assert!(check_owned_target_runnable(std::ffi::OsStr::new("/bin/true"), &[], None).is_ok());
    }

    /// An unknown invoker (a `--user` that resolves nowhere leaves
    /// none) hides the interpreter token of a snap-starting script
    /// refusal (fail-closed) while still naming the snap application.
    #[test]
    fn runnable_check_without_an_invoker_hides_the_token() {
        let dir = tempfile::tempdir().unwrap();
        let script = dir.path().join("firefox");
        std::fs::write(&script, "#!/bin/sh\nexec /snap/bin/firefox \"$@\"\n").unwrap();
        std::fs::set_permissions(&script, std::fs::Permissions::from_mode(0o755)).unwrap();
        // An unresolvable `--user` leaves no invoker identity; the
        // snap-starting shape keeps the token-hiding rule under test.
        let exists = |candidate: &Path| candidate == Path::new("/snap/bin/firefox");
        let is_runnable = |_: &Path| false;
        let resolve_none = |_: &Path| None;
        let probes = snap_probes(&exists, &is_runnable, &resolve_none);
        let text = check_owned_target_runnable_with(
            script.as_os_str(),
            &[],
            Some(std::ffi::OsStr::new("")),
            Path::new("/"),
            None,
            &probes,
        )
        .unwrap_err()
        .to_string();
        assert!(
            text.contains("is a script that starts the snap application firefox"),
            "{text}"
        );
        assert!(!text.contains("/bin/sh"), "{text}");
    }

    /// The invoker mapping behind the runnable pre-check is fail-closed:
    /// a `--user` that resolves nowhere leaves no invoker, so the
    /// snap-starting refusal hides the interpreter token. Deterministic
    /// under any credentials: an unknown account errors both as root
    /// (unknown account) and without root (`--user` needs root).
    #[test]
    fn runnable_check_invoker_mapping_hides_the_token_for_an_unknown_user() {
        assert_eq!(
            invoker_for_runnable_check(Some(OsStr::new("p11scope-definitely-no-such-user"))),
            None
        );
    }

    fn snap_probes<'a>(
        exists: &'a dyn Fn(&Path) -> bool,
        is_runnable: &'a dyn Fn(&Path) -> bool,
        resolve: &'a dyn Fn(&Path) -> Option<PathBuf>,
    ) -> SnapProbes<'a> {
        SnapProbes {
            exists,
            is_runnable,
            resolve,
        }
    }

    /// Snap commands start through snap-confine, whose file capabilities
    /// no_new_privs withholds: refuse by name before the fork with the
    /// working alternatives instead of letting snap-confine fail later.
    /// The attach path is recommended first; naming the in-snap binary
    /// comes second with its confinement cost, since it weakens the
    /// application's own sandbox under no_new_privs.
    #[test]
    fn snap_launchers_are_refused_by_name_with_the_attach_alternative() {
        for (program, path) in [
            ("/snap/bin/firefox", None),
            ("firefox", Some("/nonexistent-dir:/snap/bin")),
        ] {
            let exists = |candidate: &Path| candidate == Path::new("/snap/bin/firefox");
            let is_runnable = |candidate: &Path| candidate == Path::new("/snap/bin/firefox");
            let resolve_none = |_: &Path| None;
            let probes = snap_probes(&exists, &is_runnable, &resolve_none);
            let error = snap_launcher_refusal(
                std::ffi::OsStr::new(program),
                &[],
                path.map(std::ffi::OsStr::new),
                Path::new("/"),
                &probes,
            )
            .unwrap_or_else(|| panic!("{program} must be refused"));
            let text = error.to_string();
            assert!(text.contains("firefox is a snap application"), "{text}");
            assert!(text.contains("no_new_privs"), "{text}");
            assert!(text.contains("p11scope profile --pid <pid>"), "{text}");
            assert!(text.contains("p11scope inspect --system"), "{text}");
            let attach = text.find("Recommended:").expect("attach first: {text}");
            let direct = text
                .find("Alternatively, name the program inside the snap directly")
                .expect("direct binary second: {text}");
            assert!(attach < direct, "{text}");
            assert!(text.contains("outside snap confinement"), "{text}");
            assert!(
                text.contains("browser sandboxes are weaker under no_new_privs"),
                "{text}"
            );
            assert!(text.contains("throwaway profile"), "{text}");
            assert!(
                text.contains("/snap/firefox/current/usr/lib/firefox/firefox"),
                "{text}"
            );
        }
        // Not a snap: an ordinary binary, a PATH hit before /snap/bin, a
        // /snap/bin name that does not exist, or an ELF binary that merely
        // lives under /snap (the refusal is for /snap/bin launchers only,
        // never a /snap prefix).
        for (program, path) in [
            ("/usr/bin/true", None),
            ("firefox", Some("/usr/bin:/snap/bin")),
            ("/snap/bin/absent", None),
            ("/snap/firefox/current/usr/lib/firefox/firefox", None),
        ] {
            let exists = |candidate: &Path| {
                candidate == Path::new("/snap/bin/firefox")
                    || candidate == Path::new("/usr/bin/firefox")
                    || candidate == Path::new("/usr/bin/true")
                    || candidate == Path::new("/snap/firefox/current/usr/lib/firefox/firefox")
            };
            let is_runnable = |candidate: &Path| {
                candidate == Path::new("/snap/bin/firefox")
                    || candidate == Path::new("/usr/bin/firefox")
                    || candidate == Path::new("/usr/bin/true")
                    || candidate == Path::new("/snap/firefox/current/usr/lib/firefox/firefox")
            };
            let resolve_none = |_: &Path| None;
            let probes = snap_probes(&exists, &is_runnable, &resolve_none);
            assert!(
                snap_launcher_refusal(
                    std::ffi::OsStr::new(program),
                    &[],
                    path.map(std::ffi::OsStr::new),
                    Path::new("/"),
                    &probes,
                )
                .is_none(),
                "{program} {path:?}"
            );
        }
    }

    /// Other snaps get the generic in-snap path; only Firefox names its
    /// exact binary.
    #[test]
    fn snap_refusal_uses_a_generic_example_for_other_snaps() {
        let exists = |candidate: &Path| candidate == Path::new("/snap/bin/spotify");
        let is_runnable = |candidate: &Path| candidate == Path::new("/snap/bin/spotify");
        let resolve_none = |_: &Path| None;
        let probes = snap_probes(&exists, &is_runnable, &resolve_none);
        let text = snap_launcher_refusal(
            std::ffi::OsStr::new("/snap/bin/spotify"),
            &[],
            None,
            Path::new("/"),
            &probes,
        )
        .expect("spotify must be refused")
        .to_string();
        assert!(text.contains("spotify is a snap application"), "{text}");
        assert!(text.contains("/snap/<snap>/current/<program>"), "{text}");
        assert!(!text.contains("/snap/firefox/"), "{text}");
    }

    /// The pre-check is not fooled by the system launcher directory or
    /// by `.`/`..`/relative spellings of a launcher path.
    #[test]
    fn snap_precheck_covers_system_dir_and_dotdot_and_relative_spellings() {
        let exists = |candidate: &Path| {
            [
                "/var/lib/snapd/snap/bin/firefox",
                "/snap/bin/../bin/firefox",
                "/snap/./bin/firefox",
                "bin/firefox",
            ]
            .iter()
            .any(|hit| candidate == Path::new(hit))
        };
        let is_runnable = |candidate: &Path| candidate == Path::new("bin/firefox");
        let resolve_none = |_: &Path| None;
        let probes = snap_probes(&exists, &is_runnable, &resolve_none);
        for (program, path, cwd) in [
            ("/var/lib/snapd/snap/bin/firefox", None, "/"),
            ("/snap/bin/../bin/firefox", None, "/"),
            ("/snap/./bin/firefox", None, "/"),
            ("bin/firefox", None, "/snap"),
            ("firefox", Some("bin"), "/snap"),
        ] {
            assert!(
                snap_launcher_refusal(
                    std::ffi::OsStr::new(program),
                    &[],
                    path.map(std::ffi::OsStr::new),
                    Path::new(cwd),
                    &probes,
                )
                .is_some(),
                "{program} {path:?} from {cwd} must be refused"
            );
        }
        // A `..` spelling that escapes the launcher directory is not a
        // launcher.
        assert!(
            snap_launcher_refusal(
                std::ffi::OsStr::new("/snap/bin/../usr/bin/firefox"),
                &[],
                None,
                Path::new("/"),
                &probes,
            )
            .is_none(),
            "a spelling outside the launcher directories must not refuse"
        );
    }

    /// Whatever the spelling, a target resolving to the snap binary is a
    /// snap launch — except `snap` itself, which only `snap run` turns
    /// into a confined launch.
    #[test]
    fn snap_precheck_follows_resolution_to_the_snap_binary_and_snap_run() {
        let exists = |_: &Path| false;
        let is_runnable = |candidate: &Path| {
            candidate == Path::new("/usr/bin/snap") || candidate == Path::new("/opt/alias/spotify")
        };
        let resolve = |candidate: &Path| -> Option<PathBuf> {
            if candidate == Path::new("/opt/alias/spotify")
                || candidate == Path::new("/usr/bin/snap")
            {
                Some(PathBuf::from("/usr/bin/snap"))
            } else if candidate == Path::new("/opt/alias/tool") {
                Some(PathBuf::from("/opt/alias/tool"))
            } else {
                None
            }
        };
        let probes = snap_probes(&exists, &is_runnable, &resolve);
        let run_firefox = [OsString::from("run"), OsString::from("firefox")];
        let text = snap_launcher_refusal(
            std::ffi::OsStr::new("/opt/alias/spotify"),
            &[],
            None,
            Path::new("/"),
            &probes,
        )
        .expect("a name resolving to the snap binary must be refused")
        .to_string();
        assert!(text.contains("spotify is a snap application"), "{text}");
        let text = snap_launcher_refusal(
            std::ffi::OsStr::new("snap"),
            &run_firefox,
            Some(std::ffi::OsStr::new("/usr/bin")),
            Path::new("/"),
            &probes,
        )
        .expect("snap run must be refused")
        .to_string();
        assert!(text.contains("firefox is a snap application"), "{text}");
        assert!(text.contains("`snap run firefox`"), "{text}");
        // `snap` without `run` is not a confined launch.
        for args in [
            vec![OsString::from("list")],
            vec![],
            vec![OsString::from("run"), OsString::from("--help")],
        ] {
            // `snap run --help` names no application: still a snap
            // invocation, refused without an application name.
            let refusal = snap_launcher_refusal(
                std::ffi::OsStr::new("snap"),
                &args,
                Some(std::ffi::OsStr::new("/usr/bin")),
                Path::new("/"),
                &probes,
            );
            if args.first().is_some_and(|arg| arg == "run") {
                let text = refusal.expect("snap run must be refused").to_string();
                assert!(
                    text.contains("`snap run` starts a snap application"),
                    "{text}"
                );
            } else {
                assert!(refusal.is_none(), "snap {args:?} must not be refused");
            }
        }
        // A name resolving to itself is not a snap launch.
        assert!(
            snap_launcher_refusal(
                std::ffi::OsStr::new("/opt/alias/tool"),
                &[],
                None,
                Path::new("/"),
                &probes,
            )
            .is_none(),
            "a name resolving to itself must not be refused"
        );
    }

    /// Ubuntu's `/usr/bin/firefox` wrapper shape: a script whose basename
    /// is a snap launcher gets the snap reason, not the interpreter
    /// detour that would fail later inside snap-confine.
    #[test]
    fn script_starting_a_snap_application_gets_the_snap_reason() {
        let dir = tempfile::tempdir().unwrap();
        let script = dir.path().join("firefox");
        std::fs::write(&script, "#!/bin/sh\nexec /snap/bin/firefox \"$@\"\n").unwrap();
        std::fs::set_permissions(&script, std::fs::Permissions::from_mode(0o755)).unwrap();
        let invoker = ChildIdentity::for_invoker()
            .ok()
            .map(|identity| (identity.uid, identity.gid));
        let exists = |candidate: &Path| candidate == Path::new("/snap/bin/firefox");
        let is_runnable = |_: &Path| false;
        let resolve_none = |_: &Path| None;
        let probes = snap_probes(&exists, &is_runnable, &resolve_none);
        let text = check_owned_target_runnable_with(
            script.as_os_str(),
            &[],
            Some(std::ffi::OsStr::new("")),
            Path::new("/"),
            invoker,
            &probes,
        )
        .unwrap_err()
        .to_string();
        assert!(
            text.contains(
                "is a script for /bin/sh that starts the snap application firefox \
                 (/snap/bin/firefox)"
            ),
            "{text}"
        );
        assert!(text.contains("snap-confine"), "{text}");
        assert!(text.contains("Recommended:"), "{text}");
        assert!(
            !text.contains("p11scope run -- /bin/sh"),
            "the failing interpreter detour must not be suggested: {text}"
        );
    }

    /// The snap-starting script refusal is printed to a terminal:
    /// control bytes in the `#!` token and in the resolved path render
    /// escaped, never raw.
    #[test]
    fn snap_script_refusal_escapes_control_bytes_in_token_and_path() {
        let dir = tempfile::tempdir().unwrap();
        let script = dir.path().join("we\x11ird");
        std::fs::write(&script, "#!bad\x07interp --flag\n").unwrap();
        std::fs::set_permissions(&script, std::fs::Permissions::from_mode(0o755)).unwrap();
        let invoker = ChildIdentity::for_invoker()
            .ok()
            .map(|identity| (identity.uid, identity.gid));
        let exists = |candidate: &Path| candidate == Path::new("/snap/bin/we\x11ird");
        let is_runnable = |_: &Path| false;
        let resolve_none = |_: &Path| None;
        let probes = snap_probes(&exists, &is_runnable, &resolve_none);
        let text = check_owned_target_runnable_with(
            script.as_os_str(),
            &[],
            Some(std::ffi::OsStr::new("")),
            Path::new("/"),
            invoker,
            &probes,
        )
        .unwrap_err()
        .to_string();
        assert!(
            text.contains("bad\\u{7}interp"),
            "the token must render escaped: {text}"
        );
        assert!(
            !text.contains("bad\x07interp"),
            "no raw control byte from the token: {text}"
        );
        assert!(
            text.contains("we\\u{11}ird"),
            "the path must render escaped: {text}"
        );
        assert!(
            !text.contains("we\x11ird"),
            "no raw control byte from the path: {text}"
        );
    }

    /// The snap-starting script refusal runs as the observer (possibly
    /// root via sudo) but the `#!` token is only shown when the invoker
    /// could read the file itself: owner, primary group, or other read
    /// bits decide.
    #[test]
    fn snap_script_token_is_hidden_from_an_invoker_who_cannot_read_it() {
        let dir = tempfile::tempdir().unwrap();
        let script = dir.path().join("guarded");
        std::fs::write(&script, "#!/bin/sh\nexec /snap/bin/guarded \"$@\"\n").unwrap();
        std::fs::set_permissions(&script, std::fs::Permissions::from_mode(0o700)).unwrap();
        let meta = std::fs::metadata(&script).unwrap();
        let (owner, group) = (meta.uid(), meta.gid());
        let other = owner.wrapping_add(1);
        let other_group = group.wrapping_add(1);
        assert_ne!(other, owner);
        assert_ne!(other_group, group);
        let exists = |candidate: &Path| candidate == Path::new("/snap/bin/guarded");
        let is_runnable = |_: &Path| false;
        let resolve_none = |_: &Path| None;
        let probes = snap_probes(&exists, &is_runnable, &resolve_none);
        let refusal = |invoker: Option<(u32, u32)>| {
            check_owned_target_runnable_with(
                script.as_os_str(),
                &[],
                Some(std::ffi::OsStr::new("")),
                Path::new("/"),
                invoker,
                &probes,
            )
            .unwrap_err()
            .to_string()
        };
        // Owner-readable: the owner sees the token, anyone else does not.
        let text = refusal(Some((owner, group)));
        assert!(text.contains("is a script for /bin/sh"), "{text}");
        let text = refusal(Some((other, other_group)));
        assert!(
            text.contains("is a script that starts the snap application guarded"),
            "{text}"
        );
        assert!(!text.contains("is a script for"), "{text}");
        // Group-readable: the primary group sees the token.
        std::fs::set_permissions(&script, std::fs::Permissions::from_mode(0o750)).unwrap();
        let text = refusal(Some((other, group)));
        assert!(text.contains("is a script for /bin/sh"), "{text}");
        let text = refusal(Some((other, other_group)));
        assert!(
            text.contains("is a script that starts the snap application guarded"),
            "{text}"
        );
        // Other-readable: everyone sees the token.
        std::fs::set_permissions(&script, std::fs::Permissions::from_mode(0o705)).unwrap();
        let text = refusal(Some((other, other_group)));
        assert!(text.contains("is a script for /bin/sh"), "{text}");
    }

    /// The readability check behind the token drop: owner bits, else
    /// the primary group's, else other's; root reads anything. Write
    /// and execute bits never grant a read.
    #[test]
    fn invoker_read_check_follows_owner_group_other_bits() {
        for (meta_uid, meta_gid, mode, uid, gid, expected) in [
            (1000, 100, 0o600, 1000, 100, true),
            (1000, 100, 0o000, 1000, 100, false),
            (1000, 100, 0o100, 1000, 100, false),
            (1000, 100, 0o040, 2000, 100, true),
            (1000, 100, 0o040, 2000, 200, false),
            (1000, 100, 0o400, 2000, 100, false),
            (1000, 100, 0o004, 2000, 200, true),
            (1000, 100, 0o006, 2000, 200, true),
            (1000, 100, 0o002, 2000, 200, false),
            (1000, 100, 0o000, 0, 0, true),
        ] {
            assert_eq!(
                invoker_can_read_file(meta_uid, meta_gid, mode, uid, gid),
                expected,
                "meta {meta_uid}:{meta_gid} {mode:o} invoker {uid}:{gid}"
            );
        }
    }

    /// The snap-starting script refusal hides the token the same way when
    /// the invoker could not read the file.
    #[test]
    fn snap_script_refusal_hides_an_unreadable_token() {
        let dir = tempfile::tempdir().unwrap();
        let script = dir.path().join("firefox");
        std::fs::write(&script, "#!/bin/sh\nexec /snap/bin/firefox \"$@\"\n").unwrap();
        std::fs::set_permissions(&script, std::fs::Permissions::from_mode(0o700)).unwrap();
        let meta = std::fs::metadata(&script).unwrap();
        let invoker = Some((meta.uid().wrapping_add(1), meta.gid().wrapping_add(1)));
        let exists = |candidate: &Path| candidate == Path::new("/snap/bin/firefox");
        let is_runnable = |_: &Path| false;
        let resolve_none = |_: &Path| None;
        let probes = snap_probes(&exists, &is_runnable, &resolve_none);
        let text = check_owned_target_runnable_with(
            script.as_os_str(),
            &[],
            Some(std::ffi::OsStr::new("")),
            Path::new("/"),
            invoker,
            &probes,
        )
        .unwrap_err()
        .to_string();
        assert!(
            text.contains(
                "is a script that starts the snap application firefox (/snap/bin/firefox)"
            ),
            "{text}"
        );
        assert!(!text.contains("is a script for"), "{text}");
        assert!(text.contains("snap-confine"), "{text}");
    }

    /// Over-refusal: a dangling `/snap/bin/tool` (lstat hit, not runnable)
    /// with a later runnable `/usr/bin/tool` must not refuse — resolution
    /// runs the later binary. `exists` simulates lstat (true for the
    /// dangling link), `is_runnable` simulates stat+file+exec (false for
    /// it), mirroring production.
    #[test]
    fn snap_precheck_skips_a_dangling_snap_shadow_for_the_later_runnable() {
        let exists = |candidate: &Path| {
            candidate == Path::new("/snap/bin/tool") || candidate == Path::new("/usr/bin/tool")
        };
        let is_runnable = |candidate: &Path| candidate == Path::new("/usr/bin/tool");
        let resolve_none = |_: &Path| None;
        let probes = snap_probes(&exists, &is_runnable, &resolve_none);
        assert!(
            snap_launcher_refusal(
                std::ffi::OsStr::new("tool"),
                &[],
                Some(std::ffi::OsStr::new("/snap/bin:/usr/bin")),
                Path::new("/"),
                &probes,
            )
            .is_none(),
            "a dangling /snap/bin shadow must be skipped for the later runnable"
        );
    }

    /// Under-refusal: a non-executable earlier shadow (lstat hit, not
    /// runnable) with a real `/snap/bin/tool` must refuse — resolution
    /// lands on the snap launcher.
    #[test]
    fn snap_precheck_skips_an_earlier_shadow_for_the_snap_launcher() {
        let exists = |candidate: &Path| {
            candidate == Path::new("/tmp/shadow/tool") || candidate == Path::new("/snap/bin/tool")
        };
        let is_runnable = |candidate: &Path| candidate == Path::new("/snap/bin/tool");
        let resolve_none = |_: &Path| None;
        let probes = snap_probes(&exists, &is_runnable, &resolve_none);
        assert!(
            snap_launcher_refusal(
                std::ffi::OsStr::new("tool"),
                &[],
                Some(std::ffi::OsStr::new("/tmp/shadow:/snap/bin")),
                Path::new("/"),
                &probes,
            )
            .is_some(),
            "a non-runnable earlier shadow must be skipped for /snap/bin"
        );
    }

    /// The PATH predicate uses stat semantics (follows symlinks) plus
    /// file+exec, exactly like [`resolve_program_in_path`]: a dangling
    /// symlink (lstat hit, stat miss), a non-executable file and a
    /// directory are not runnable; an executable file and a symlink to one
    /// are. No `/snap/bin` writes needed.
    #[test]
    fn snap_path_candidate_uses_stat_file_and_exec_semantics() {
        use std::os::unix::fs::PermissionsExt as _;
        let dir = tempfile::tempdir().unwrap();
        let dangling = dir.path().join("dangling");
        std::os::unix::fs::symlink(dir.path().join("absent-target"), &dangling).unwrap();
        assert!(
            std::fs::symlink_metadata(&dangling).is_ok(),
            "the dangling link is an lstat hit"
        );
        assert!(
            !snap_path_candidate_is_runnable(&dangling),
            "a dangling symlink is not runnable (stat miss)"
        );
        let shadow = dir.path().join("shadow");
        std::fs::write(&shadow, "not executable\n").unwrap();
        std::fs::set_permissions(&shadow, std::fs::Permissions::from_mode(0o644)).unwrap();
        assert!(!snap_path_candidate_is_runnable(&shadow));
        assert!(!snap_path_candidate_is_runnable(dir.path()));
        let tool = dir.path().join("tool");
        std::fs::copy("/bin/true", &tool).unwrap();
        std::fs::set_permissions(&tool, std::fs::Permissions::from_mode(0o755)).unwrap();
        assert!(snap_path_candidate_is_runnable(&tool));
        let link = dir.path().join("link");
        std::os::unix::fs::symlink(&tool, &link).unwrap();
        assert!(snap_path_candidate_is_runnable(&link));
    }

    /// Sol-full F8: an earlier PATH directory's readable but
    /// non-executable shadow must not stop the search — resolution finds
    /// the later executable (`execvp` semantics), and the ELF guard still
    /// applies to the found candidate.
    #[test]
    fn path_search_skips_a_non_executable_shadow_for_the_later_executable() {
        let shadow_dir = tempfile::tempdir().unwrap();
        let shadow = shadow_dir.path().join("p11scope-shadowed-tool");
        std::fs::write(&shadow, "#!/bin/sh\nexit 0\n").unwrap();
        std::fs::set_permissions(&shadow, std::fs::Permissions::from_mode(0o644)).unwrap();
        let bin_dir = tempfile::tempdir().unwrap();
        let tool = bin_dir.path().join("p11scope-shadowed-tool");
        std::fs::copy("/bin/true", &tool).unwrap();
        std::fs::set_permissions(&tool, std::fs::Permissions::from_mode(0o755)).unwrap();
        let path = std::env::join_paths([shadow_dir.path(), bin_dir.path()]).unwrap();
        let resolved =
            resolve_program_in_path(shadow.file_name().unwrap(), Some(path.as_os_str())).unwrap();
        assert_eq!(resolved, std::fs::canonicalize(&tool).unwrap());
        // Descriptor pinning and the launch-file guard are unchanged:
        // the found candidate still opens and classifies as ELF.
        let (kind, _) = classify_launch_file(&std::fs::File::open(&resolved).unwrap()).unwrap();
        assert_eq!(kind, LaunchKind::Elf);
    }

    /// Sol-full F8 twin: with no executable candidate anywhere, a
    /// shadowed name keeps the permission refusal (`execvp` reports
    /// EACCES, not ENOENT), while a name found nowhere is `NotFound`.
    #[test]
    fn path_search_without_an_executable_candidate_keeps_the_permission_refusal() {
        let shadow_dir = tempfile::tempdir().unwrap();
        let shadow = shadow_dir.path().join("p11scope-shadow-only-tool");
        std::fs::write(&shadow, "not executable\n").unwrap();
        std::fs::set_permissions(&shadow, std::fs::Permissions::from_mode(0o644)).unwrap();
        let path = std::env::join_paths([shadow_dir.path()]).unwrap();
        let error = resolve_program_in_path(shadow.file_name().unwrap(), Some(path.as_os_str()))
            .unwrap_err();
        assert_eq!(error.kind(), io::ErrorKind::PermissionDenied);
        let error = resolve_program_in_path(
            std::ffi::OsStr::new("p11scope-definitely-absent-tool"),
            Some(path.as_os_str()),
        )
        .unwrap_err();
        assert_eq!(error.kind(), io::ErrorKind::NotFound);
    }

    #[test]
    fn prearm_end_cause_maps_ends() {
        use render::PrearmWatchEnd;
        assert_eq!(
            CaptureEnd::DurationExpired.prearm_end_cause(),
            PrearmWatchEnd::ScopeEnd
        );
        assert_eq!(
            CaptureEnd::TargetExit.prearm_end_cause(),
            PrearmWatchEnd::ScopeEnd
        );
        assert_eq!(
            CaptureEnd::LimitReached.prearm_end_cause(),
            PrearmWatchEnd::ScopeEnd
        );
        assert_eq!(CaptureEnd::Signal.prearm_end_cause(), PrearmWatchEnd::Stop);
        assert_eq!(CaptureEnd::Error.prearm_end_cause(), PrearmWatchEnd::Stop);
    }

    fn prearm_test_report(
        module: Option<crate::plan::ModuleId>,
        calls: u64,
        errors: u64,
        in_flight: u64,
    ) -> metrics::SlotReport {
        metrics::SlotReport {
            names: vec!["C_Sign".into()],
            aliased: false,
            semantic_authorized: true,
            module,
            module_ambiguous: false,
            module_unresolved: module.is_none(),
            mode: p11scope_ebpf_common::CounterMode::Latency,
            calls,
            errors,
            in_flight,
            total_ns: 0,
            max_ns: 0,
            buckets: [0; p11scope_ebpf_common::LATENCY_BUCKETS],
            rv_counts: std::collections::BTreeMap::new(),
            file_offset: 0x1000,
            target_object: None,
            ordinals: Vec::new(),
        }
    }

    fn prearm_test_plan(modules: &[u32]) -> crate::plan::AttachPlan {
        let mut plan = crate::plan::AttachPlan::from_slots(Vec::new());
        plan.modules = modules
            .iter()
            .map(|id| crate::plan::ModuleSummary {
                id: crate::plan::ModuleId(*id),
                object: crate::discovery::identity::PinnedObjectId(*id),
                key: crate::plan::TEST_OBJECT,
                path: format!("/prearm/{id}.so"),
                tables: Vec::new(),
                interfaces: 0,
                source: "prearm",
                corroborated: false,
                skipped: Vec::new(),
                admission_class: None,
            })
            .collect();
        plan
    }

    #[test]
    fn prearm_used_modules_counts_attributed_and_inflight() {
        use crate::plan::ModuleId;
        let plan = prearm_test_plan(&[3, 7]);
        let pins = crate::discovery::identity::PinnedObjects::empty();
        let reports = vec![
            prearm_test_report(Some(ModuleId(3)), 5, 0, 0),
            // All-zero rows are silence, not use.
            prearm_test_report(Some(ModuleId(7)), 0, 0, 0),
        ];
        assert_eq!(
            prearm_used_modules(&reports, &plan, &pins),
            BTreeSet::from([ModuleId(3)]),
        );
        // Entered-but-unreturned calls still count as observed use.
        let reports = vec![prearm_test_report(Some(ModuleId(7)), 0, 0, 2)];
        assert_eq!(
            prearm_used_modules(&reports, &plan, &pins),
            BTreeSet::from([ModuleId(7)]),
        );
        // Error rows count too: the endpoint was reached.
        let reports = vec![prearm_test_report(Some(ModuleId(7)), 0, 1, 0)];
        assert_eq!(
            prearm_used_modules(&reports, &plan, &pins),
            BTreeSet::from([ModuleId(7)]),
        );
    }

    #[test]
    fn prearm_used_modules_fails_closed_on_unattributable() {
        use crate::plan::ModuleId;
        let plan = prearm_test_plan(&[3, 7]);
        let pins = crate::discovery::identity::PinnedObjects::empty();
        // An ownerless report no pin resolves marks every module used: a
        // quiet claim needs proven no-use, and unknown association never
        // proves it.
        let mut report = prearm_test_report(None, 4, 0, 0);
        report.target_object = Some(crate::plan::TargetObject {
            dev: (8, 1),
            ino: 42,
            sha256: None,
        });
        assert_eq!(
            prearm_used_modules(&[report], &plan, &pins),
            BTreeSet::from([ModuleId(3), ModuleId(7)]),
        );
        let report = prearm_test_report(None, 4, 0, 0);
        assert_eq!(
            prearm_used_modules(&[report], &plan, &pins),
            BTreeSet::from([ModuleId(3), ModuleId(7)]),
        );
        assert!(prearm_report_owners(&prearm_test_report(None, 4, 0, 0), &plan, &pins).is_empty());
    }

    #[test]
    fn prearm_terminal_freezes_watches_at_stop_not_publication() {
        use crate::attach::BackendSelection;
        use crate::discovery::engine::session_fixture::ScriptedSession;
        use crate::discovery::hooks::HookRegistry;

        // A trivial provider with no standard exports: the watch waits
        // unarmed — the close boundary is what this test pins, not coverage.
        let dir = tempfile::tempdir().unwrap();
        let src = dir.path().join("stop-freeze.c");
        std::fs::write(&src, "int stop_freeze_marker;\n").unwrap();
        let provider = dir.path().join("stop-freeze.so");
        assert!(
            std::process::Command::new("gcc")
                .args(["-shared", "-fPIC", "-o"])
                .arg(&provider)
                .arg(&src)
                .status()
                .unwrap()
                .success()
        );
        let pid = std::process::id();
        // Stop long ago, publication now: duration, signal and error ends
        // all close at the frozen stop, excluding the blind tail.
        for (end, cause) in [
            (
                CaptureEnd::DurationExpired,
                crate::render::PrearmWatchEnd::ScopeEnd,
            ),
            (CaptureEnd::Signal, crate::render::PrearmWatchEnd::Stop),
            (CaptureEnd::Error, crate::render::PrearmWatchEnd::Stop),
        ] {
            let args = CaptureArgs {
                kind: Kind::Profile,
                modules: Vec::new(),
                exclude_modules: vec![],
                manifests: Vec::new(),
                prearm_modules: vec![provider.clone()],
                forwarding_modules: Vec::new(),
                hooks: HookRegistry::builtin(),
                scope: ScopeArg::Pid(pid),
                metrics: false,
                counter_mode: None,
                select_endpoint: None,
                track_short_lived: false,
                verbose: false,
                quiet: false,
                duration: None,
                out: None,
                out_is_stdout: false,
                max_events: None,
                max_scan_pids: None,
                ring_bytes: None,
                drain_interval: None,
                unsafe_requested: false,
                allow_confined_uretprobe: false,
                attach_backend: BackendSelection::default(),
            };
            let view = ProcessView::open(ProcessViewId(0), pid).expect("retain the self view");
            let mut engine =
                Engine::discover(&args, &Scope::Pid(pid), Some(view)).expect("pre-arm discover");
            assert!(engine.has_prearm_watches());
            let session = ScriptedSession::default();
            let reports: Vec<metrics::SlotReport> = Vec::new();
            finish_prearm_terminal(
                &mut engine,
                &session,
                &[],
                end,
                &reports,
                &metrics::KernelEvidence::default(),
                0,
                Some(1000),
                None,
                false,
                None,
            );
            let watch = engine.discovery().modules[0]
                .watch
                .as_ref()
                .expect("finish renders every watch");
            assert_eq!(watch.until_ns, Some(1000));
            assert_eq!(watch.ended_by, Some(cause));
        }
    }

    #[test]
    fn owned_prearm_hold_without_owned_child_threads_no_claim() {
        // A non-`run` scope has no owned child: no hold and no owned-run
        // claim, so the terminal builder keeps every window.
        assert_eq!(owned_prearm_hold(None), (None, false, None));
    }

    #[test]
    fn compose_prearm_hold_pins_every_claim_shape() {
        use crate::discovery::pause::PauseGateHold;

        let held = || PauseGateHold {
            start_ns: Some(5),
            end_ns: Some(900),
            continuous: true,
        };
        // Owned run with a proven hold: the run's pre-spawn scope start
        // replaces the coordinator's arm bound, and the release bound
        // travels alongside for the builder's pre-release check.
        assert_eq!(
            compose_prearm_hold(Some(held()), Some(50), Some(1000), true),
            (
                Some(PauseGateHold {
                    start_ns: Some(50),
                    end_ns: Some(900),
                    continuous: true,
                }),
                true,
                Some(1000),
            )
        );
        // Owned run without a scope start: the unboundable claim start
        // fails closed downstream, never silently armed.
        assert_eq!(
            compose_prearm_hold(Some(held()), None, Some(1000), true),
            (
                Some(PauseGateHold {
                    start_ns: None,
                    end_ns: Some(900),
                    continuous: true,
                }),
                true,
                Some(1000),
            )
        );
        // Owned run without a release bound: the builder withholds every
        // proof, never silently barrier-covered.
        assert_eq!(
            compose_prearm_hold(Some(held()), Some(50), None, true),
            (
                Some(PauseGateHold {
                    start_ns: Some(50),
                    end_ns: Some(900),
                    continuous: true,
                }),
                true,
                None,
            )
        );
        // Passive owned run: no hold, but the owned-run scope and release
        // bound stand.
        assert_eq!(
            compose_prearm_hold(None, Some(50), Some(1000), true),
            (None, true, Some(1000))
        );
        // Non-`run` scope: any hold-shaped input is dropped entirely.
        assert_eq!(
            compose_prearm_hold(Some(held()), Some(50), Some(1000), false),
            (None, false, None)
        );
    }

    /// The owned-run startup wires the barrier-release bound into
    /// `owned.prearm_release_ns` after the barrier release resolves and
    /// before the post-release pause revalidation runs: the bound must be
    /// the release the child actually crossed, and the revalidation must
    /// see the wired claim. The startup needs a live child, so the order
    /// is pinned statically (same `split_once` precedent as
    /// `run_loop_reports_discovery_noise_before_returning_a_capture_error`).
    #[test]
    fn prearm_release_wiring_sits_between_release_and_revalidate() {
        let source = include_str!("run.rs");
        let body = source
            .split_once("fn run_owned_inner_with_host(")
            .unwrap()
            .1
            .split_once("fn preflight_uretprobe_hazard(")
            .unwrap()
            .0;
        let released = body
            .find(".release_until(")
            .expect("owned startup releases the child barrier");
        let wired = body
            .find("owned.prearm_release_ns = ")
            .expect("owned startup wires the pre-arm release bound");
        let revalidated = body
            .find("post_release_pass(")
            .expect("owned startup revalidates after the release");
        let step = source
            .split_once("fn post_release_pass(")
            .expect("the post-release step exists")
            .1
            .split_once("\n}\n")
            .expect("the post-release step ends")
            .0;
        assert!(
            step.contains(".revalidate_after_release("),
            "the post-release step is the revalidation"
        );
        assert!(
            released < wired && wired < revalidated,
            "prearm_release_ns is wired after release_until and before revalidate_after_release"
        );
        assert_eq!(
            body.matches("owned.prearm_release_ns = ").count(),
            1,
            "one wiring site feeds the terminal claim"
        );
    }

    /// The owned-run startup preloads the overlay-witness BPF session
    /// before spawning the child: the one-time session load (BPF
    /// verifier plus functional probe, ~1s in slow guests) must not
    /// land inside a 500ms pause-cycle engine apply, where it
    /// fail-closes the first overlay join unavailable and turns the
    /// pause partial. The startup needs a live child, so the order is
    /// pinned statically (same `split_once` precedent as
    /// `prearm_release_wiring_sits_between_release_and_revalidate`).
    #[test]
    fn witness_preload_sits_before_owned_spawn() {
        let source = include_str!("run.rs");
        let body = source
            .split_once("fn run_owned_inner_with_host(")
            .unwrap()
            .1
            .split_once("fn preflight_uretprobe_hazard(")
            .unwrap()
            .0;
        let preloaded = body
            .find("overlay_witness::preload_session()")
            .expect("owned startup preloads the witness session");
        let spawned = body
            .find("OwnedChild::spawn_verbose_as(")
            .expect("owned startup spawns the child");
        assert!(
            preloaded < spawned,
            "witness preload sits before OwnedChild::spawn_verbose_as"
        );
        assert_eq!(
            body.matches("overlay_witness::preload_session()").count(),
            1,
            "one preload site feeds the owned run"
        );
    }

