    #[test]
    fn refused_multi_host_precedes_capture_sinks_and_empty_provider_discovery() {
        use crate::attach::{MultiHostRefusal, MultiHostStage};
        let dir = tempfile::tempdir().unwrap();
        let output = dir.path().join("existing-trace.jsonl");
        for selection in [
            BackendSelection::Auto,
            BackendSelection::Multi,
            BackendSelection::Singles,
        ] {
            for errno in [libc::EOPNOTSUPP, libc::EPERM, libc::EINVAL] {
                std::fs::write(&output, b"keep existing output\n").unwrap();
                let mut args = capture_args(ScopeArg::System);
                args.kind = Kind::Trace;
                args.duration = Some(Duration::from_millis(1));
                args.out = Some(output.clone());
                args.attach_backend = selection;
                args.allow_confined_uretprobe = true;
                let refusal = MultiHostRefusal::for_test(MultiHostStage::SelfLink, Some(errno));
                let error = capture_with_host(&args, &|| Err(refusal)).unwrap_err();
                assert_eq!(
                    error.downcast_ref::<MultiHostRefusal>(),
                    Some(&refusal),
                    "{error:#}"
                );
                assert_eq!(std::fs::read(&output).unwrap(), b"keep existing output\n");
                assert_eq!(
                    std::fs::read_dir(dir.path()).unwrap().count(),
                    1,
                    "no sink temp or discovery artifact"
                );
            }
        }
    }

    #[test]
    fn refused_multi_host_precedes_owned_workload_and_output() {
        use crate::attach::{MultiHostRefusal, MultiHostStage};
        let dir = tempfile::tempdir().unwrap();
        let sentinel = dir.path().join("workload-ran");
        let output = dir.path().join("existing-profile.json");
        let script = format!("printf ran > '{}'", sentinel.display());
        for selection in [
            BackendSelection::Auto,
            BackendSelection::Multi,
            BackendSelection::Singles,
        ] {
            for errno in [libc::EOPNOTSUPP, libc::EPERM, libc::EINVAL] {
                std::fs::write(&output, b"keep existing report\n").unwrap();
                let mut args = run_args(cli::PausePolicy::Never, &["/bin/sh", "-c", &script]);
                args.duration = Some(Duration::from_millis(1));
                args.out = Some(output.clone());
                args.attach_backend = selection;
                args.allow_confined_uretprobe = true;
                let refusal = MultiHostRefusal::for_test(MultiHostStage::SelfLink, Some(errno));
                let error = run_owned_inner_with_host(&args, Arc::new(SignalState::new()), &|| {
                    // Include an unreleased fork child; do not merely wait
                    // for its sentinel command to execute. Other test
                    // threads' children are excluded and none is reaped.
                    // SAFETY: siginfo_t is a zeroable C output structure.
                    let mut status: libc::siginfo_t = unsafe { std::mem::zeroed() };
                    // SAFETY: a valid output pointer; WNOWAIT is read-only.
                    let waited = unsafe {
                        libc::waitid(
                            libc::P_ALL,
                            0,
                            &mut status,
                            libc::WEXITED
                                | libc::WSTOPPED
                                | libc::WNOHANG
                                | libc::WNOWAIT
                                | libc::__WNOTHREAD,
                        )
                    };
                    assert_eq!(
                        (waited, io::Error::last_os_error().raw_os_error()),
                        (-1, Some(libc::ECHILD)),
                        "user workload was forked before host admission",
                    );
                    Err(refusal)
                })
                .unwrap_err();
                assert_eq!(
                    error.downcast_ref::<MultiHostRefusal>(),
                    Some(&refusal),
                    "{error:#}"
                );
                assert!(!sentinel.exists(), "the user workload must not execute");
                assert_eq!(std::fs::read(&output).unwrap(), b"keep existing report\n");
            }
        }
    }

    /// 7.10b widening wins (controller ruling): an owned `run` accepts
    /// `--track-short-lived` and arms the PID target-exec consumer for its
    /// direct child via `engine.arm_extensive(..., Some(pid))` (pinned by
    /// `owned_run_under_cgroup_scope_arms_pid_consumer_for_direct_child`);
    /// the old pre-fork "records nothing beside run" refusal is gone. With
    /// a runnable command the flag reaches host admission: a refusing host
    /// is consulted and its refusal surfaces, never the flag message.
    #[test]
    fn owned_run_track_short_lived_reaches_host_admission() {
        use crate::attach::{MultiHostRefusal, MultiHostStage};
        let mut args = run_args(cli::PausePolicy::Never, &["/bin/true"]);
        args.track_short_lived = true;
        let probes = std::cell::Cell::new(0);
        let refusal = MultiHostRefusal::for_test(MultiHostStage::ProgramLoad, Some(libc::EACCES));
        let host = || {
            probes.set(probes.get() + 1);
            Err(refusal)
        };
        let error = run_owned_inner_with_host(&args, Arc::new(SignalState::new()), &host)
            .err()
            .unwrap();
        assert_eq!(
            error.downcast_ref::<MultiHostRefusal>(),
            Some(&refusal),
            "{error:#}"
        );
        assert_eq!(probes.get(), 1);
    }

    /// File learning arms under detailed policies only: aggregate
    /// metrics and every counter mode stay unarmed.
    #[test]
    fn file_learning_arms_only_for_detailed_policies() {
        use p11scope_ebpf_common::CounterMode;
        assert!(file_learning_armed(CapturePolicy::Allowlisted));
        assert!(file_learning_armed(
            CapturePolicy::UnsafeUnvalidatedMetadata
        ));
        assert!(!file_learning_armed(CapturePolicy::AggregateOnly));
        for mode in [
            CounterMode::Counts,
            CounterMode::Timestamps,
            CounterMode::Latency,
        ] {
            assert!(!file_learning_armed(CapturePolicy::Counter(mode)));
        }
    }

    /// 7.10b widening keeps the documented counter-mode refusal: beside
    /// `--counter-mode` the flag is refused by name at policy selection,
    /// before anything is forked or the host is consulted.
    #[test]
    fn owned_run_track_short_lived_refuses_beside_counter_mode_before_fork() {
        use p11scope_ebpf_common::CounterMode;
        for mode in [
            CounterMode::Counts,
            CounterMode::Timestamps,
            CounterMode::Latency,
        ] {
            let mut args = run_args(cli::PausePolicy::Never, &["/bin/true"]);
            args.metrics = true;
            args.counter_mode = Some(mode);
            args.track_short_lived = true;
            let error = run_owned_inner_with_host(&args, Arc::new(SignalState::new()), &|| {
                panic!("host admission must not run for a refused flag combination")
            })
            .unwrap_err();
            assert!(
                format!("{error:#}").contains(&format!(
                    "--track-short-lived cannot be combined with --counter-mode {}",
                    mode.name()
                )),
                "{mode:?}: {error:#}"
            );
        }
    }

    /// The owned-run arm site passes the `owned_extensive_arm` decision
    /// through to `engine.arm_extensive` unchanged: the effective flag
    /// for `args.track_short_lived` under this policy, plus the direct
    /// child as the explicit owned target. A `false`/`None` regression
    /// at the call site disarms the PID target-exec consumer. The
    /// startup needs a live child, so the wiring is pinned statically
    /// (same `split_once` precedent as
    /// `witness_preload_sits_before_owned_spawn`); the decision itself
    /// is pinned behaviorally by
    /// `owned_run_arm_decision_passes_effective_flag_and_direct_child`.
    #[test]
    fn owned_run_arm_site_uses_owned_decision() {
        let source = include_str!("run.rs");
        let body = source
            .split_once("fn run_owned_inner_with_host(")
            .unwrap()
            .1
            .split_once("fn preflight_uretprobe_hazard(")
            .unwrap()
            .0;
        assert!(
            body.contains("owned_extensive_arm(args.track_short_lived, policy, pid)"),
            "owned startup arms through the owned decision helper"
        );
        assert!(
            body.contains("engine.arm_extensive(extensive, policy, owned)"),
            "owned startup passes the decision through unchanged"
        );
        assert_eq!(
            body.matches("engine.arm_extensive(").count(),
            1,
            "one arm site feeds the owned run"
        );
    }

    /// The owned-`run` arm decision carries the effective flag plus the
    /// direct child as the explicit owned target: a `false`/`None`
    /// regression here disarms the PID target-exec consumer the owned
    /// run must arm.
    #[test]
    fn owned_run_arm_decision_passes_effective_flag_and_direct_child() {
        // Every Detailed policy arms with the flag set, and carries the
        // child either way.
        for policy in [
            CapturePolicy::Allowlisted,
            CapturePolicy::UnsafeUnvalidatedMetadata,
            CapturePolicy::AggregateOnly,
        ] {
            assert_eq!(
                owned_extensive_arm(true, policy, 4242),
                (true, Some(4242)),
                "{policy:?}"
            );
            assert_eq!(
                owned_extensive_arm(false, policy, 4242),
                (false, Some(4242)),
                "{policy:?}"
            );
        }
        // A counter policy never arms, whatever the flag; the child is
        // still carried (the CLI combination already refused above).
        for mode in [
            p11scope_ebpf_common::CounterMode::Counts,
            p11scope_ebpf_common::CounterMode::Timestamps,
            p11scope_ebpf_common::CounterMode::Latency,
        ] {
            assert_eq!(
                owned_extensive_arm(true, CapturePolicy::Counter(mode), 4242),
                (false, Some(4242)),
                "{mode:?}"
            );
        }
    }

    #[test]
    fn counter_capture_and_run_require_host_after_build_policy_validation() {
        use crate::attach::{MultiHostRefusal, MultiHostStage};
        use p11scope_ebpf_common::CounterMode;
        for mode in [
            CounterMode::Counts,
            CounterMode::Timestamps,
            CounterMode::Latency,
        ] {
            for backend in [
                BackendSelection::Auto,
                BackendSelection::Multi,
                BackendSelection::Singles,
            ] {
                for owned in [false, true] {
                    let probes = std::cell::Cell::new(0);
                    let refusal =
                        MultiHostRefusal::for_test(MultiHostStage::ProgramLoad, Some(libc::EACCES));
                    let host = || {
                        probes.set(probes.get() + 1);
                        Err(refusal)
                    };
                    let error = if owned {
                        let mut args = run_args(cli::PausePolicy::Never, &["/bin/true"]);
                        args.metrics = true;
                        args.counter_mode = Some(mode);
                        args.attach_backend = backend;
                        run_owned_inner_with_host(&args, Arc::new(SignalState::new()), &host)
                            .err()
                            .unwrap()
                    } else {
                        let mut args = capture_args(ScopeArg::System);
                        args.metrics = true;
                        args.counter_mode = Some(mode);
                        args.attach_backend = backend;
                        capture_with_host(&args, &host).unwrap_err()
                    };
                    if cfg!(p11scope_counter_objects) {
                        assert_eq!(
                            error.downcast_ref::<MultiHostRefusal>(),
                            Some(&refusal),
                            "{error:#}"
                        );
                        assert_eq!(probes.get(), 1);
                    } else {
                        assert!(
                            error
                                .to_string()
                                .starts_with("counter-mode-unavailable-in-build:"),
                            "{error:#}"
                        );
                        assert_eq!(probes.get(), 0);
                    }
                }
            }
        }
    }

    #[test]
    fn counter_modes_pass_the_cli_gate_into_capture_setup() {
        // Builds without counter objects (SMALL) refuse every mode
        // by name at the policy gate instead of reaching setup.
        let objects = env!("P11SCOPE_COUNTER_OBJECTS_ENABLED") == "1";
        for mode in [
            p11scope_ebpf_common::CounterMode::Counts,
            p11scope_ebpf_common::CounterMode::Timestamps,
            p11scope_ebpf_common::CounterMode::Latency,
        ] {
            let mut args = capture_args(ScopeArg::Pid(i32::MAX as u32));
            args.metrics = true;
            args.counter_mode = Some(mode);
            // The blanket counter refusal is gone: the next refusal is the
            // nested-namespace poison inside real capture setup (still no
            // target or BPF work). Reaching it proves the mode passed CLI
            // selection.
            let error = nested(|| capture(&args)).expect_err("counter mode must reach real setup");
            let text = format!("{error:#}");
            assert!(!text.contains("counter-mode-unwired"), "{mode:?}: {text}");
            if objects {
                assert!(
                    text.starts_with("pid-namespace-mismatch:"),
                    "{mode:?}: {text}"
                );
            } else {
                assert!(
                    text.starts_with("counter-mode-unavailable-in-build:"),
                    "{mode:?}: {text}"
                );
            }
        }
    }

    #[test]
    fn counter_modes_pass_the_cli_gate_into_owned_run_setup() {
        // Builds without counter objects (SMALL) refuse every mode
        // by name at the policy gate instead of reaching setup.
        let objects = env!("P11SCOPE_COUNTER_OBJECTS_ENABLED") == "1";
        for mode in [
            p11scope_ebpf_common::CounterMode::Counts,
            p11scope_ebpf_common::CounterMode::Timestamps,
            p11scope_ebpf_common::CounterMode::Latency,
        ] {
            let mut args = run_args(
                cli::PausePolicy::Never,
                &["/definitely/missing/p11scope-counter-cli-gate"],
            );
            args.metrics = true;
            args.counter_mode = Some(mode);
            // Same gate proof on the run path: the poison fires before
            // anything is resolved or forked.
            let error =
                nested(|| run_owned(&args)).expect_err("counter mode must reach real setup");
            let text = format!("{error:#}");
            assert!(!text.contains("counter-mode-unwired"), "{mode:?}: {text}");
            if objects {
                assert!(
                    text.starts_with("pid-namespace-mismatch:"),
                    "{mode:?}: {text}"
                );
            } else {
                assert!(
                    text.starts_with("counter-mode-unavailable-in-build:"),
                    "{mode:?}: {text}"
                );
            }
        }
    }

    #[test]
    fn counter_modes_select_counter_policies_through_capture_policy() {
        // Builds without counter objects (SMALL) refuse every mode
        // by name instead of selecting it.
        let objects = env!("P11SCOPE_COUNTER_OBJECTS_ENABLED") == "1";
        for mode in [
            p11scope_ebpf_common::CounterMode::Counts,
            p11scope_ebpf_common::CounterMode::Timestamps,
            p11scope_ebpf_common::CounterMode::Latency,
        ] {
            // Metrics profile/run select the counter policy for every mode.
            if objects {
                assert_eq!(
                    capture_policy(Kind::Profile, true, false, Some(mode), false, None).unwrap(),
                    CapturePolicy::Counter(mode),
                    "{mode:?}"
                );
            } else {
                let error = capture_policy(Kind::Profile, true, false, Some(mode), false, None)
                    .unwrap_err();
                let text = format!("{error:#}");
                assert!(
                    text.contains("counter-mode-unavailable-in-build"),
                    "{mode:?}: {text}"
                );
                assert!(!text.contains("counter-mode-unwired"), "{text}");
            }
            // Every other combination refuses by name, never with the
            // removed blanket token.
            let requires_metrics = format!(
                "--counter-mode {} requires --mode metrics on profile or run",
                mode.name()
            );
            for (kind, metrics, unsafe_requested, expected) in [
                (Kind::Trace, false, false, requires_metrics.as_str()),
                (Kind::Trace, true, false, requires_metrics.as_str()),
                (Kind::Profile, false, false, requires_metrics.as_str()),
                (
                    Kind::Profile,
                    true,
                    true,
                    "--counter-mode cannot be combined with --unsafe-unvalidated-metadata",
                ),
            ] {
                let error =
                    capture_policy(kind, metrics, unsafe_requested, Some(mode), false, None)
                        .unwrap_err();
                let text = format!("{error:#}");
                assert_eq!(
                    text, expected,
                    "{mode:?} metrics={metrics} unsafe={unsafe_requested}"
                );
                assert!(!text.contains("counter-mode-unwired"), "{text}");
            }
        }
        // Omission keeps every legacy selection.
        assert_eq!(
            capture_policy(Kind::Profile, false, false, None, false, None).unwrap(),
            CapturePolicy::Allowlisted
        );
        assert_eq!(
            capture_policy(Kind::Profile, true, false, None, false, None).unwrap(),
            CapturePolicy::AggregateOnly
        );
        assert_eq!(
            capture_policy(Kind::Trace, false, false, None, false, None).unwrap(),
            CapturePolicy::Allowlisted
        );
    }

    // 614b P2#2: `--track-short-lived` refuses beside every counter
    // mode at policy selection, before build/flavor checks, so a
    // counter session can never arm the exe-identity read. Detailed
    // selections keep accepting the flag.
    #[test]
    fn counter_modes_refuse_track_short_lived_through_capture_policy() {
        for mode in [
            p11scope_ebpf_common::CounterMode::Counts,
            p11scope_ebpf_common::CounterMode::Timestamps,
            p11scope_ebpf_common::CounterMode::Latency,
        ] {
            let error =
                capture_policy(Kind::Profile, true, false, Some(mode), true, None).unwrap_err();
            assert_eq!(
                format!("{error:#}"),
                format!(
                    "--track-short-lived cannot be combined with --counter-mode {}: \
                     extensive mode arms Detailed captures only",
                    mode.name()
                ),
                "{mode:?}"
            );
        }
        // Detailed positives: the flag alone changes no selection.
        assert_eq!(
            capture_policy(Kind::Profile, false, false, None, true, None).unwrap(),
            CapturePolicy::Allowlisted
        );
        assert_eq!(
            capture_policy(Kind::Profile, true, false, None, true, None).unwrap(),
            CapturePolicy::AggregateOnly
        );
        assert_eq!(
            capture_policy(Kind::Trace, false, false, None, true, None).unwrap(),
            CapturePolicy::Allowlisted
        );
    }

    // 6.15: endpoint selection details a counter broad only. The CLI
    // refuses this first; the policy re-checks so no programmatic
    // caller can arm a selection the driver cannot resolve. A
    // selection beside a counter mode changes no policy by itself.
    #[test]
    fn select_endpoint_requires_counter_policy_through_capture_policy() {
        for (kind, metrics) in [
            (Kind::Profile, true),
            (Kind::Profile, false),
            (Kind::Trace, false),
        ] {
            let error =
                capture_policy(kind, metrics, false, None, false, Some("C_Sign")).unwrap_err();
            assert_eq!(
                format!("{error:#}"),
                "--select-endpoint requires --counter-mode counts|timestamps|latency \
                 on --mode metrics",
                "{kind:?}/{metrics}"
            );
        }
        // Beside a counter mode the selection rides along unchanged.
        // Builds without counter objects refuse by name instead.
        if env!("P11SCOPE_COUNTER_OBJECTS_ENABLED") == "1" {
            let mode = p11scope_ebpf_common::CounterMode::Counts;
            assert_eq!(
                capture_policy(
                    Kind::Profile,
                    true,
                    false,
                    Some(mode),
                    false,
                    Some("C_Sign")
                )
                .unwrap(),
                CapturePolicy::Counter(mode),
            );
        }
    }

    // 7.10b widening: the exe-identity read arms on every Detailed
    // lane and scope that publishes a hint — the helper only needs
    // the flag and the policy, since trace, metrics and exact-PID
    // all publish now (gap splits on cgroup/system, target-exec
    // hints on PID scope). Counter policies still never arm.
    #[test]
    fn extensive_arms_all_detailed_policies() {
        // Every Detailed policy arms with the flag set.
        for policy in [
            CapturePolicy::Allowlisted,
            CapturePolicy::UnsafeUnvalidatedMetadata,
            CapturePolicy::AggregateOnly,
        ] {
            assert!(extensive_effective(true, policy), "{policy:?}");
            assert!(!extensive_effective(false, policy), "{policy:?}");
        }
        // P2#2 confinement still holds inside the helper: a counter
        // policy never arms, whatever the other inputs.
        for mode in [
            p11scope_ebpf_common::CounterMode::Counts,
            p11scope_ebpf_common::CounterMode::Timestamps,
            p11scope_ebpf_common::CounterMode::Latency,
        ] {
            assert!(
                !extensive_effective(true, CapturePolicy::Counter(mode)),
                "{mode:?}"
            );
        }
    }

    #[test]
    fn output_sink_open_marks_dash_stdout_for_trace() {
        // `-o -` on a trace opens no file but records stdout as the
        // complete sink; plain omission stays sink-less, and profile
        // (which refuses the dash at parse) never takes the arm.
        assert!(matches!(
            OutputSink::open(Kind::Trace, None, true),
            Ok(OutputSink::TraceStdout)
        ));
        assert!(matches!(
            OutputSink::open(Kind::Trace, None, false),
            Ok(OutputSink::None)
        ));
        assert!(matches!(
            OutputSink::open(Kind::Profile, None, false),
            Ok(OutputSink::None)
        ));
    }

    #[test]
    fn run_loop_forwards_stdout_sink_to_capture_trace() {
        // `-o -` opens no file: the dash rides run_loop into
        // capture_trace as the operator's variable (never a bare
        // out=None collapse or a false literal), where the terminal
        // keeps EVIDENCE on stdout. The emitter twins prove the
        // behavior; this pins the wiring in source.
        let source = include_str!("run.rs");
        let trace_arm = source
            .split_once("fn run_loop(")
            .expect("run loop")
            .1
            .split_once("Kind::Trace =>")
            .expect("trace arm")
            .1
            .split_once("engine.report_discovery_noise();")
            .expect("loop end")
            .0;
        assert!(
            trace_arm.contains("OutputSink::TraceStdout => (None, true)"),
            "run_loop must map the dash sink to no file plus the stdout flag"
        );
        let call = trace_arm
            .split_once("capture_trace(")
            .expect("trace call")
            .1
            .split_once(')')
            .expect("call end")
            .0;
        assert!(
            call.contains("stdout_is_file,"),
            "forward the stdout flag, not a literal"
        );
        assert!(
            !call.contains("false"),
            "no false literal in the forwarded positions"
        );
    }

    #[test]
    fn run_loop_forwards_built_counter_inputs_to_capture_profile() {
        // The profile loop builds real CounterCaptureInputs from the active
        // policy instead of passing None. The privileged collection cell
        // proves it behaviorally; this pins the wiring in source.
        let source = include_str!("run.rs");
        let profile_arm = source
            .split_once("fn run_loop(")
            .expect("run loop")
            .1
            .split_once("Kind::Trace =>")
            .expect("profile arm")
            .0;
        assert!(
            profile_arm.contains("counter_inputs_for_capture(policy, engine)"),
            "run_loop must build counter inputs from the active policy"
        );
        let call = profile_arm
            .split_once("capture_profile(")
            .expect("profile call")
            .1
            .split_once(')')
            .expect("call end")
            .0;
        assert!(
            call.contains("counter_inputs,"),
            "forward built inputs, not None"
        );
        assert!(
            !call.contains("None"),
            "no None literal in the inputs position"
        );
    }

    #[test]
    fn run_loop_forwards_endpoint_selection_to_capture_profile() {
        // 6.15: the CLI selection rides run_loop into capture_profile
        // as the operator's variable (never a None literal), where the
        // metrics selection stage resolves it and the composer adds
        // the additive ledger. The stage/composer behavior is proven
        // by the driver twins; this pins the wiring in source.
        let source = include_str!("run.rs");
        let profile_arm = source
            .split_once("fn run_loop(")
            .expect("run loop")
            .1
            .split_once("Kind::Trace =>")
            .expect("profile arm")
            .0;
        let call = profile_arm
            .split_once("capture_profile(")
            .expect("profile call")
            .1
            .split_once(')')
            .expect("call end")
            .0;
        assert!(
            call.contains("select_endpoint,"),
            "forward the operator selection, not None"
        );
        assert!(
            !call.contains("None"),
            "no None literal in the forwarded positions"
        );
        let profile = source
            .split_once("fn capture_profile(")
            .expect("profile loop")
            .1
            .split_once("fn write_json_report")
            .expect("report site")
            .0;
        assert!(
            profile.contains("run_metrics_selection_stage("),
            "capture_profile must resolve the selection before the loop"
        );
        assert!(
            profile.contains("with_selected_detail(j, ledger)"),
            "capture_profile must compose the additive ledger"
        );
        // K0: the close witness snapshot precedes quiescence, which
        // invalidates the PID lifecycle tap; a snapshot past it would
        // always read terminal and void every window as caller-changed.
        let snapshot = profile
            .find("k0_close_facts = k0_window.as_ref()")
            .expect("K0 close snapshot");
        let quiesce = profile.find("quiesce_terminal(").expect("quiescence");
        assert!(
            snapshot < quiesce,
            "capture_profile must snapshot the K0 close witness before quiescence"
        );
        // K0 tail: the shutdown-tail split collects exactly the records
        // the pre-quiescence snapshot cannot see — the quiescence-staged
        // suffix plus the terminal drain — and hands them to the close.
        // All four sites must survive in order: the staged-suffix slice,
        // the observed quiescence apply, the guarded terminal branch,
        // and the take into the close.
        let suffix = profile
            .find("staged_records[k0_prefix_records..]")
            .expect("K0 tail staged suffix");
        let observed = profile
            .find("apply_quiesced_discovery_observed(")
            .expect("K0 tail observed quiescence");
        let terminal = profile
            .find("drain_discovery_terminal_to_position_observed(")
            .expect("K0 tail observed terminal");
        let take = profile
            .find("tail_records: k0_tail_records.take()")
            .expect("K0 tail take");
        assert!(
            suffix < observed && observed < terminal && terminal < take,
            "capture_profile must collect the K0 tail in order"
        );
        // K0 loss snapshots: the open passes the comparable discovery
        // losses (the live total minus exit-only truncations) and whether
        // the capture is owned before the loop, and the close reads them
        // again after the terminal drain, inside `run_terminal`, so
        // growth inside the window voids the detail.
        let open = profile.find("open_k0_production(").expect("K0 open");
        let open_call = &profile[open..];
        let open_losses = open_call
            .find("k0_comparable_losses(&engine.capture_facts())")
            .expect("K0 open losses");
        let open_owned = open_call.find("owned.is_some(),").expect("K0 open owned");
        let open_end = open_call.find(");").expect("K0 open call end");
        assert!(
            open_losses < open_end && open_owned < open_end,
            "the K0 open passes its losses and owned flag"
        );
        let terminal_fn = source
            .split_once("fn run_terminal(")
            .expect("run_terminal")
            .1;
        // The close snapshots facts, then comparable losses from them
        // (production precedes the tests module, so the first match is
        // the production site, not this string).
        let facts_binding = terminal_fn
            .find("let after_facts = context.0.capture_facts()")
            .expect("K0 close facts");
        let close_binding = terminal_fn
            .find("let after_losses =")
            .expect("K0 close binding");
        assert!(
            facts_binding < close_binding,
            "the K0 close snapshots facts before losses"
        );
        let close_call = &terminal_fn[close_binding..];
        let close_losses = close_call
            .find("k0_comparable_losses(&after_facts)")
            .expect("K0 close losses");
        let close_end = close_call.find(';').expect("K0 close binding end");
        assert!(
            close_losses < close_end,
            "the K0 close snapshots its comparable losses"
        );
        let close = terminal_fn.find("close_k0_production(").expect("K0 close");
        let terminal_read = terminal_fn.find(".terminal(").expect("broad terminal read");
        assert!(
            terminal_read < close_binding && close_binding < close,
            "run_terminal must snapshot the K0 close losses after the terminal read and before the close"
        );
    }

    /// m5: the K0 debug line prints on the terminal-failure path too,
    /// so a quiesce-error void shows its counts instead of failing the
    /// live cells with a parse error. Both arms gate on the same
    /// variable and share the format helper.
    #[test]
    fn k0_debug_line_prints_on_the_terminal_failure_path() {
        let source = include_str!("run.rs");
        let production = source.split_once("#[cfg(test)]\nmod tests").unwrap().0;
        let terminal_fn = production.split_once("fn run_terminal(").unwrap().1;
        assert_eq!(
            terminal_fn.matches("var_os(\"P11SCOPE_K0_DEBUG\")").count(),
            2,
            "the normal close and the terminal-failure arm both gate the line"
        );
        assert_eq!(
            production.matches("format_k0_debug_line(").count(),
            3,
            "one format helper plus its two call sites"
        );
    }

    #[test]
    fn counter_inputs_come_from_policy_and_counters_plan() {
        use crate::attach::CapturePolicy;
        use crate::discovery::engine::Engine;
        let mut engine = Engine::empty_for_test();
        let plan = crate::plan::AttachPlan::from_slots_with_policy(
            vec![],
            crate::plan::AdmissionPolicy::Counters(
                crate::capacity::CounterBudget::new(512).unwrap(),
            ),
        )
        .unwrap();
        engine.inject_counter_start_state_for_test(
            crate::attach::Scope::Pid(1),
            Vec::new(),
            plan,
            crate::discovery::identity::PinnedObjects::empty(),
            Vec::new(),
        );
        // Counter policy + Counters plan -> bounded inputs from the budget.
        let inputs = counter_inputs_for_capture(
            CapturePolicy::Counter(p11scope_ebpf_common::CounterMode::Counts),
            &engine,
        )
        .expect("counter plan builds inputs");
        assert_eq!(inputs.rows(), 512);
        assert_eq!(inputs.rv_keys(), 65536);
        // Non-counter policies never build inputs.
        for policy in [CapturePolicy::AggregateOnly, CapturePolicy::Allowlisted] {
            assert!(
                counter_inputs_for_capture(policy, &engine).is_none(),
                "{policy:?} builds no counter inputs"
            );
        }
        // Counter policy without a Counters plan builds nothing.
        let mut detailed = Engine::empty_for_test();
        detailed.inject_counter_start_state_for_test(
            crate::attach::Scope::Pid(1),
            Vec::new(),
            crate::plan::AttachPlan::from_slots(vec![]),
            crate::discovery::identity::PinnedObjects::empty(),
            Vec::new(),
        );
        assert!(
            counter_inputs_for_capture(
                CapturePolicy::Counter(p11scope_ebpf_common::CounterMode::Counts),
                &detailed
            )
            .is_none()
        );
    }

    /// Review P2: a PID-scoped capture refuses by name before its target is
    /// even opened (this PID cannot exist).
    #[test]
    fn a_nested_observer_refuses_a_pid_capture_before_opening_its_target() {
        let error = nested(|| {
            capture(&capture_args(ScopeArg::Pid(i32::MAX as u32)))
                .expect_err("a nested observer must refuse --pid")
        });
        let text = format!("{error:#}");
        assert!(
            text.starts_with(&format!(
                "pid-namespace-mismatch: refusing --pid {}:",
                i32::MAX
            )),
            "{text}"
        );
    }

    /// DR-RETRO-PIDNS-2: a `/proc` with no entry for this observer refuses
    /// a --system capture by name before discovery or the uretprobe
    /// self-probe, which would otherwise fail and point at the override.
    #[test]
    fn an_unserved_proc_refuses_a_system_capture_by_name() {
        let unserved = crate::pidns::PidNumbering {
            observer: crate::pidns::ObserverPidNs::Unknown("/proc/self/ns/pid: ENOENT".into()),
            proc_view: crate::pidns::ProcView::Unserved("/proc/self: ENOENT".into()),
        };
        let error = crate::pidns::test_seam::with_numbering(unserved, || {
            capture(&capture_args(ScopeArg::System)).expect_err("an unserved /proc must refuse")
        });
        let text = format!("{error:#}");
        assert!(
            text.starts_with(
                "pid-namespace-mismatch: refusing a --system capture: the mounted /proc"
            ),
            "{text}"
        );
        assert!(!text.contains("--allow-uretprobe"), "{text}");
    }

    /// Review P3: the published evidence reads the observer's numbering,
    /// so a nested capture can never seal `exact`/COMPLETE.
    #[test]
    fn a_nested_observers_evidence_names_its_numbering_as_a_gap() {
        let evidence = nested(|| terminal_evidence_for(render::SchedulingEvidence::default()));
        assert_eq!(evidence.pid_namespace.observer, "nested");
        assert!(
            evidence
                .gap_classes
                .observation
                .causes
                .contains(&"pid_namespace"),
            "{:?}",
            evidence.gap_classes
        );
        assert_eq!(evidence.completeness, "PARTIAL");
        let agreeing = terminal_evidence_for(render::SchedulingEvidence::default());
        assert_eq!(agreeing.pid_namespace.observer, "initial");
    }

    struct CgroupProofChild(std::process::Child);

    impl Drop for CgroupProofChild {
        fn drop(&mut self) {
            let _ = self.0.kill();
            let _ = self.0.wait();
        }
    }

    fn nested_own_numbering_for_test() -> crate::pidns::PidNumbering {
        crate::pidns::PidNumbering {
            observer: crate::pidns::ObserverPidNs::Nested,
            proc_view: crate::pidns::ProcView::Own,
        }
    }

    /// DR-K8S-5 carve-out: a nested observer, a `--cgroup` scope, an
    /// empty plan, and every member visible and readable (two live
    /// provider-free processes, the kind-e2e idle pod shape) ends as
    /// an ordinary empty capture instead of the refusal.
    #[test]
    fn nested_cgroup_capture_with_all_members_proven_proceeds_empty() {
        let dir = tempfile::tempdir().expect("a scope directory");
        let a = CgroupProofChild(
            std::process::Command::new("sleep")
                .arg("120")
                .die_with_parent()
                .spawn()
                .expect("sleep a"),
        );
        let b = CgroupProofChild(
            std::process::Command::new("sleep")
                .arg("120")
                .die_with_parent()
                .spawn()
                .expect("sleep b"),
        );
        std::fs::write(
            dir.path().join("cgroup.procs"),
            format!("{}\n{}\n", a.0.id(), b.0.id()),
        )
        .expect("a cgroup.procs");
        let scope = crate::scope::cgroup(dir.path()).expect("open scope directory");
        let engine = Engine::discover(
            &capture_args(ScopeArg::Cgroup(dir.path().to_path_buf())),
            &scope,
            None,
        )
        .expect("discovery over two sleeps captures");
        assert!(engine.plan().modules.is_empty(), "sleeps map no provider");
        assert_eq!(
            engine.scanned_view_count(),
            2,
            "both members scanned into views"
        );
        assert!(
            engine.discovery().scan_unavailable.is_none(),
            "the scan ran"
        );
        assert!(
            empty_plan_is_clean(engine.plan()),
            "no loss may hide behind the fixture: {:?} {:?}",
            engine.plan().skipped,
            engine.plan().modules_skipped
        );
        refuse_nested_empty_capture_for_scope(
            &nested_own_numbering_for_test(),
            &ScopeArg::Cgroup(dir.path().to_path_buf()),
            "a --cgroup capture",
            &engine,
        )
        .expect("proven cgroup emptiness proceeds");
    }

    /// Twin: one cgroup member unreadable (its `cgroup.procs` denied)
    /// keeps the refusal — the observer cannot tell "nothing there"
    /// from "can't see". The denial probe mirrors the `scope_pids`
    /// walk test: under a privilege that reads through mode 000 the
    /// member is genuinely proven, so the capture genuinely proceeds.
    #[test]
    fn nested_cgroup_capture_with_an_unreadable_member_is_still_refused() {
        let dir = tempfile::tempdir().expect("a scope directory");
        let leaf = dir.path().join("leaf.scope");
        std::fs::create_dir(&leaf).expect("a leaf cgroup");
        std::fs::write(leaf.join("cgroup.procs"), "99999999\n").expect("a cgroup.procs");
        let mut permissions = std::fs::metadata(&leaf).unwrap().permissions();
        permissions.set_mode(0o000);
        std::fs::set_permissions(&leaf, permissions).unwrap();
        let denied = std::fs::read_dir(&leaf).is_err();
        let scope = crate::scope::cgroup(dir.path()).expect("open scope directory");
        let engine = Engine::discover(
            &capture_args(ScopeArg::Cgroup(dir.path().to_path_buf())),
            &scope,
            None,
        )
        .expect("discovery over a denied leaf captures");
        std::fs::set_permissions(&leaf, std::fs::Permissions::from_mode(0o755)).unwrap();
        assert!(
            engine.plan().modules.is_empty(),
            "nothing mapped means no modules either way"
        );
        let verdict = refuse_nested_empty_capture_for_scope(
            &nested_own_numbering_for_test(),
            &ScopeArg::Cgroup(dir.path().to_path_buf()),
            "a --cgroup capture",
            &engine,
        );
        if !denied {
            verdict.expect("nothing was denied, so the empty cgroup proceeds");
            return;
        }
        let error = verdict.expect_err("a denied member keeps the refusal");
        let text = format!("{error:#}");
        assert!(
            text.starts_with("pid-namespace-mismatch: refusing a --cgroup capture:"),
            "{text}"
        );
    }

    /// Twin: a member listed as `0` (outside this PID namespace) is
    /// not proven visible, so the refusal stays even when every other
    /// member scanned cleanly.
    #[test]
    fn nested_cgroup_capture_with_an_invisible_member_is_still_refused() {
        let dir = tempfile::tempdir().expect("a scope directory");
        let a = CgroupProofChild(
            std::process::Command::new("sleep")
                .arg("120")
                .die_with_parent()
                .spawn()
                .expect("sleep a"),
        );
        std::fs::write(
            dir.path().join("cgroup.procs"),
            format!("0\n{}\n", a.0.id()),
        )
        .expect("a cgroup.procs");
        let scope = crate::scope::cgroup(dir.path()).expect("open scope directory");
        let engine = Engine::discover(
            &capture_args(ScopeArg::Cgroup(dir.path().to_path_buf())),
            &scope,
            None,
        )
        .expect("discovery over one sleep captures");
        assert!(
            engine.plan().modules.is_empty(),
            "one sleep maps no provider"
        );
        let error = refuse_nested_empty_capture_for_scope(
            &nested_own_numbering_for_test(),
            &ScopeArg::Cgroup(dir.path().to_path_buf()),
            "a --cgroup capture",
            &engine,
        )
        .expect_err("an invisible member keeps the refusal");
        let text = format!("{error:#}");
        assert!(
            text.starts_with("pid-namespace-mismatch: refusing a --cgroup capture:"),
            "{text}"
        );
    }

    /// A `--pid` scope keeps the refusal even over a proven-clean
    /// engine: its kernel filter can never match outside the initial
    /// namespace. (`--system` proceeds instead; see
    /// `nested_system_capture_with_zero_modules_proceeds_empty`.)
    #[test]
    fn nested_pid_capture_keeps_the_refusal() {
        let dir = tempfile::tempdir().expect("a scope directory");
        std::fs::write(dir.path().join("cgroup.procs"), "").expect("an empty cgroup.procs");
        let scope = crate::scope::cgroup(dir.path()).expect("open scope directory");
        let engine = Engine::discover(
            &capture_args(ScopeArg::Cgroup(dir.path().to_path_buf())),
            &scope,
            None,
        )
        .expect("discovery over an empty cgroup captures");
        assert!(engine.plan().modules.is_empty());
        assert!(empty_plan_is_clean(engine.plan()));
        let error = refuse_nested_empty_capture_for_scope(
            &nested_own_numbering_for_test(),
            &ScopeArg::Pid(42),
            "--pid 42",
            &engine,
        )
        .expect_err("a pid scope keeps the refusal");
        let text = format!("{error:#}");
        assert!(
            text.starts_with("pid-namespace-mismatch: refusing --pid 42:"),
            "{text}"
        );
    }

    /// An idle node at capture start is normal (pods arrive later):
