    /// No sleeps while backlog exists; the pause slice still wins; an
    /// idle tick re-polls for readiness instead of idling out the frame.
    #[test]
    fn ready_sleep_skips_only_on_backlog() {
        let frame_due_in = Duration::from_secs(1);
        assert_eq!(
            ready_sleep_duration(true, true, frame_due_in),
            Duration::from_millis(1)
        );
        assert_eq!(
            ready_sleep_duration(false, true, frame_due_in),
            Duration::ZERO
        );
        assert_eq!(
            ready_sleep_duration(false, false, frame_due_in),
            READY_IDLE_POLL
        );
        assert_eq!(
            ready_sleep_duration(false, false, Duration::from_millis(1)),
            Duration::from_millis(1)
        );
        assert_eq!(
            ready_sleep_duration(true, false, frame_due_in),
            Duration::from_millis(1)
        );
    }

    /// F-T4-2, the gate alone on scripted times. A frame ran at 0. The pause
    /// helper's hook fires 1 ms later and its stop stays pending from then on.
    /// The loop ticks every `READY_IDLE_POLL`, as an idle capture does. At
    /// every drain interval (trace's 200 ms, profile's 1 s, the 60 s maximum),
    /// the first tick after the hook must admit the pause service, well inside
    /// the stop's 500 ms causal budget. The frame-only gate waited for the
    /// next frame instead: 999 ms after the hook at the profile default. With
    /// no stop pending the gate still admits frames only, once per drain
    /// interval, and never asks the pause on a frame tick.
    #[test]
    fn a_pending_pause_stop_is_due_on_the_next_tick_at_any_drain_interval() {
        let budget = Duration::from_nanos(crate::discovery::pause::CYCLE_NS);
        let hook = Duration::from_millis(1);
        let drains = [TRACE_CADENCE, PROFILE_CADENCE, Duration::from_secs(60)];
        // The first tick the gate admits, its pass, and whether it asked for
        // the pause state although it was a frame tick.
        let first_due = |drain: Duration, hook: Option<Duration>| {
            let mut since_frame = Duration::ZERO;
            loop {
                since_frame += READY_IDLE_POLL;
                let mut asked = false;
                let pass = discovery_due(
                    since_frame,
                    drain,
                    || {
                        asked = true;
                        hook.is_some_and(|hook| since_frame >= hook)
                    },
                    || false,
                );
                if let Some(pass) = pass {
                    return (since_frame, pass, asked && pass == DiscoveryPass::Frame);
                }
            }
        };

        let pending: Vec<_> = drains
            .iter()
            .map(|&drain| (drain, first_due(drain, Some(hook))))
            .collect();
        for (drain, (due, _, _)) in &pending {
            let waited = *due - hook;
            assert!(
                waited <= budget,
                "drain {drain:?}: the first due tick came {waited:?} after the hook, \
                 past the {budget:?} causal budget"
            );
        }
        for (drain, (due, pass, _)) in &pending {
            assert_eq!(
                *pass,
                DiscoveryPass::PendingStop,
                "drain {drain:?}: a pending stop between frames must admit the pause \
                 service alone, not a frame"
            );
            assert!(
                *due - hook <= READY_IDLE_POLL,
                "drain {drain:?}: the stop waited {:?}, more than one idle tick",
                *due - hook
            );
        }

        for drain in drains {
            let (due, pass, asked_on_frame) = first_due(drain, None);
            assert_eq!(
                (due, pass),
                (drain, DiscoveryPass::Frame),
                "drain {drain:?}: without a pending stop only the frame is due"
            );
            assert!(
                !asked_on_frame,
                "drain {drain:?}: a frame tick must not pay for the pause check"
            );
        }
    }

    /// Both capture loops idle on ring readiness, not on a fixed sleep: a
    /// revert of either loop body to `thread::sleep` keeps every
    /// behavioral unit test green (the loops only run live), so pin the
    /// call sites statically, sliced like
    /// `terminal_capture_modes_wire_shared_finish_and_drain_helpers`.
    #[test]
    fn capture_loops_idle_on_readiness() {
        let source = include_str!("run.rs");
        let profile = source
            .split_once("fn capture_profile(")
            .unwrap()
            .1
            .split_once("fn write_json_report")
            .unwrap()
            .0;
        let trace = source
            .split_once("fn capture_trace(")
            .unwrap()
            .1
            .split_once("fn terminal_trace_count_line")
            .unwrap()
            .0;
        for (function, body) in [("capture_profile", profile), ("capture_trace", trace)] {
            assert_eq!(
                body.matches("wait_until_ready(").count(),
                1,
                "{function} must idle on exactly one ring-readiness wait"
            );
            assert!(
                !body.contains("thread::sleep"),
                "{function} idles on a fixed sleep instead of ring readiness"
            );
        }
    }

    /// F-T4-2's loop wiring, which the BPF-free tick tests cannot reach. Both
    /// capture loops ask the one gate with the owned pending-stop check,
    /// count the gated pass through the shared cadence step, and send a
    /// pending stop to the between-frames service. The count lives in the
    /// shared step — the per-iteration body (the preamble plus the tick
    /// closure, sliced from the capture loop) names the counter alias
    /// exactly twice (the borrow plus the shared-step call), so no direct
    /// `*frame_tick` mutation outside the step can shift the cadence — and
    /// the backing counter exactly once (the borrow), so no `frames`
    /// mutation anywhere before the borrow, preamble included, can shift
    /// it either — and trace's frame clock advances through its own
    /// shared step, never directly, so a pending-stop pass leaves the
    /// frame and discovery cadence unchanged. Sliced like
    /// `capture_loops_idle_on_readiness`.
    #[test]
    fn capture_loops_service_a_pending_stop_between_frames() {
        let source = include_str!("run.rs");
        let tick_of = |start: &str, end: &str| {
            source
                .split_once(start)
                .unwrap()
                .1
                .split_once(end)
                .unwrap()
                .0
                .split_once("    loop {")
                .unwrap()
                .1
                .split_once("let mut finish_context =")
                .unwrap()
                .0
        };
        let profile = tick_of("fn capture_profile(", "fn write_json_report");
        let trace = tick_of("fn capture_trace(", "fn terminal_trace_count_line");
        for (function, tick) in [("capture_profile", profile), ("capture_trace", trace)] {
            assert_eq!(
                tick.matches("discovery_due(").count(),
                1,
                "{function} must gate discovery once per tick"
            );
            let pending_stop_check = if function == "capture_trace" {
                "owned_stop_pending(engine, session, owned.as_deref(), interrupted)"
            } else {
                "owned_stop_pending(context.0, context.1, context.2.as_deref(), interrupted)"
            };
            assert!(
                tick.contains(pending_stop_check),
                "{function} must ask the gate for a pending pause stop"
            );
            if function == "capture_trace" {
                assert!(
                    tick.find(pending_stop_check).unwrap()
                        < tick.find("with_trace_identity_frame(").unwrap(),
                    "trace must decide the pending-stop pass before granting frame proof work"
                );
            }
            assert_eq!(
                tick.matches("count_discovery_pass(frame_tick, pass)")
                    .count(),
                1,
                "{function} must count the gated pass through the shared cadence step"
            );
            assert_eq!(
                tick.matches("frame_tick").count(),
                2,
                "{function} must touch the frame counter only through the shared step: \
                 the borrow plus the shared-step call, no direct mutation"
            );
            assert_eq!(
                tick.matches("frames").count(),
                1,
                "{function} must name the backing counter only for the borrow: \
                 no direct mutation before it"
            );
            assert!(
                tick.contains("match counted.pass {"),
                "{function} must dispatch on the counted pass"
            );
            assert!(
                tick.contains("DiscoveryPass::PendingStop => service_pending_stop("),
                "{function} must service a pending stop between frames"
            );
            let frame = tick
                .split_once("DiscoveryPass::Frame => ")
                .and_then(|(_, rest)| rest.split_once("DiscoveryPass::PendingStop =>"))
                .unwrap_or_else(|| panic!("{function} must match the frame pass first"))
                .0;
            assert!(
                frame.contains("drain_discovery_tick(") && frame.contains("counted.force_full"),
                "{function}: only a frame pass runs the full pass, with its counted sweep verdict"
            );
            assert_eq!(
                tick.matches("drain_discovery_tick(").count(),
                1,
                "{function} must run the full pass from exactly one arm"
            );
        }
        assert_eq!(
            trace
                .matches("advance_trace_frame_clock(frame_clock, pass, Instant::now())")
                .count(),
            1,
            "trace must advance its frame clock through the shared step once per tick"
        );
        assert!(
            !trace.contains("*frame_clock ="),
            "trace must not advance its frame clock outside the shared step"
        );
    }

    /// F-T8-1, one tick on scripted clock reads. The gate reads the frame clock
    /// at drain − 1 ms, and the tick's work (a 30 ms event drain) then crosses
    /// the frame boundary, so any later read sees drain + 29 ms. With separate
    /// reads the snapshot and render decisions came from those later reads.
    /// The frame rendered and reset the clock with no discovery pass:
    /// `(false, true, true)`. With one read per tick, this tick skips the whole
    /// frame and the next tick does all of it.
    #[test]
    fn a_profile_tick_does_the_whole_frame_or_none_of_it() {
        let drain = PROFILE_CADENCE;
        let decide = |reads: [Duration; 3]| {
            let mut reads = reads.into_iter();
            let frame =
                profile_frame_decisions(|| reads.next().expect("at most three reads"), drain);
            let discovery = discovery_due(frame.since_frame, drain, || false, || false)
                == Some(DiscoveryPass::Frame);
            (discovery, frame.fresh_snapshot, frame.render)
        };
        let crossing = drain + Duration::from_millis(29);
        assert_eq!(
            decide([drain - Duration::from_millis(1), crossing, crossing]),
            (false, false, false),
            "a tick that starts before the frame boundary does none of the frame"
        );
        let next = drain + Duration::from_millis(30);
        assert_eq!(
            decide([next, next, next]),
            (true, true, true),
            "the next tick does all of it"
        );
    }

    #[test]
    fn immediate_exec_recovery_request_schedules_a_whole_profile_frame_once() {
        let drain = PROFILE_CADENCE;
        let rendered = Instant::now();
        let mut last_frame = rendered;
        let after_long_tick = rendered + Duration::from_millis(500);
        request_profile_recovery_frame(&mut last_frame, drain, true, || after_long_tick);
        let mut reads = 0;
        let frame = profile_frame_decisions(
            || {
                reads += 1;
                after_long_tick.duration_since(last_frame)
            },
            drain,
        );
        assert_eq!(reads, 1);
        assert_eq!(
            discovery_due(frame.since_frame, drain, || false, || false),
            Some(DiscoveryPass::Frame)
        );
        assert!(frame.fresh_snapshot && frame.render);
        let mut cache = Some(7);
        assert_eq!(
            profile_tick_snapshot(frame, &mut cache, || Ok(11)).unwrap(),
            11
        );

        // The next completed render takes over the ordinary cadence. A
        // consumed signal cannot keep requesting frames or read another clock.
        last_frame = after_long_tick;
        request_profile_recovery_frame(&mut last_frame, drain, false, || {
            panic!("ordinary cadence needs no recovery clock read")
        });
        let next = profile_frame_decisions(
            || (after_long_tick + Duration::from_millis(1)).duration_since(last_frame),
            drain,
        );
        assert_eq!(
            discovery_due(next.since_frame, drain, || false, || false),
            None
        );
        assert!(!next.fresh_snapshot && !next.render);
    }

    #[test]
    fn no_exec_recovery_request_preserves_profile_cadence_and_pending_stop() {
        let drain = PROFILE_CADENCE;
        let rendered = Instant::now();
        let mut last_frame = rendered;
        request_profile_recovery_frame(&mut last_frame, drain, false, || {
            panic!("ordinary cadence reads no recovery clock")
        });
        assert_eq!(last_frame, rendered);
        let frame = profile_frame_decisions(|| Duration::from_millis(1), drain);
        assert_eq!(
            discovery_due(frame.since_frame, drain, || true, || false),
            Some(DiscoveryPass::PendingStop)
        );
        assert!(!frame.fresh_snapshot && !frame.render);
    }

    /// One scripted profile tick, offset from the loop's first tick.
    #[derive(Clone, Copy)]
    struct ScriptedTick {
        start: Duration,
        /// Its passes and its event drain. The gate reads the frame clock
        /// before this work; any later frame decision reads after it.
        work: Duration,
        stop_pending: bool,
    }

    /// What one scripted tick decided: its discovery pass, whether it read the
    /// maps fresh, and whether it rendered.
    type TickFrame = (Option<DiscoveryPass>, bool, bool);

    /// Drives scripted ticks through the production frame decisions, as
    /// `capture_profile` does. Each tick gets `profile_frame_decisions` for its
    /// frame, then `discovery_due` on its read for the pass. A render resets the
    /// frame clock at the tick's end, where the render block runs. The clock
    /// starts a full interval before the first tick, as `capture_profile` sets
    /// it.
    fn run_profile_ticks(drain: Duration, ticks: &[ScriptedTick]) -> Vec<TickFrame> {
        // Absolute times are shifted by one interval, so the clock starts at 0.
        let mut last_frame = Duration::ZERO;
        ticks
            .iter()
            .map(|tick| {
                let start = drain + tick.start;
                let mut reads = 0;
                let frame = profile_frame_decisions(
                    || {
                        reads += 1;
                        let at = if reads == 1 { start } else { start + tick.work };
                        at.saturating_sub(last_frame)
                    },
                    drain,
                );
                let pass = discovery_due(frame.since_frame, drain, || tick.stop_pending, || false);
                if frame.render {
                    last_frame = start + tick.work;
                }
                (pass, frame.fresh_snapshot, frame.render)
            })
            .collect()
    }

    fn frame_passes(decided: &[TickFrame]) -> usize {
        decided
            .iter()
            .filter(|(pass, _, _)| *pass == Some(DiscoveryPass::Frame))
            .count()
    }

    fn assert_whole_profile_frames(decided: &[TickFrame]) {
        for (index, &(pass, fresh_snapshot, render)) in decided.iter().enumerate() {
            let frame = pass == Some(DiscoveryPass::Frame);
            assert!(
                frame == fresh_snapshot && frame == render,
                "tick {index}: pass {pass:?}, fresh snapshot {fresh_snapshot}, render {render}"
            );
        }
    }

    /// F-T8-1: busy 30 ms ticks back to back for 20 s at the 1 s profile
    /// default. Every frame must keep its discovery pass, at least 19. The
    /// separate reads gave one, the very first. Each later tick that crossed
    /// a boundary rendered and reset the clock without a pass, so the next
    /// rendering tick's gate always fell 10 ms short.
    #[test]
    fn busy_profile_ticks_keep_one_discovery_pass_per_frame() {
        let drain = PROFILE_CADENCE;
        let ms = Duration::from_millis;
        let busy: Vec<_> = (0u32..)
            .map(|k| ScriptedTick {
                start: ms(30) * k,
                work: ms(30),
                stop_pending: false,
            })
            .take_while(|tick| tick.start < Duration::from_secs(20))
            .collect();
        let decided = run_profile_ticks(drain, &busy);
        assert!(
            frame_passes(&decided) >= 19,
            "20 s of busy 30 ms ticks gave {} discovery passes",
            frame_passes(&decided)
        );
        assert_whole_profile_frames(&decided);
    }

    /// F-T8-1: a 200 ms pending-stop service straddles the frame boundary
    /// between idle 2 ms ticks. It must not cost the next tick its frame pass.
    #[test]
    fn a_profile_pending_stop_cannot_skip_the_next_frames_discovery() {
        let drain = PROFILE_CADENCE;
        let ms = Duration::from_millis;
        let idle = |start| ScriptedTick {
            start,
            work: Duration::ZERO,
            stop_pending: false,
        };
        let mut straddle: Vec<_> = (0u32..500).map(|k| idle(ms(2) * k)).collect();
        let service = straddle.len();
        straddle.push(ScriptedTick {
            start: ms(999),
            work: ms(200),
            stop_pending: true,
        });
        // The 1 ms pause slice follows the service, then 2 ms idle polls.
        straddle.extend((0u32..900).map(|k| idle(ms(1200) + ms(2) * k)));
        let decided = run_profile_ticks(drain, &straddle);
        assert_eq!(
            decided[service],
            (Some(DiscoveryPass::PendingStop), false, false),
            "the straddling service does none of the frame"
        );
        assert_eq!(
            decided[service + 1],
            (Some(DiscoveryPass::Frame), true, true),
            "the tick after the service runs the frame's discovery pass"
        );
        assert_whole_profile_frames(&decided);
        assert_eq!(frame_passes(&decided), 3, "frames at 0, 1.2 s and 2.2 s");
    }

    /// What one scripted tick did through the shared tick path: its
    /// discovery pass, its snapshot/render decisions, and the counted frame
    /// state after it.
    struct TickEffect {
        pass: Option<DiscoveryPass>,
        fresh_snapshot: bool,
        render: bool,
        /// Cumulative frame count after this tick (shared counter).
        frames: u64,
        /// This tick's discovery forced a full sweep (shared cadence).
        force_full: bool,
    }

    /// Cumulative effect counters over scripted ticks.
    #[derive(Default)]
    struct TickEffectTotals {
        forced_sweeps: usize,
        fresh_snapshots: usize,
        cached_snapshots: usize,
        renders: usize,
        pending_stops: usize,
    }

    /// Drives scripted ticks through the production tick path, as
    /// `capture_profile` does: `profile_frame_decisions` for the frame, the
    /// gate for the pass, the shared counted pass for discovery, the shared
    /// snapshot step for the maps, and the frame's render verdict. Discovery,
    /// snapshot and render effects are recorded fakes; the decisions, the
    /// frame counting and the forced-sweep cadence are production code. The
    /// clock starts a full interval before the first tick and a render resets
    /// it at the tick's end, as `capture_profile` sets them.
    fn run_profile_ticks_with_effects(
        drain: Duration,
        ticks: &[ScriptedTick],
    ) -> (Vec<TickEffect>, TickEffectTotals) {
        // Absolute times are shifted by one interval, so the clock starts at 0.
        let mut last_frame = Duration::ZERO;
        let mut frames = 0u64;
        let mut cache: Option<u64> = None;
        let mut snapshot_seq = 0u64;
        let mut totals = TickEffectTotals::default();
        let mut effects = Vec::new();
        for tick in ticks {
            let start = drain + tick.start;
            let mut reads = 0;
            let frame = profile_frame_decisions(
                || {
                    reads += 1;
                    let at = if reads == 1 { start } else { start + tick.work };
                    at.saturating_sub(last_frame)
                },
                drain,
            );
            let pass = discovery_due(frame.since_frame, drain, || tick.stop_pending, || false);
            let mut force_full = false;
            if let Some(pass) = pass {
                let counted = count_discovery_pass(&mut frames, pass);
                force_full = counted.force_full;
                match counted.pass {
                    DiscoveryPass::Frame => {
                        if force_full {
                            totals.forced_sweeps += 1;
                        }
                    }
                    DiscoveryPass::PendingStop => {
                        totals.pending_stops += 1;
                    }
                    // This harness gates with no backlog, so no pass here.
                    DiscoveryPass::Backlog => {
                        unreachable!("profile cadence harness admits no backlog pass")
                    }
                }
            }
            let mut read_fresh = false;
            profile_tick_snapshot(frame, &mut cache, || {
                read_fresh = true;
                snapshot_seq += 1;
                Ok(snapshot_seq)
            })
            .unwrap();
            if read_fresh {
                totals.fresh_snapshots += 1;
            } else {
                totals.cached_snapshots += 1;
            }
            if frame.render {
                totals.renders += 1;
                last_frame = start + tick.work;
            }
            effects.push(TickEffect {
                pass,
                fresh_snapshot: frame.fresh_snapshot,
                render: frame.render,
                frames,
                force_full,
            });
        }
        (effects, totals)
    }

    /// What one scripted trace tick did through the shared tick path: its
    /// discovery pass, the frame-clock stamp after it, and the counted
    /// frame state after it.
    struct TraceTickEffect {
        pass: Option<DiscoveryPass>,
        /// Frame-clock stamp after this tick, as an offset from the
        /// driver's clock start (production stamps `Instant::now()` on a
        /// frame pass).
        frame_stamp: Duration,
        /// Cumulative frame count after this tick (shared counter).
        frames: u64,
        /// This tick's discovery forced a full sweep (shared cadence).
        force_full: bool,
    }

    /// Cumulative effect counters over scripted trace ticks.
    #[derive(Default)]
    struct TraceTickEffectTotals {
        forced_sweeps: usize,
        pending_stops: usize,
    }

    /// Drives scripted ticks through the production trace tick path, as
    /// `capture_trace` does: `discovery_due` on the frame-clock elapsed,
    /// the shared clock-advance step, and the shared counted pass for
    /// discovery. Discovery effects are recorded fakes; the gate, the
    /// clock advance, the frame counting and the forced-sweep cadence are
    /// production code. The clock starts a full interval before the first
    /// tick, as `capture_trace` sets it. The gate and the advance share
    /// one scripted read per tick: production stamps a fresh `now` right
    /// after the gate, before the discovery drain, so the tick's work
    /// never shifts the stamp and `work` stays unused here.
    fn run_trace_ticks_with_effects(
        drain: Duration,
        ticks: &[ScriptedTick],
    ) -> (Vec<TraceTickEffect>, TraceTickEffectTotals) {
        let start = Instant::now();
        let mut last_frame = start;
        let mut frames = 0u64;
        let mut totals = TraceTickEffectTotals::default();
        let mut effects = Vec::new();
        for tick in ticks {
            let now = start + drain + tick.start;
            let pass = discovery_due(
                now.duration_since(last_frame),
                drain,
                || tick.stop_pending,
                || false,
            );
            let mut force_full = false;
            if let Some(pass) = pass {
                advance_trace_frame_clock(&mut last_frame, pass, now);
                let counted = count_discovery_pass(&mut frames, pass);
                force_full = counted.force_full;
                match counted.pass {
                    DiscoveryPass::Frame => {
                        if force_full {
                            totals.forced_sweeps += 1;
                        }
                    }
                    DiscoveryPass::PendingStop => {
                        totals.pending_stops += 1;
                    }
                    // This harness gates with no backlog, so no pass here.
                    DiscoveryPass::Backlog => {
                        unreachable!("trace cadence harness admits no backlog pass")
                    }
                }
            }
            effects.push(TraceTickEffect {
                pass,
                frame_stamp: last_frame.duration_since(start),
                frames,
                force_full,
            });
        }
        (effects, totals)
    }

    /// G6: pending-stop passes must not shift the forced-sweep cadence.
    /// Idle 2 ms ticks with stop-pending ticks scattered between frames and
    /// one 200 ms service straddling the frame-5 boundary: the next frame
    /// after the cluster performs exactly one forced sweep plus a fresh
    /// snapshot and a render, the frame count advances by exactly one per
    /// frame pass, and every pending stop leaves the count, the snapshot
    /// and the render untouched. The counting, cadence and snapshot steps
    /// are the shared production path, not a test mirror.
    #[test]
    fn pending_stop_passes_do_not_shift_the_forced_sweep_cadence() {
        let drain = PROFILE_CADENCE;
        let ms = Duration::from_millis;
        let idle = |start| ScriptedTick {
            start,
            work: Duration::ZERO,
            stop_pending: false,
        };
        // Idle 2 ms ticks from 0 to just under 5 s: frames land every
        // drain from the first tick — at 0, 1, 2, 3 s and the forced 5th
        // right after the cluster past 4 s — with no 6th frame in range.
        let mut ticks: Vec<_> = (0u32..2500).map(|k| idle(ms(2) * k)).collect();
        // Scattered pending stops between the early frames.
        for tick in [50, 150, 250, 350, 450] {
            ticks[tick].stop_pending = true;
        }
        // A cluster of pending stops ahead of the forced frame, including
        // one 200 ms service straddling the frame-5 boundary at 4 s.
        for tick in [2050, 2150, 2250, 2350, 2450] {
            ticks[tick].stop_pending = true;
        }
        ticks[1999] = ScriptedTick {
            start: ms(3998),
            work: ms(200),
            stop_pending: true,
        };
        let (effects, totals) = run_profile_ticks_with_effects(drain, &ticks);

        // Every frame pass counts exactly one frame; nothing else counts.
        for (index, effect) in effects.iter().enumerate() {
            let before = if index == 0 {
                0
            } else {
                effects[index - 1].frames
            };
            if effect.pass == Some(DiscoveryPass::Frame) {
                assert_eq!(
                    effect.frames,
                    before + 1,
                    "tick {index}: a frame pass counts exactly one frame"
                );
            } else {
                assert_eq!(
                    effect.frames,
                    before,
                    "tick {index}: a {pass:?} pass must not count a frame",
                    pass = effect.pass
                );
            }
        }
        // Pending stops change nothing: no count, no forced sweep, no fresh
        // snapshot, no render.
        for (index, effect) in effects.iter().enumerate() {
            if effect.pass == Some(DiscoveryPass::PendingStop) {
                assert!(
                    !effect.force_full && !effect.fresh_snapshot && !effect.render,
                    "tick {index}: a pending stop forces nothing and renders nothing"
                );
            }
        }
        assert_eq!(totals.pending_stops, 11, "the scripted pending stops");
        // The straddling service does none of the frame; the next frame
        // after the cluster is the forced 5th: exactly one forced sweep
        // plus a fresh snapshot and a render, frames 4 to 5.
        assert_eq!(
            (
                effects[1999].pass,
                effects[1999].fresh_snapshot,
                effects[1999].render
            ),
            (Some(DiscoveryPass::PendingStop), false, false),
            "the straddling service does none of the frame"
        );
        assert_eq!(
            (
                effects[2000].pass,
                effects[2000].fresh_snapshot,
                effects[2000].render
            ),
            (Some(DiscoveryPass::Frame), true, true),
            "the tick after the service runs the frame"
        );
        assert_eq!(effects[2000].frames, 5, "that frame is the 5th");
        assert!(
            effects[2000].force_full,
            "the 5th frame forces the full sweep"
        );
        assert_eq!(effects[1999].frames, 4, "no count across the service");
        assert_eq!(totals.forced_sweeps, 1, "exactly one forced sweep");
        assert_eq!(effects.last().unwrap().frames, 5, "no extra frame counts");
        assert_eq!(totals.fresh_snapshots, 5, "one fresh snapshot per frame");
        assert_eq!(totals.renders, 5, "one render per frame");
        assert_eq!(
            totals.cached_snapshots,
            ticks.len() - 5,
            "every other tick reuses the cached snapshot"
        );
        let decided: Vec<TickFrame> = effects
            .iter()
            .map(|effect| (effect.pass, effect.fresh_snapshot, effect.render))
            .collect();
        assert_whole_profile_frames(&decided);
    }

    /// C5: the shared trace clock step advances the frame clock on a frame
    /// pass and leaves it alone on any other pass.
    #[test]
    fn trace_frame_clock_advances_only_on_a_frame_pass() {
        let start = Instant::now();
        let mut clock = start;
        let later = start + Duration::from_millis(200);
        advance_trace_frame_clock(&mut clock, DiscoveryPass::PendingStop, later);
        assert_eq!(
            clock, start,
            "a pending-stop pass leaves the frame clock alone"
        );
        advance_trace_frame_clock(&mut clock, DiscoveryPass::Frame, later);
        assert_eq!(clock, later, "a frame pass stamps the frame clock");
    }

    /// C5 (G6 mirror for trace): pending-stop passes must not shift the
    /// forced-sweep cadence or the frame clock. Idle 50 ms ticks over the
    /// 200 ms drain with stop-pending ticks scattered between frames, a
    /// cluster ahead of the forced frame, and a stop pending on a
    /// frame-due tick itself (the frame wins): every frame pass counts
    /// exactly one frame and stamps the clock at its gate time, every
    /// pending stop leaves the count, the stamp and the sweep verdict
    /// untouched, and the 5th frame forces the one full sweep. The gate,
    /// the clock advance, the counting and the cadence are the shared
    /// production path, not a test mirror.
    #[test]
    fn trace_pending_stop_passes_shift_neither_the_clock_nor_the_cadence() {
        let drain = TRACE_CADENCE;
        let ms = Duration::from_millis;
        let idle = |start| ScriptedTick {
            start,
            work: Duration::ZERO,
            stop_pending: false,
        };
        // Idle 50 ms ticks from 0 to 950 ms: frames land every drain from
        // the first tick — at 0, 200, 400, 600 and the forced 800 ms —
        // with no 6th frame in range.
        let mut ticks: Vec<_> = (0u32..20).map(|k| idle(ms(50) * k)).collect();
        // Scattered pending stops between the early frames.
        for tick in [1, 5, 9, 13] {
            ticks[tick].stop_pending = true;
        }
        // A cluster of pending stops ahead of the forced frame.
        for tick in [14, 15] {
            ticks[tick].stop_pending = true;
        }
        // A stop pending on the forced frame's own tick: the gate runs
        // the frame, not the stop.
        ticks[16].stop_pending = true;
        let (effects, totals) = run_trace_ticks_with_effects(drain, &ticks);

        // Every frame pass counts exactly one frame and stamps the clock
        // at its gate time; nothing else counts or stamps.
        for (index, effect) in effects.iter().enumerate() {
            let (before, stamp_before) = if index == 0 {
                (0, Duration::ZERO)
            } else {
                (effects[index - 1].frames, effects[index - 1].frame_stamp)
            };
            if effect.pass == Some(DiscoveryPass::Frame) {
                assert_eq!(
                    effect.frames,
                    before + 1,
                    "tick {index}: a frame pass counts exactly one frame"
                );
                assert_eq!(
                    effect.frame_stamp,
                    drain + ticks[index].start,
                    "tick {index}: a frame pass stamps the clock at its gate time"
                );
            } else {
                assert_eq!(
                    effect.frames,
                    before,
                    "tick {index}: a {pass:?} pass must not count a frame",
                    pass = effect.pass
                );
                assert_eq!(
                    effect.frame_stamp,
                    stamp_before,
                    "tick {index}: a {pass:?} pass must not move the frame clock",
                    pass = effect.pass
                );
            }
        }
        // Pending stops change nothing: no count, no stamp, no sweep.
        for (index, effect) in effects.iter().enumerate() {
            if effect.pass == Some(DiscoveryPass::PendingStop) {
                assert!(
                    !effect.force_full,
                    "tick {index}: a pending stop forces no sweep"
                );
            }
        }
        assert_eq!(totals.pending_stops, 6, "the scripted pending stops");
        // The frame wins its own tick: the stop pending there runs as the
        // forced 5th frame.
        assert_eq!(
            effects[16].pass,
            Some(DiscoveryPass::Frame),
            "the gate runs the frame when both are due"
        );
        assert_eq!(effects[16].frames, 5, "that frame is the 5th");
        assert!(
            effects[16].force_full,
            "the 5th frame forces the full sweep"
        );
        assert_eq!(effects[15].frames, 4, "no count across the cluster");
        assert_eq!(
            effects[15].frame_stamp, effects[12].frame_stamp,
            "no clock shift across the cluster"
        );
        assert_eq!(totals.forced_sweeps, 1, "exactly one forced sweep");
        assert_eq!(effects.last().unwrap().frames, 5, "no extra frame counts");
        assert_eq!(
            effects
                .iter()
                .filter(|effect| effect.pass == Some(DiscoveryPass::Frame))
                .map(|effect| effect.frame_stamp)
                .collect::<Vec<_>>(),
            [200, 400, 600, 800, 1000].map(ms),
            "frames stamp exactly one drain apart"
        );
    }

    /// F-T8-1's loop wiring, which the scripted frame tests cannot reach. The
    /// profile loop reads its frame clock once per tick, through
    /// `profile_frame_decisions`, and its gate, snapshot and render all follow
    /// that one read — the snapshot through the shared snapshot step. Its
    /// only other read sizes the idle wait. Sliced like
    /// `capture_loops_idle_on_readiness`.
    #[test]
    fn the_profile_loop_decides_each_frame_from_one_clock_read() {
        let source = include_str!("run.rs");
        let profile = source
            .split_once("fn capture_profile(")
            .unwrap()
            .1
            .split_once("fn write_json_report")
            .unwrap()
            .0;
        for (marker, decision) in [
            (
                "let tick_frame = profile_frame_decisions(|| last_frame.elapsed(), drain);",
                "the tick's one frame-clock read",
            ),
            (
                "discovery_due(tick_frame.since_frame, drain,",
                "the gate on that read",
            ),
            (
                "profile_tick_snapshot(tick_frame, snapshot_cache,",
                "the snapshot on that read, through the shared step",
            ),
            (
                "if tick_frame.render {",
                "the render and reset on that read",
            ),
            (
                "drain.saturating_sub(last_frame.elapsed())",
                "the idle wait",
            ),
        ] {
            assert_eq!(
                profile.matches(marker).count(),
                1,
                "capture_profile: {decision}"
            );
        }
        let snapshot_step = source
            .split_once("fn profile_tick_snapshot")
            .unwrap()
            .1
            .split_once("\n}\n")
            .unwrap()
            .0;
        assert_eq!(
            snapshot_step
                .matches("if !tick_frame.fresh_snapshot {")
                .count(),
            1,
            "the shared snapshot step gates the fresh read on the frame verdict"
        );
        assert_eq!(
            profile.matches("last_frame.elapsed()").count(),
            2,
            "capture_profile reads its frame clock only for the tick's frame and the idle wait"
        );
    }

    /// Every rendered profile frame finishes through the reclaiming helper,
    /// passing the real heap hook. The helper's once-per-call composition is
    /// execution-tested; the call itself stays pinned as source text like the
    /// frame-decision test above: the real loop needs attached BPF, which unit
    /// tests cannot drive. Comment-stripped, so keeping the call as a comment
    /// still fails; the `if` count pins the call against an `if false` guard.
    #[test]
    fn rendered_profile_frames_finish_through_the_reclaiming_helper() {
        let source = include_str!("run.rs");
        let profile = source
            .split_once("fn capture_profile(")
            .unwrap()
            .1
            .split_once("fn write_json_report")
            .unwrap()
            .0;
        let render = profile
            .split_once("if tick_frame.render {")
            .unwrap()
            .1
            .split_once("request_profile_recovery_frame(")
            .unwrap()
            .0;
        let code = render
            .lines()
            .map(|line| line.split_once("//").map_or(line, |(code, _)| code))
            .collect::<Vec<_>>()
            .join("\n");
        assert_eq!(
            code.matches("finish_profile_render_frame(").count(),
            1,
            "capture_profile finishes each rendered frame through the helper once"
        );
        assert_eq!(
            code.matches("crate::inventory::reclaim_pass_heap").count(),
            1,
            "the finish call passes the real heap hook"
        );
        assert_eq!(
            code.matches("if ").count(),
            2,
            "the render block holds only its frame-bytes check and the finish call"
        );
    }

    /// Every finished profile frame runs its heap hook exactly once: three
    /// rendered frames with the sink open reclaim three times and keep the
    /// capture running; a closed sink with no file output reclaims, then ends
    /// it; a closed sink with file output keeps running for the report.
    #[test]
    fn finished_profile_frames_reclaim_once_each() {
        use std::cell::Cell;
        let runs = Cell::new(0u64);
        let mut scheduling = SchedulingAccumulator::default();
        let ago = |ms: u64| Instant::now() - Duration::from_millis(ms);
        for _ in 0..3 {
            assert!(
                !finish_profile_render_frame(&mut scheduling, ago(5), true, false, || runs
                    .set(runs.get() + 1),),
                "an open sink keeps the capture running"
            );
        }
        assert_eq!(runs.get(), 3, "each finished frame reclaims exactly once");
        assert!(
            finish_profile_render_frame(&mut scheduling, ago(5), false, false, || runs
                .set(runs.get() + 1),),
            "a closed sink with no file output ends the capture"
        );
        assert_eq!(runs.get(), 4);
        assert!(
            !finish_profile_render_frame(&mut scheduling, ago(5), false, true, || runs
                .set(runs.get() + 1),),
            "a closed sink with file output keeps the capture running"
        );
        assert_eq!(runs.get(), 5);
        assert!(
            scheduling.snapshot(0).phase_ms.render >= 25,
            "each finish accounts its Render phase"
        );
    }

    /// Requested-wait margin at the default ring: one full idle timeout
    /// admits 2 ms x 128k/s = 256 records, far under the default ring.
    /// This bounds the REQUESTED wait only — it is not a scheduling
    /// proof (audit F1: the OS may deschedule past the timeout, and no
    /// arithmetic here observes that). The scheduling claim rests on the
    /// requalification campaign, not this bound.
    #[test]
    fn ready_idle_timeout_margin_at_default_ring() {
        const FASTEST_BURST_PER_S: u128 = 128_000;
        const RECORD_BYTES: u128 =
            (core::mem::size_of::<p11scope_ebpf_common::EventRecord>() + 8) as u128;
        let capacity = u128::from(p11scope_ebpf_common::RING_BYTES) / RECORD_BYTES;
        let worst_case = READY_IDLE_POLL.as_millis() * FASTEST_BURST_PER_S / 1000;
        assert!(
            worst_case * 2 < capacity,
            "idle timeout admits {worst_case} records at {FASTEST_BURST_PER_S}/s, \
             without 2x margin under the {capacity}-record default ring"
        );
    }

    /// A pipe pair for readiness-wait tests: readable end borrowed, write
    /// end owned, both closed on drop.
    fn readiness_pipe() -> (OwnedFd, OwnedFd) {
        let mut fds = [-1; 2];
        // SAFETY: fds points to two writable integers; pipe initializes both.
        assert_eq!(unsafe { libc::pipe(fds.as_mut_ptr()) }, 0);
        // SAFETY: successful pipe returned two distinct owned descriptors.
        unsafe { (OwnedFd::from_raw_fd(fds[0]), OwnedFd::from_raw_fd(fds[1])) }
    }

    fn write_byte(writer: &OwnedFd) {
        // SAFETY: one initialized byte; the write end is open.
        assert_eq!(
            unsafe { libc::write(writer.as_raw_fd(), [7u8].as_ptr().cast(), 1) },
            1
        );
    }

    /// The readiness wait wakes on data, not on the timeout: a readable
    /// fd with a huge timeout returns immediately. A sleep-the-timeout
    /// implementation fails this (it would wait out the full timeout),
    /// which is exactly the audit F1 mutant this pins against.
    #[test]
    fn ready_wait_returns_early_on_readable_fd() {
        use std::os::fd::AsFd as _;
        let (reader, writer) = readiness_pipe();
        write_byte(&writer);
        let start = Instant::now();
        wait_until_ready(&[reader.as_fd()], Duration::from_secs(30));
        assert!(
            start.elapsed() < Duration::from_secs(10),
            "readiness wait sat out the timeout on a readable fd"
        );
    }

    /// Data arriving mid-wait wakes the wait: a writer after ~100 ms with
    /// a 30 s timeout returns in well under the timeout.
    #[test]
    fn ready_wait_wakes_on_mid_wait_data() {
        use std::os::fd::AsFd as _;
        let (reader, writer) = readiness_pipe();
        let delayed = std::thread::spawn(move || {
            std::thread::sleep(Duration::from_millis(100));
            write_byte(&writer);
        });
        let start = Instant::now();
        wait_until_ready(&[reader.as_fd()], Duration::from_secs(30));
        assert!(
            start.elapsed() < Duration::from_secs(10),
            "readiness wait missed data that arrived mid-wait"
        );
        delayed.join().unwrap();
    }

    /// An empty fd waits out (approximately) the timeout and returns, so
    /// the idle cadence is preserved when nothing arrives — and the wait
    /// never spins: it blocks for most of the timeout.
    #[test]
    fn ready_wait_empty_fd_times_out() {
        use std::os::fd::AsFd as _;
        let (reader, _writer) = readiness_pipe();
        let start = Instant::now();
        wait_until_ready(&[reader.as_fd()], Duration::from_millis(200));
        let elapsed = start.elapsed();
        assert!(
            elapsed >= Duration::from_millis(100),
            "readiness wait returned without blocking on an empty fd: {elapsed:?}"
        );
        assert!(
            elapsed < Duration::from_secs(10),
            "readiness wait overran its timeout: {elapsed:?}"
        );
    }

    /// RB-2: the idle wait watches the DISCOVERY ring beside EVENTS, so a
    /// filling discovery ring wakes the loop to stage it instead of waiting
    /// out the tick.
    #[test]
    fn ready_wait_wakes_on_either_ring() {
        use std::os::fd::AsFd as _;
        let (events, _events_writer) = readiness_pipe();
        let (discovery, discovery_writer) = readiness_pipe();
        write_byte(&discovery_writer);
        let start = Instant::now();
        wait_until_ready(
            &[events.as_fd(), discovery.as_fd()],
            Duration::from_secs(30),
        );
        assert!(
            start.elapsed() < Duration::from_secs(10),
            "a readable discovery ring did not wake the wait"
        );
    }

    /// M-1: the loop-end discovery loss is the producer's fresh counter, not
    /// the Engine's copy from its last batch, which missed loss produced in
    /// the last frame; the copy is only the fallback.
    #[test]
    fn loop_end_discovery_loss_reads_the_producer_fresh() {
        assert_eq!(loop_end_discovery_loss(Ok(9), 4), 9);
        assert_eq!(loop_end_discovery_loss(Err(anyhow!("read failed")), 4), 4);
        assert_eq!(loop_end_discovery_loss(Ok(3), 4), 4, "never less than seen");
    }

    /// RB-2: both capture loops stage the discovery ring on every tick,
    /// immediately before their one readiness wait.
    #[test]
    fn capture_loops_stage_discovery_every_tick() {
        let source = include_str!("run.rs");
        for (start, end) in [
            ("fn capture_profile(", "fn write_json_report"),
            ("fn capture_trace(", "fn terminal_trace_count_line"),
        ] {
            let body = source
                .split_once(start)
                .unwrap()
                .1
                .split_once(end)
                .unwrap()
                .0;
            // Either the single-quantum staging call or the rounds drain
            // that re-polls it: both stage the ring on this tick.
            let stage = ["session.stage_discovery(", "drain_discovery_rounds("]
                .into_iter()
                .filter_map(|marker| body.find(marker))
                .min()
                .unwrap_or_else(|| panic!("{start} never stages discovery"));
            let wait = body.find("wait_until_ready(").unwrap();
            assert!(stage < wait, "{start} stages before its readiness wait");
            assert!(
                body[stage..wait].matches(';').count() <= 2,
                "{start} stages right before the wait"
            );
        }
    }

    /// The poll timeout rounds up: exact milliseconds pass through, a
    /// nonzero sub-millisecond timeout waits 1 ms rather than
    /// truncating to `poll(0)`, and only zero maps to zero (which
    /// `wait_until_ready` short-circuits before polling anyway).
    #[test]
    fn poll_timeout_rounds_sub_millisecond_up() {
        assert_eq!(poll_timeout_ms(Duration::ZERO), 0);
        assert_eq!(poll_timeout_ms(Duration::from_nanos(1)), 1);
        assert_eq!(poll_timeout_ms(Duration::from_micros(500)), 1);
        assert_eq!(poll_timeout_ms(Duration::from_millis(1)), 1);
        assert_eq!(poll_timeout_ms(Duration::from_millis(200)), 200);
        assert_eq!(poll_timeout_ms(Duration::from_secs(30)), 30_000);
        assert_eq!(poll_timeout_ms(Duration::MAX), i32::MAX);
    }

    /// Zero timeout never blocks, even on an empty fd: the backlog path
    /// keeps its no-sleep contract exactly.
    #[test]
    fn ready_wait_zero_timeout_never_blocks() {
        use std::os::fd::AsFd as _;
        let (reader, _writer) = readiness_pipe();
        let start = Instant::now();
        wait_until_ready(&[reader.as_fd()], Duration::ZERO);
        assert!(
            start.elapsed() < Duration::from_secs(5),
            "zero readiness wait blocked"
        );
    }

    /// The cancel marker is the harness's control-latency signal: exact
    /// text, signal number, and tick count, printed before detach work.
    #[test]
    fn cancel_marker_names_the_signal_and_tick_count() {
        assert_eq!(
            cancel_marker(Some(2), 42),
            "p11scope: cancel: loop exited on signal 2 after 42 ticks"
        );
    }

    /// The readiness line is the contract scripts wait on (the live frame is
    /// TTY-only): it must name the attached probe count and how to stop.
    #[test]
    fn capture_ready_line_names_probes_and_how_to_stop() {
        assert_eq!(
            capture_ready_line(136, false),
            "p11scope: capturing: 136 probes attached; stop with Ctrl-C"
        );
        assert_eq!(
            capture_ready_line(1, false),
            "p11scope: capturing: 1 probe attached; stop with Ctrl-C"
        );
    }

    /// The startup line precedes the readiness line: every live
    /// capture prints it on stderr before the slow discovery/attach
    /// work, so the run never looks hung. It carries the same stop
    /// hint but a distinct needle — harnesses keep waiting for
    /// `p11scope: capturing: `, which an earlier extra line does not
    /// break.
    #[test]
    fn starting_line_precedes_ready_line() {
        assert_eq!(
            capture_starting_line(),
            "p11scope: starting: loading probes and scanning processes \
             (a busy machine can take a minute or more); stop with Ctrl-C"
        );
        let ready = capture_ready_line(136, false);
        assert!(
            ready.starts_with("p11scope: capturing: "),
            "the readiness needle keeps its prefix: {ready}"
        );
        assert!(
            !capture_starting_line().contains("capturing: "),
            "the startup line must not trip the readiness needle"
        );
    }

    #[test]
    fn target_caller_line_names_pid_and_exe() {
        let caller = render::CaptureCaller {
            exe: Some("/opt/target/harness".to_string()),
            exe_unknown_reason: None,
            exec_from_exe: None,
        };
        assert_eq!(
            target_caller_line(4242, &caller),
            "p11scope: target: pid 4242 exe /opt/target/harness"
        );
    }

    #[test]
    fn target_caller_line_names_unknown_reason() {
        for reason in [TARGET_CALLER_EXITED, TARGET_CALLER_EXE_UNREADABLE] {
            let caller = render::CaptureCaller {
                exe: None,
                exe_unknown_reason: Some(reason),
                exec_from_exe: None,
            };
            assert_eq!(
                target_caller_line(4242, &caller),
                format!("p11scope: target: pid 4242 caller unknown: {reason}")
            );
        }
    }

    #[test]
    fn target_caller_line_escapes_exe_controls() {
        // The exe is target-controlled: control bytes are rewritten at
        // this terminal boundary, never printed raw.
        let caller = render::CaptureCaller {
            exe: Some("/tmp/x\x1b[1m".to_string()),
            exe_unknown_reason: None,
            exec_from_exe: None,
        };
        let line = target_caller_line(4242, &caller);
        assert!(!line.contains('\x1b'), "{line}");
        assert!(line.contains("pid 4242 exe /tmp/x"), "{line}");
    }

    #[test]
    fn target_exec_line_names_pid_and_both_exes() {
        // The end-of-capture stderr note after a mid-capture exec: the
        // operator's own target pid beside the program that made the calls,
        // with the attach-time program beside it.
        let line = target_exec_line(4242, "/usr/bin/bash", "/usr/bin/pkcs11-tool");
        assert_eq!(
            line,
            "p11scope: target: pid 4242 exe /usr/bin/pkcs11-tool \
             (exec'd from /usr/bin/bash during the capture)"
        );
    }

    #[test]
    fn target_exec_line_escapes_both_exes_controls() {
        // Both exes are target-controlled: control bytes are rewritten at
        // this terminal boundary, never printed raw.
        let line = target_exec_line(4242, "/tmp/old\x07", "/tmp/new\x1b[1m");
        assert!(!line.contains('\x1b'), "{line}");
        assert!(!line.contains('\x07'), "{line}");
        assert!(line.contains("pid 4242 exe /tmp/new"), "{line}");
        assert!(line.contains("/tmp/old"), "{line}");
    }

    #[test]
    fn resolve_pid_caller_with_names_all_outcomes() {
        // Named: the link text wins without consulting the exit proof.
        let named = resolve_pid_caller_with(
            7,
            |_| Some("/bin/app".to_string()),
            |_| panic!("a readable link never consults the exit proof"),
            || true,
        );
        assert_eq!(named.exe.as_deref(), Some("/bin/app"));
        assert_eq!(named.exe_unknown_reason, None);
        // Unreadable plus proven exit: the exit is named.
        let exited = resolve_pid_caller_with(7, |_| None, |_| true, || true);
        assert_eq!(exited.exe, None);
        assert_eq!(exited.exe_unknown_reason, Some(TARGET_CALLER_EXITED));
        // Unreadable but live: unreadable, never presumed exited.
        let hidden = resolve_pid_caller_with(7, |_| None, |_| false, || true);
        assert_eq!(hidden.exe, None);
        assert_eq!(
            hidden.exe_unknown_reason,
            Some(TARGET_CALLER_EXE_UNREADABLE)
        );
        // Changed generation: a readable link is discarded, never
        // misattached, and the exit is named without consulting the
        // proof.
        let changed = resolve_pid_caller_with(
            7,
            |_| Some("/bin/recycled".to_string()),
            |_| panic!("a changed generation never consults the exit proof"),
            || false,
        );
        assert_eq!(changed.exe, None);
        assert_eq!(changed.exe_unknown_reason, Some(TARGET_CALLER_EXITED));
        // Changed under the read: same discard when the bracket fails
        // after the link was already read.
        let mut first = true;
        let raced = resolve_pid_caller_with(
            7,
            |_| Some("/bin/recycled".to_string()),
            |_| panic!("a changed generation never consults the exit proof"),
            || std::mem::replace(&mut first, false),
        );
        assert_eq!(raced.exe, None);
        assert_eq!(raced.exe_unknown_reason, Some(TARGET_CALLER_EXITED));
    }

    #[test]
    fn resolve_pid_caller_names_live_self() {
        // The real reader over a pid that is certainly alive and
        // readable: this test process names its own exe.
        let caller = resolve_pid_caller(std::process::id(), None);
        let exe = caller.exe.as_deref().unwrap_or_default();
        assert!(!exe.is_empty(), "{caller:?}");
        assert_eq!(caller.exe_unknown_reason, None);
    }

    #[test]
    fn resolve_pid_caller_with_pin_names_live_self() {
        // The pin-bound reader over a live pin names the same exe: the
        // bracket passes through when the generation is unchanged.
        let pin =
            crate::process::PidPin::open(std::process::id()).expect("pinning the test process");
        let caller = resolve_pid_caller(std::process::id(), Some(&pin));
        let exe = caller.exe.as_deref().unwrap_or_default();
        assert!(!exe.is_empty(), "{caller:?}");
        assert_eq!(caller.exe_unknown_reason, None);
    }

    #[test]
    fn resolve_pid_caller_names_unreaped_zombie_exited() {
        // A zombie answers `kill(pid, 0)` but its exe link is gone: the
        // exit must be named, never misreported as hidepid/unreadable —
        // both unpinned (the stat verdict) and through the real pin held
        // across the kill (the pidfd poll verdict where pidfd applies).
        let mut child = std::process::Command::new("sleep")
            .arg("30")
            .die_with_parent()
            .spawn()
            .expect("spawning the zombie fixture");
        let pid = child.id();
        let pin = crate::process::PidPin::open(pid).expect("pinning the live child");
        child.kill().expect("killing the zombie fixture");
        let deadline = Instant::now() + Duration::from_secs(5);
        while !crate::process::process_is_zombie(pid) && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(5));
        }
        assert!(
            crate::process::process_is_zombie(pid),
            "the killed child is unreaped"
        );
        let caller = resolve_pid_caller(pid, None);
        let pinned = resolve_pid_caller(pid, Some(&pin));
        child.wait().expect("reaping the zombie fixture");
        assert_eq!(caller.exe, None, "{caller:?}");
        assert_eq!(
            caller.exe_unknown_reason,
            Some(TARGET_CALLER_EXITED),
            "{caller:?}"
        );
        assert_eq!(pinned.exe, None, "{pinned:?}");
        assert_eq!(
            pinned.exe_unknown_reason,
            Some(TARGET_CALLER_EXITED),
            "{pinned:?}"
        );
    }

