    /// Startup T2: both capture loops emit the ready line before the
    /// gated loader-readiness line. The loops need a live session, so
    /// the order is pinned statically.
    #[test]
    fn both_capture_loops_emit_readiness_after_the_ready_line() {
        let source = include_str!("run.rs");
        let production = source.split_once("#[cfg(test)]\nmod tests").unwrap().0;
        let profile = production
            .split_once("fn capture_profile(")
            .expect("profile loop")
            .1
            .split_once("fn capture_trace(")
            .expect("trace loop bounds the profile loop")
            .0;
        let trace = production
            .split_once("fn capture_trace(")
            .expect("trace loop")
            .1
            .split_once("fn terminal_trace_count_line(")
            .expect("terminal line bounds the trace loop")
            .0;
        for (name, body) in [("profile", profile), ("trace", trace)] {
            let mut pos = 0;
            for marker in [
                "capture_ready_line(",
                "loader_readiness_hooks(",
                "loader_readiness_line(",
                "startup_hook_recount_line(",
            ] {
                let at = body[pos..]
                    .find(marker)
                    .unwrap_or_else(|| panic!("{name} loop lacks {marker}"));
                pos += at + marker.len();
            }
        }
    }

    /// Per-scope initial-arming order: a `--pid` capture completes the
    /// deferred initial arming (and, in profile, the endpoint selection)
    /// before the `capturing:` line, so it has no post-ready window;
    /// `--system`/`--cgroup` keep the completion after the ready line.
    /// Both loops re-sync their plan consumers after the completion —
    /// its cleanup pass can change the plan silently (no plan-changed
    /// tick fires for it), so the semantic state, the tracer, the trace
    /// header and the endpoint selection all resolve against the
    /// post-completion plan, exactly as when the start armed inline.
    /// The completion's stop check honours the `--duration` deadline
    /// beside Ctrl-C, so a short duration is not spent inside arming
    /// and then overrun. The loops need a live session, so the order
    /// is pinned statically; the acceptance transcripts prove it runs.
    #[test]
    fn capture_loops_arm_before_ready_for_pid_and_after_for_wide_scopes() {
        let source = include_str!("run.rs");
        let production = source.split_once("#[cfg(test)]\nmod tests").unwrap().0;
        assert_eq!(
            production.matches("complete_initial_arming(").count(),
            2,
            "the profile and trace loops each complete once"
        );
        let profile = production
            .split_once("fn capture_profile(")
            .expect("profile loop")
            .1
            .split_once("fn capture_trace(")
            .expect("trace loop bounds the profile loop")
            .0;
        let trace = production
            .split_once("fn capture_trace(")
            .expect("trace loop")
            .1
            .split_once("fn terminal_trace_count_line(")
            .expect("terminal line bounds the trace loop")
            .0;
        // Each chain ends at the hook recount: the only other syncs
        // sit in the terminal paths past it, so a missing re-sync fails
        // the chain instead of matching a later one.
        for (name, body, syncs) in [
            ("profile", profile, &["state.sync_plan("][..]),
            (
                "trace",
                trace,
                &["state.sync_plan(", "tracer.sync_plan("][..],
            ),
        ] {
            let mut markers = vec![
                "let arm_before_ready = matches!(scope, Scope::Pid(_));",
                "if !arm_before_ready {",
                "capture_ready_line(",
                "complete_initial_arming(",
            ];
            markers.extend_from_slice(syncs);
            if name == "profile" {
                // The selection sits between the completion and the
                // pid-scope ready line: its detail window is open
                // before `capturing:` on that path.
                markers.push("run_metrics_selection_stage(");
            }
            markers.extend_from_slice(&[
                "if arm_before_ready {",
                "capture_ready_line(",
                "loader_readiness_hooks(",
            ]);
            let mut pos = 0;
            for marker in markers {
                let at = body[pos..]
                    .find(marker)
                    .unwrap_or_else(|| panic!("{name} loop lacks {marker}"));
                pos += at + marker.len();
            }
            let complete = body.find("complete_initial_arming(").unwrap();
            let call_end = body[complete..]
                .find(")?;")
                .expect("the completion call ends");
            let call = &body[complete..complete + call_end];
            assert!(
                call.contains("interrupted.interrupted()"),
                "{name} completion honours Ctrl-C between views"
            );
            assert!(
                call.contains("duration.is_some_and(|limit| clock.elapsed() >= limit)"),
                "{name} completion honours the duration deadline between views"
            );
        }
        let pid_ready = trace
            .find("if arm_before_ready {")
            .expect("trace emits the pid-scope ready line");
        let header = trace
            .find("trace::header(")
            .expect("trace assembles its header");
        assert!(
            pid_ready < header,
            "the trace header reads the post-completion plan, after the ready line"
        );
    }

    /// Kernel-found work must not promote early frames: under desktop
    /// churn every frame batch queues more unowned pids, so promotion
    /// re-runs the full frame pass at the minimum interval instead of
    /// the drain cadence and starves newcomer admission itself. The
    /// ordinary frame cadence plus between-frame backlog passes service
    /// newcomers; neither capture loop may move its frame clock for a
    /// discovery hint.
    #[test]
    fn capture_loops_never_promote_frames_for_kernel_found_work() {
        let source = include_str!("run.rs");
        let production = source.split_once("#[cfg(test)]\nmod tests").unwrap().0;
        assert_eq!(
            production.matches("take_fast_discovery_frame(").count(),
            0,
            "no capture loop consumes a fast-frame promotion hint"
        );
        assert_eq!(
            production.matches("request_fast_discovery_frame(").count(),
            0,
            "no capture loop moves its frame clock for kernel-found work"
        );
    }

