    #[test]
    fn system_scope_admits_fork_children_without_a_destination_check() {
        // One fork-safe C_OpenSession slot so the parent can hold an open
        // session the child must inherit.
        let names = vec!["C_OpenSession".to_string()];
        let (descriptor_index, semantic_ambiguous) = crate::kinds::descriptor_index(&names);
        let plan = crate::plan::AttachPlan::from_slots(vec![crate::plan::Slot {
            index: 0,
            descriptor_index,
            object: crate::plan::TEST_PINNED_OBJECT,
            object_path: "/opt/p11.so".into(),
            file_offset: 0,
            names,
            aliased: false,
            semantics: crate::kinds::DESCRIPTORS[descriptor_index as usize],
            semantic_authorized: true,
            semantic_ambiguous,
            fork_safe: true,
            module_ids: vec![crate::plan::ModuleId(0)],
        }]);
        let mut state = semantics::State::new(&plan);
        let mut tracker =
            process::Tracker::for_producer(crate::events::EventsDomain::test_standin(1), 16);
        let domain = tracker.producer_domain();
        let parent_image = p11scope_ebpf_common::ImageIdentity {
            task_cookie: 90,
            exec_id: 0,
        };
        let (parent, _) = tracker.admit_history(domain, 100, parent_image);
        let parent = parent.expect("parent generation admits");
        // Parent opens one session before forking.
        let mut call: p11scope_ebpf_common::Event = unsafe { std::mem::zeroed() };
        call.event_type = p11scope_ebpf_common::event_type::CALL;
        call.pid_tgid = 100u64 << 32;
        call.session = 7;
        call.slot = 0;
        call.rv = 0;
        call.image = parent_image;
        state.observe_process(parent, &call);
        assert_eq!(state.sessions().opened, 1);
        // Genuine birth: distinct child pid and distinct nonzero cookies.
        let mut fork: p11scope_ebpf_common::Event = unsafe { std::mem::zeroed() };
        fork.event_type = p11scope_ebpf_common::event_type::FORK;
        fork.pid_tgid = 100u64 << 32;
        fork.session = 200;
        fork.image = parent_image;
        fork.child_image = p11scope_ebpf_common::ImageIdentity {
            task_cookie: 20,
            exec_id: 0,
        };
        assert!(observe_fork(
            domain,
            &mut tracker,
            &mut state,
            &Scope::System,
            &fork
        ));
        assert_eq!(
            state.semantic_evidence().semantic_history_drops,
            0,
            "genuine fork must admit without history rejection"
        );
        assert_eq!(
            state.sessions().inherited,
            1,
            "child must inherit the parent open session"
        );
        // Birth is one-shot: replaying it must not duplicate the inheritance.
        assert!(observe_fork(
            domain,
            &mut tracker,
            &mut state,
            &Scope::System,
            &fork
        ));
        assert_eq!(state.sessions().inherited, 1);
        // Negative control: the old malformed shape (same pid, zero cookies)
        // is handled but records a rejection.
        let drops_before = state.semantic_evidence().semantic_history_drops;
        let mut malformed: p11scope_ebpf_common::Event = unsafe { std::mem::zeroed() };
        malformed.event_type = p11scope_ebpf_common::event_type::FORK;
        malformed.pid_tgid = 100u64 << 32;
        malformed.session = 100;
        assert!(observe_fork(
            domain,
            &mut tracker,
            &mut state,
            &Scope::System,
            &malformed
        ));
        assert_eq!(
            state.semantic_evidence().semantic_history_drops,
            drops_before + 1,
            "malformed fork must record a rejection"
        );
    }

    /// P2 (container lanes): GNU `timeout -s INT` without `--foreground`
    /// sends SIGINT to its child and then to the child's process group, so
    /// the observer receives the same stop twice within microseconds. That
    /// is one stop request, not the operator's second Ctrl-C — which would
    /// abandon cleanup ("cleanup incomplete", exit 130). A genuinely later
    /// second SIGINT still escalates.
    #[test]
    fn an_immediate_duplicate_sigint_is_one_stop_request() {
        const T0: u64 = 5_000_000_000;
        let state = SignalState::new();
        state.observe_delivery(libc::SIGINT, Some(T0));
        state.observe_delivery(libc::SIGINT, Some(T0 + 20_000));
        assert_eq!(state.first_signal(), Some(libc::SIGINT));
        assert_eq!(state.sigint_deliveries(), 1, "a 20 us duplicate escalated");
        // Two handlers on two threads can stamp out of order.
        state.observe_delivery(libc::SIGINT, Some(T0 - 5_000));
        assert_eq!(
            state.sigint_deliveries(),
            1,
            "an out-of-order duplicate escalated"
        );
        state.observe_delivery(
            libc::SIGINT,
            Some(T0 + DUPLICATE_STOP_WINDOW.as_nanos() as u64 + 1),
        );
        assert_eq!(
            state.sigint_deliveries(),
            2,
            "a later Ctrl-C must still escalate"
        );

        // A preceding SIGTERM does not make the first SIGINT a duplicate.
        let state = SignalState::new();
        state.observe_delivery(libc::SIGTERM, Some(T0));
        state.observe_delivery(libc::SIGINT, Some(T0 + 1_000));
        assert_eq!(state.first_signal(), Some(libc::SIGTERM));
        assert_eq!(state.sigint_deliveries(), 1);
    }

    /// The real handler stamps every delivery, so the coalescing above is
    /// what production runs; `observe` (no stamp) stays test-only.
    #[test]
    fn the_stop_handler_stamps_each_delivery_with_the_monotonic_clock() {
        let source = include_str!("run.rs");
        let install = source
            .split_once("fn install_stop_flag()")
            .unwrap()
            .1
            .split_once("\n}\n")
            .unwrap()
            .0;
        assert!(
            install.contains("observed.observe_delivery(recorded, crate::attach::monotonic_ns())"),
            "{install}"
        );
        let production = source.split_once("#[cfg(test)]\nmod tests").unwrap().0;
        assert!(
            !production.contains(".observe(recorded)"),
            "unstamped handler"
        );
    }

    #[test]
    fn signal_state_retains_first_identity_and_saturates_sigint_deliveries() {
        let state = SignalState::new();
        state.observe(libc::SIGTERM);
        state.observe(libc::SIGINT);
        state.observe(libc::SIGINT);
        state.observe(libc::SIGINT);

        assert_eq!(state.first_signal(), Some(libc::SIGTERM));
        assert_eq!(state.sigint_deliveries(), 2);
    }

    /// DR-K8S-1: outside the initial PID namespace `--pid` is refused by
    /// name before discovery; cgroup and system proceed with the warning.
    /// In the initial namespace every scope proceeds silently.
    #[test]
    fn a_pid_scope_outside_the_initial_pid_namespace_is_refused_by_name() {
        use crate::pidns::{ObserverPidNs, PidNumbering, ProcView};
        let scopes = [
            ScopeArg::Pid(42),
            ScopeArg::Cgroup("/sys/fs/cgroup/x".into()),
            ScopeArg::System,
        ];
        for scope in &scopes {
            assert_eq!(
                pid_namespace_preflight(scope, &PidNumbering::agreeing()).unwrap(),
                None,
                "{scope:?}"
            );
        }
        let mismatches = [
            PidNumbering {
                observer: ObserverPidNs::Nested,
                proc_view: ProcView::Own,
            },
            PidNumbering {
                observer: ObserverPidNs::Unknown("gone".into()),
                proc_view: ProcView::Own,
            },
            // M1: initial observer, foreign /proc (`nsenter -m` without -p).
            PidNumbering {
                observer: ObserverPidNs::Initial,
                proc_view: ProcView::Foreign("/proc/self: gone".into()),
            },
        ];
        for observer in mismatches {
            let error = pid_namespace_preflight(&scopes[0], &observer).unwrap_err();
            assert!(
                format!("{error:#}").starts_with("pid-namespace-mismatch: refusing --pid 42: "),
                "{error:#}"
            );
            for scope in &scopes[1..] {
                let warning = pid_namespace_preflight(scope, &observer)
                    .unwrap()
                    .expect("a non-PID scope proceeds with a warning");
                assert!(warning.contains("pid_namespace"), "{warning}");
            }
        }
    }

    /// Finding nothing is not an error, so the only thing that keeps the operator
    /// from a silent empty report is this line naming the two commands that explain.
    #[test]
    fn zero_modules_points_at_inspect_and_doctor() {
        let hint = no_modules_hint(&ScopeArg::Pid(42));
        assert!(
            hint.contains("no PKCS#11 modules discovered in pid 42"),
            "{hint}"
        );
        assert!(hint.contains("p11scope inspect --pid 42"), "{hint}");
        assert!(hint.contains("p11scope doctor --pid 42"), "{hint}");
        let hint = no_modules_hint(&ScopeArg::Cgroup("/sys/fs/cgroup/x".into()));
        assert!(hint.contains("cgroup /sys/fs/cgroup/x"), "{hint}");
        assert!(hint.contains("p11scope inspect --pid"), "{hint}");
        assert!(
            hint.contains("p11scope doctor --cgroup /sys/fs/cgroup/x"),
            "{hint}"
        );
        let hint = no_modules_hint(&ScopeArg::System);
        assert!(hint.contains("system-wide"), "{hint}");
        assert!(hint.contains("p11scope inspect --system"), "{hint}");
        assert!(hint.contains("p11scope inspect --pid"), "{hint}");
        assert!(hint.contains("p11scope doctor"), "{hint}");
    }

    fn empty_profile_plan_for_test() -> crate::plan::AttachPlan {
        crate::plan::AttachPlan::from_slots_with_policy(
            Vec::new(),
            crate::plan::AdmissionPolicy::detailed(),
        )
        .expect("an empty profile plan builds")
    }

    /// P1-3: a plan with zero modules and one `original_file_unproven`
    /// skip (a provider the scan found and the witness refused) names
    /// the found-but-refused provider instead of claiming none found.
    #[test]
    fn an_empty_plan_with_a_refused_provider_names_it_instead_of_claiming_none_found() {
        use crate::discovery::scan::Skipped;
        let mut plan = empty_profile_plan_for_test();
        assert!(plan.modules.is_empty());
        plan.skipped.push(Skipped {
            subject: "/opt/provider/libx.so".into(),
            reason: "original_file_unproven: kernel witness unavailable: no BTF".into(),
        });
        let hint = empty_plan_hint(&ScopeArg::System, &plan);
        assert!(hint.contains("found 1 PKCS#11 provider"), "{hint}");
        assert!(hint.contains("could not count calls"), "{hint}");
        assert!(hint.contains("original_file_unproven"), "{hint}");
        assert!(!hint.contains("no PKCS#11 modules discovered"), "{hint}");
        assert!(hint.contains("p11scope doctor"), "{hint}");
    }

    /// P1-3 twin: a deleted mapping was never opened, so provider-ness
