    /// P1-3 JSON half: a refused-provider skip lands in the document
    /// as a named gap (flattened per the closed vocabulary, which
    /// never names paths), PARTIAL, with the `skipped` cause — the
    /// same refusal the stderr line names in full.
    #[test]
    fn refused_provider_skips_land_in_json_as_named_gaps() {
        use crate::discovery::scan::Skipped;
        let internal = Skipped {
            subject: "/opt/provider/libx.so".into(),
            reason: "original_file_unproven: kernel witness unavailable: no BTF".into(),
        };
        let projected = crate::render::capture_skipped_out(&internal);
        assert_eq!(projected.name, "discovery subject", "{projected:?}");
        let mut ev = crate::render::tests::evidence();
        ev.table_entries = 0;
        ev.slots = 0;
        ev.active_slots = 0;
        ev.attached_probes = 0;
        ev.discovery.modules = Vec::new();
        ev.skipped = vec![projected];
        ev.verdict();
        assert_eq!(ev.completeness, "PARTIAL");
        for cause in ["discovery", "slots", "skipped"] {
            assert!(
                ev.gap_classes.observation.causes.contains(&cause),
                "{:?}",
                ev.gap_classes.observation.causes
            );
        }
        let json = serde_json::to_value(&ev).expect("evidence serializes");
        assert_eq!(json["skipped"][0]["name"], "discovery subject");
        assert_eq!(json["completeness"], "PARTIAL");
    }

    /// An empty capture over a replaced provider names the file on
    /// stderr: one escaped line per distinct file, bounded with a
    /// counted tail; other skips stay silent.
    #[test]
    fn replaced_files_are_named_on_stderr_lines_bounded_and_escaped() {
        use crate::discovery::scan::{REPLACED_PROVIDER_REASON, Skipped};
        let skip = |subject: &str, reason: &str| Skipped {
            subject: subject.into(),
            reason: reason.into(),
        };
        let lines = replaced_file_hint_lines(&[
            skip("/opt/b.so (deleted)", REPLACED_PROVIDER_REASON),
            skip("/opt/a.so (deleted)", REPLACED_PROVIDER_REASON),
            skip("/opt/a.so (deleted)", REPLACED_PROVIDER_REASON),
            skip("capture discovery", "some other reason"),
        ]);
        assert_eq!(lines.len(), 2, "{lines:?}");
        assert!(
            lines[0].contains("/opt/a.so (deleted)") && lines[1].contains("/opt/b.so (deleted)"),
            "distinct files in sorted order, duplicates folded: {lines:?}"
        );
        assert!(
            lines.iter().all(|line| line.contains("calls not counted")),
            "each line carries the reason: {lines:?}"
        );
        let evil = replaced_file_hint_lines(&[skip(
            "/opt/\x07evil.so (deleted)",
            REPLACED_PROVIDER_REASON,
        )]);
        assert_eq!(evil.len(), 1);
        assert!(
            !evil[0].contains('\x07') && evil[0].contains("\\u{7}"),
            "control bytes are escaped: {:?}",
            evil[0]
        );
        let many: Vec<Skipped> = (0..10)
            .map(|n| {
                skip(
                    &format!("/opt/f{n:02}.so (deleted)"),
                    REPLACED_PROVIDER_REASON,
                )
            })
            .collect();
        let bounded = replaced_file_hint_lines(&many);
        assert_eq!(bounded.len(), 9, "{bounded:?}");
        assert!(
            bounded[8].contains("and 2 more replaced files"),
            "the tail counts the rest: {bounded:?}"
        );
        assert!(
            replaced_file_hint_lines(&[skip("capture discovery", "some other reason")]).is_empty(),
            "no replaced reason means no lines"
        );
    }

    /// Capture startup names each distinct replaced file whenever the plan's
    /// skips carry the replaced-file reason — even when other modules did
    /// attach — while the no-modules pointer stays empty-only and a dead
    /// named pid stays silent (its missing-process line speaks instead).
    #[test]
    fn capture_start_lines_name_replaced_files_whenever_skipped() {
        use crate::discovery::scan::{REPLACED_PROVIDER_REASON, Skipped};
        let skip = |subject: &str, reason: &str| Skipped {
            subject: subject.into(),
            reason: reason.into(),
        };
        let replaced = skip("/opt/r.so (deleted)", REPLACED_PROVIDER_REASON);
        let other = skip("capture discovery", "some other reason");
        let scope = ScopeArg::Pid(42);
        let empty = capture_start_hint_lines(
            Some(no_modules_hint(&scope)),
            false,
            std::slice::from_ref(&replaced),
        );
        assert_eq!(empty.len(), 2, "{empty:?}");
        assert!(
            empty[0].contains("no PKCS#11 modules discovered in pid 42"),
            "the empty capture keeps its pointer first: {empty:?}"
        );
        assert!(
            empty[1].contains("/opt/r.so (deleted)"),
            "the empty capture names the file: {empty:?}"
        );
        let attached = capture_start_hint_lines(None, false, std::slice::from_ref(&replaced));
        assert_eq!(attached.len(), 1, "{attached:?}");
        assert!(
            attached[0].contains("/opt/r.so (deleted)"),
            "an attached capture still names the replaced file: {attached:?}"
        );
        assert!(
            !attached[0].contains("no PKCS#11 modules"),
            "an attached capture never prints the no-modules pointer: {attached:?}"
        );
        assert!(
            capture_start_hint_lines(None, false, &[other]).is_empty(),
            "other skips stay silent when modules attached"
        );
        assert!(
            capture_start_hint_lines(
                Some(no_modules_hint(&scope)),
                true,
                std::slice::from_ref(&replaced)
            )
            .is_empty(),
            "a dead named pid stays silent on the empty path"
        );
        assert!(
            capture_start_hint_lines(None, true, &[replaced]).is_empty(),
            "a dead named pid stays silent on the attached path"
        );
    }

    /// `inspect` propagates a hard error for a pid that names nothing; it must reach
    /// the operator as one line and exit 1, never as a panic or a backtrace dump.
    #[test]
    fn inspect_on_a_nonexistent_pid_is_one_line_and_not_a_panic() {
        // Above /proc/sys/kernel/pid_max on every supported kernel.
        let error = crate::inspect::run(
            crate::cli::InspectScope::Pid(0x7fff_fff0),
            &[],
            &[],
            &crate::discovery::hooks::HookRegistry::builtin(),
            false,
            None,
        )
        .expect_err("a pid that names nothing cannot be inspected");
        let rendered = format!("{error:#}");
        assert_eq!(rendered.lines().count(), 1, "{rendered}");
        assert!(rendered.contains("2147483632"), "{rendered}");
    }

    /// The finalization a stopped loop runs into: `-o` publication produces
    /// valid JSON and replaces stale content atomically (adapted from the
    /// previous shutdown-path test).
    #[test]
    fn shutdown_path_publishes_valid_json_over_a_stale_file() {
        let dir = tempfile::tempdir().unwrap();
        let mut permissions = std::fs::metadata(dir.path()).unwrap().permissions();
        permissions.set_mode(0o700);
        std::fs::set_permissions(dir.path(), permissions).unwrap();
        let path = dir.path().join("observed.json");
        std::fs::write(&path, b"stale trailing bytes that must disappear").unwrap();
        let j = serde_json::json!({"schema": "p11scope/observed-profile/v3", "evidence": {}});
        let mut out = AtomicFile::create(&path).unwrap();
        write_json_report(out.file(), &j).expect("shutdown finalization must write the report");
        out.commit().unwrap();
        let parsed: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
        assert_eq!(parsed["schema"], "p11scope/observed-profile/v3");
    }

    /// Healthy twin: a good frame and a good `-o` write publish with no
    /// rescue bytes on stdout. The frame result comes from the real
    /// `write_stdout`/`flush_stdout`, like every twin below.
    #[test]
    fn terminal_publish_succeeds_when_frame_and_report_are_healthy() {
        use std::cell::Cell;
        let mut frame_sink = Vec::new();
        let mut frame_open = true;
        let frame_error = write_stdout(&mut frame_sink, &mut frame_open, b"frame\n")
            .and_then(|()| flush_stdout(&mut frame_sink, &mut frame_open))
            .err();
        assert!(frame_error.is_none());
        let json = serde_json::json!({"schema": "p11scope/observed-profile/v3"});
        let attempted = Cell::new(false);
        let mut sink = Vec::new();
        let mut sink_open = true;
        publish_profile_report_with_fallback(
            &mut sink,
            &mut sink_open,
            &json,
            Some(Path::new("observed.json")),
            || {
                attempted.set(true);
                Ok(())
            },
            frame_error,
        )
        .expect("healthy sinks publish");
        assert!(attempted.get(), "the -o write ran");
        assert!(sink.is_empty(), "no rescue bytes on the healthy path");
    }

    /// A hard stdout failure on the live frame still attempts the `-o`
    /// write; the frame failure surfaces after the report publishes.
    #[test]
    fn terminal_publish_still_attempts_the_report_after_a_hard_frame_error() {
        use std::cell::Cell;
        let mut broken = FailingWriter {
            kind: std::io::ErrorKind::Other,
            fail_flush: false,
        };
        let mut frame_open = true;
        let frame_error = write_stdout(&mut broken, &mut frame_open, b"frame\n").err();
        assert!(frame_error.is_some(), "the injected frame write must fail");
        let json = serde_json::json!({"schema": "p11scope/observed-profile/v3"});
        let attempted = Cell::new(false);
        let mut sink = Vec::new();
        let mut sink_open = true;
        let error = publish_profile_report_with_fallback(
            &mut sink,
            &mut sink_open,
            &json,
            Some(Path::new("observed.json")),
            || {
                attempted.set(true);
                Ok(())
            },
            frame_error,
        )
        .expect_err("the frame failure still surfaces");
        assert!(attempted.get(), "the -o write runs despite the frame error");
        let text = format!("{error:#}");
        assert!(text.contains("writing stdout"), "{text}");
    }

    /// A failed `-o` write rescues the rendered document to stdout as one
    /// compact JSON document on its own line, marked inside with the
    /// failed path, and still exits nonzero naming the `-o` error.
    #[test]
    fn terminal_publish_rescues_the_rendered_report_to_stdout_when_output_fails() {
        let json = serde_json::json!({"schema": "p11scope/observed-profile/v3", "n": 1});
        let mut sink = Vec::new();
        let mut sink_open = true;
        let error = publish_profile_report_with_fallback(
            &mut sink,
            &mut sink_open,
            &json,
            Some(Path::new("/tmp/observed.json")),
            || Err(anyhow!("simulated disk-full on -o write")),
            None,
        )
        .expect_err("the -o failure still exits nonzero");
        let text = format!("{error:#}");
        assert!(text.contains("simulated disk-full"), "{text}");
        let mut expected = serde_json::json!({"schema": "p11scope/observed-profile/v3", "n": 1});
        expected["delivery"] = serde_json::json!({
            "rescued_after_output_failure": "/tmp/observed.json",
            "output_error": "simulated disk-full on -o write",
        });
        let mut framed = vec![b'\n'];
        serde_json::to_writer(&mut framed, &expected).unwrap();
        framed.push(b'\n');
        assert_eq!(
            sink, framed,
            "the rendered document is rescued as one marked compact line"
        );
        // Machine-separable on stdout alone: exactly one JSON line.
        assert_eq!(sink.first(), Some(&b'\n'));
        assert_eq!(sink.last(), Some(&b'\n'));
        let inner = &sink[1..sink.len() - 1];
        assert!(
            !inner.contains(&b'\n'),
            "the rescued document is one line even without stderr"
        );
        let parsed: serde_json::Value = serde_json::from_slice(inner).unwrap();
        assert_eq!(parsed, expected);
        assert_eq!(parsed["n"], 1, "the rendered payload survives the rescue");
        assert_eq!(
            parsed["delivery"]["rescued_after_output_failure"],
            "/tmp/observed.json"
        );
        assert!(
            parsed["delivery"]["output_error"]
                .as_str()
                .unwrap()
                .contains("simulated disk-full"),
            "the rescue names its -o cause inside the document: {parsed}"
        );
    }

    /// A rescue shed by backpressure is drained and named: the terminal
    /// tick budget is spent (the frame already used it), the socket buffer
    /// is full, so the rescue flush drops with counters. The drop
    /// accounting must still run on the `Err` path and the returned error
    /// must name the shed — the JSON is already sealed, so stderr/error
    /// text is the only honest record.
    #[test]
    fn terminal_publish_names_a_rescue_shed_under_backpressure() {
        use std::io::Write as _;
        use std::os::unix::net::UnixStream;
        let (writer, reader) = UnixStream::pair().unwrap();
        // Fill the socket buffer so no reader drains: the bounded flush
        // must time out instead of blocking.
        let mut filler = writer.try_clone().unwrap();
        filler.set_nonblocking(true).unwrap();
        let chunk = vec![7u8; 65536];
        while filler.write(&chunk).is_ok() {}
        let mut sink = crate::sink::SinkWriter::new(writer).unwrap();
        // Spent terminal budget: the frame already used the tick's 250 ms.
        sink.begin_tick(std::time::Duration::ZERO);
        let mut sink_open = true;
        let mut scheduling = SchedulingAccumulator::default();
        let json = serde_json::json!({"schema": "p11scope/observed-profile/v3", "n": 1});
        let error = publish_profile_report_with_drop_accounting(
            &mut sink,
            &mut sink_open,
            &mut scheduling,
            &json,
            Some(Path::new("/tmp/observed.json")),
            || Err(anyhow!("simulated disk-full on -o write")),
            None,
        )
        .expect_err("the -o failure still exits nonzero");
        let text = format!("{error:#}");
        assert!(text.contains("simulated disk-full"), "{text}");
        assert!(
            text.contains("shed") && text.contains("stdout fallback"),
            "a backpressure shed rescue names its loss: {text}"
        );
        assert!(
            scheduling.sink_dropped_bytes > 0 && scheduling.sink_timeouts > 0,
            "the rescue shed is drained into the accumulator: {} bytes in {} timeouts",
            scheduling.sink_dropped_bytes,
            scheduling.sink_timeouts
        );
        assert_eq!(
            sink.take_drops(),
            crate::sink::SinkDrops::default(),
            "the post-publish drain ran even on the rescue path"
        );
        drop(reader);
    }

    /// Both sinks failing surfaces both errors; stdout just hard-failed
    /// on the frame, so no rescue is retried to the same fd.
    #[test]
    fn terminal_publish_combines_frame_and_report_failures_without_a_doomed_retry() {
        use std::cell::Cell;
        let mut sink = FailAfterLines {
            allowed_lines: 0,
            bytes: Vec::new(),
            attempts: Vec::new(),
        };
        let mut sink_open = true;
        let frame_error = write_stdout(&mut sink, &mut sink_open, b"frame\n").err();
        assert!(frame_error.is_some(), "the injected frame write must fail");
        assert_eq!(sink.attempts.len(), 1);
        let json = serde_json::json!({"schema": "p11scope/observed-profile/v3"});
        let attempted = Cell::new(false);
        let error = publish_profile_report_with_fallback(
            &mut sink,
            &mut sink_open,
            &json,
            Some(Path::new("observed.json")),
            || {
                attempted.set(true);
                Err(anyhow!("simulated disk-full on -o write"))
            },
            frame_error,
        )
        .expect_err("both failures surface");
        assert!(attempted.get(), "the -o write runs despite the frame error");
        assert_eq!(
            sink.attempts.len(),
            1,
            "no rescue retry to the just-failed stdout"
        );
        let text = format!("{error:#}");
        assert!(text.contains("simulated disk-full"), "{text}");
        assert!(text.contains("writing stdout"), "{text}");
    }

    /// A failed `-o` write after stdout already closed (EPIPE) cannot
    /// rescue anywhere; the error says stdout is closed.
    #[test]
    fn terminal_publish_reports_a_closed_stdout_when_output_fails_after_epipe() {
        let mut broken = FailingWriter {
            kind: std::io::ErrorKind::BrokenPipe,
            fail_flush: false,
        };
        let mut sink_open = true;
        let frame_error = write_stdout(&mut broken, &mut sink_open, b"frame\n").err();
        assert!(frame_error.is_none(), "EPIPE is tolerated");
        assert!(!sink_open, "EPIPE closes the sink");
        let json = serde_json::json!({"schema": "p11scope/observed-profile/v3"});
        let error = publish_profile_report_with_fallback(
            &mut broken,
            &mut sink_open,
            &json,
            Some(Path::new("observed.json")),
            || Err(anyhow!("simulated disk-full on -o write")),
            frame_error,
        )
        .expect_err("the -o failure still surfaces");
        assert!(!sink_open);
        let text = format!("{error:#}");
        assert!(text.contains("simulated disk-full"), "{text}");
        assert!(text.contains("closed"), "{text}");
    }

